    "about_kicker": "About 2NIGHT",
    "about_title": "Tonight, not tomorrow.",
    "about_lead": "2NIGHT is for the moment you decide at 7pm that you actually want to do something — and want real people near you who feel the same.",
    "about_story_pull": "Most nights die in a group chat. “We should hang out soon.” Soon never comes.",
    "about_story_t": "The night you actually go out",
    "about_story_p1": "2NIGHT was built around one stubborn idea: the best nights aren’t planned three weeks out. They happen because someone, somewhere nearby, is free right now and ready to move. We made the app that turns that impulse into a real plan — fast, in person, tonight.",
    "about_story_p2": "Set your status in one line. See who’s out near you. Ping, match, meet. No endless swiping toward “maybe next week.” Just the people who are out tonight, and the shortest possible path to being in the same room.",
    "about_world_t": "Worldwide, not city-gated",
    "about_world_p1": "2NIGHT isn’t rolling out one city at a time. It works anywhere on earth — with the people near you, wherever you happen to be tonight. Land in a new city and the night is already live.",
    "about_world_p2": "You decide how far it reaches. Choose your radius — from your street to the whole city — and 2NIGHT shows you who’s out inside it.",
    "about_who1_t": "Travellers",
    "about_who1_b": "New city, no contacts, one night to make it count. Open 2NIGHT and the local night is already in front of you.",
    "about_who2_t": "Expats",
    "about_who2_b": "Building a life somewhere new. Meet people who are out tonight in the place you now call home.",
    "about_who3_t": "Locals",
    "about_who3_b": "You know the city — you just want company for tonight. Set your status and find your people, no calendar required.",
    "about_design_t": "Designed for the night",
    "about_design_p": "Warm champagne on deep charcoal. Editorial, quiet, and a little exclusive — built to feel like the best room in the city, not another loud feed. Every screen is made for people who decide late and move fast.",
    "support_kicker": "Support",
    "support_title": "How can we help?",
    "support_lead": "Everything you need to know about 2NIGHT — and a real human at the other end when you need one.",
    "faq_q7": "How do you handle my privacy?",
    "faq_a7": "We collect only what’s needed to help you meet people tonight, and we never sell your personal data. You choose what’s visible to others and when you share location. Read the full details in our Privacy Policy.",
    "faq_a7_link": "Privacy Policy",
    "support_contact_t": "Still need a hand?",
    "support_contact_p": "Email us and a real person will get back to you. We read every message.",
    "nav_safety": "Safety",
    "nav_contact": "Contact",
    "footer_safety": "Safety",
    "footer_contact": "Contact",
    "contact_kicker": "Contact us",
    "screens_disclaimer": "All photos are for illustration only.",
    "android_soon": "Android — available soon",
    "testimonials_kicker": "From the night",
    "testimonials_title": "What our users said about us",
    "testimonials_sub": "Early beta nights, in their own words.",
    "testimonials_note": "Quotes from beta users. Names and cities are representative.",
    "testimonial1_q": "I landed in Lisbon with zero plans. By 9pm I was at a rooftop bar with three people I’d just matched. That’s the whole app in one night.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lisbon",
    "testimonial2_q": "No more “we should hang out soon.” I set my status, saw who was free, and actually met someone the same evening. Finally.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Paris",
    "testimonial3_q": "The Black Events are unreal. It feels less like an app and more like an invite to the best room in the city.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "New city for work, knew no one. Two weeks in I’ve got a real circle — all from deciding at 7pm I didn’t want to stay in.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlin",
    "testimonial5_q": "It’s fast, it’s beautiful, and it actually respects your time. Ping, match, meet — exactly as promised.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "London",
    "testimonial6_q": "Travel Mode is a cheat code. I open 2NIGHT the second I land and the local night is already waiting.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "New York",
    "safety_kicker": "Safety",
    "safety_title": "Meet people the smart way.",
    "safety_lead": "2NIGHT is built for spontaneous, real-life nights. A few simple habits keep them fun — and keep you in control when you meet someone new.",
    "safety_t1_t": "Meet in a public place",
    "safety_t1_b": "For a first meet, pick somewhere busy and well-lit — a bar, a café, a popular spot. Stay in public until you genuinely feel comfortable, and don’t go to a private location with someone you’ve just met.",
    "safety_t2_t": "Tell a friend your plans",
    "safety_t2_b": "Let someone you trust know where you’re going, who you’re meeting, and when you expect to be back. Share your live location with them for the night and check in afterwards.",
    "safety_t3_t": "Arrange your own transport",
    "safety_t3_b": "Get yourself there and back on your own terms. Keep your phone charged, know how you’re getting home, and you’re free to leave whenever you want — no explanation needed.",
    "safety_t4_t": "Never send money",
    "safety_t4_b": "Never send money, gift cards, or crypto to someone you met on the app, no matter the story. Requests for cash, financial help, or investment “tips” are classic scams — stop and report them.",
    "safety_t5_t": "Trust your gut",
    "safety_t5_b": "If something feels off, it probably is. You never owe anyone your time. End the chat, leave the meet, or call a friend — there’s no wrong reason to walk away.",
    "safety_t6_t": "Report & block",
    "safety_t6_b": "Anyone who makes you uncomfortable can be blocked and reported in a tap. Our team reviews reports — flagging bad behaviour keeps the whole night safer for everyone.",
    "safety_t7_t": "Protect your personal info",
    "safety_t7_b": "Keep chats inside 2NIGHT until you trust someone. Don’t share your home address, workplace, financial details, or documents, and be thoughtful about photos that reveal exactly where you live.",
    "safety_t8_t": "You’re in control",
    "safety_t8_b": "You decide when you’re live, how far your radius reaches, and what you share. We don’t run background checks, so your own judgement always comes first.",
    "safety_help_t": "In an emergency, call for help.",
    "safety_help_p": "If you ever feel unsafe or threatened, contact your local emergency services first. To report someone or something to us, email our team — we read every message.",
    "cookie_text": "2NIGHT uses only the cookies needed to make this site work and remember your preferences. We don't load advertising or third-party tracking cookies.",
