    "faq_q1": "2NIGHT est-elle gratuite ?",
    "faq_a1": "Oui. Rejoindre 2NIGHT et faire des rencontres, c’est gratuit. Un abonnement payant arrive, et vous verrez précisément ce qu’il coûte dans l’app avant tout paiement.",
    "faq_q2": "Quand l’appli arrive-t-elle dans ma ville ?",
    "faq_a2": "Nous ouvrons les villes par vagues. Rejoignez la liste d’attente et nous vous préviendrons dès que 2NIGHT sera disponible près de chez vous.",
    "faq_q3": "En quoi est-elle différente des autres applis de rencontre ?",
    "faq_a3": "Fini le swipe à l’infini vers « un jour peut-être ». 2NIGHT vous montre qui sort près de vous maintenant et vous aide à rencontrer pour de vrai — ce soir, pas dans trois semaines.",
    "faq_q4": "Est-ce sécurisé ?",
    "faq_a4": "Vous décidez quand vous êtes visible, jusqu’où s’étend votre rayon et ce que vous partagez. Bloquez et signalez en un geste, et passez hors ligne pour disparaître instantanément. Lisez nos conseils de sécurité avant toute rencontre.",
