    "aria_menu": "Menu",
    "disclaimer_html": "<strong>2NIGHT est réservé aux adultes de 18 ans et plus.</strong> 2NIGHT arrive bientôt ; certaines fonctionnalités et le téléchargement sur l'App Store ne sont peut-être pas encore disponibles dans votre région. Les écrans et les photos de l'application sont donnés à titre d'illustration uniquement, et les témoignages proviennent d'utilisateurs bêta et sont représentatifs. 2NIGHT aide les gens à se rencontrer mais ne réalise <strong>pas</strong> de vérification des antécédents ou de l'identité — veuillez lire nos conseils de <a href=\"/safety\">Sécurité</a> et faire des rencontres de façon responsable. En utilisant 2NIGHT, vous acceptez nos <a href=\"/terms\">Conditions</a> et notre <a href=\"/privacy\">Politique de confidentialité</a>. Apple, le logo Apple et App Store sont des marques d'Apple Inc. ; 2NIGHT n'est ni affilié à Apple Inc., ni sponsorisé ou approuvé par celle-ci.",
