    "pc_title": "Vos choix de confidentialité",
    "pc_lead": "Vous gardez le contrôle de vos données sur 2NIGHT. Voici comment exercer vos choix de confidentialité, à tout moment.",
    "pc1_t": "Accéder à vos données",
    "pc1_b": "Demandez une copie des données personnelles que nous détenons à votre sujet, et nous vous l’enverrons.",
    "pc2_t": "Supprimer votre compte et vos données",
    "pc2_b": "Supprimez votre compte à tout moment dans Réglages → Compte → Supprimer le compte, ou écrivez-nous. Nous effaçons vos données, sous réserve de toute obligation légale de conservation.",
    "pc3_t": "Refuser le marketing",
    "pc3_b": "Désactivez les e-mails promotionnels et les notifications push dans Réglages → Notifications, ou utilisez le lien de désinscription présent dans chaque e-mail.",
    "pc4_t": "Ne pas vendre ni partager",
    "pc4_b": "Nous ne vendons jamais vos données personnelles et ne les partageons jamais à des fins de publicité comportementale inter-contextes — il n’y a rien à refuser.",
    "pc5_t": "Gérer les cookies",
    "pc5_b": "Modifiez vos préférences de cookies et de suivi à tout moment via la bannière de cookies ou les réglages de votre navigateur.",
    "pc6_t": "Localisation et autorisations",
    "pc6_b": "Gérez l’accès à la localisation, à l’appareil photo et aux notifications depuis les réglages de votre appareil, et révoquez-les quand vous le souhaitez.",
    "pc_note": "Ces choix sont accessibles à tous, partout — y compris les droits accordés par le GDPR (UE/Royaume-Uni) et le CCPA/CPRA (California). Nous ne vous facturerons jamais ni ne vous traiterons différemment pour les avoir exercés.",
    "pc_contact": "Pour exercer un droit à la confidentialité, écrivez à privacy@2night.co — nous répondons sous 30 jours.",
