    "pc_kicker": "Deine Privatsphäre",
    "pc_title": "Deine Datenschutzeinstellungen",
    "pc_lead": "Du behältst die Kontrolle über deine Daten auf 2NIGHT. So nimmst du jederzeit deine Datenschutzrechte wahr.",
    "pc1_t": "Auf deine Daten zugreifen",
    "pc1_b": "Fordere eine Kopie der personenbezogenen Daten an, die wir über dich gespeichert haben, und wir senden sie dir zu.",
    "pc2_t": "Konto und Daten löschen",
    "pc2_b": "Lösche dein Konto jederzeit unter Einstellungen → Konto → Konto löschen oder schreib uns eine E-Mail. Wir löschen deine Daten, vorbehaltlich gesetzlicher Aufbewahrungspflichten.",
    "pc3_t": "Marketing abbestellen",
    "pc3_b": "Deaktiviere Werbe-E-Mails und Push-Benachrichtigungen unter Einstellungen → Benachrichtigungen oder nutze den Abmeldelink in jeder E-Mail.",
    "pc4_t": "Kein Verkauf, keine Weitergabe",
    "pc4_b": "Wir verkaufen deine personenbezogenen Daten niemals und geben sie niemals für kontextübergreifende verhaltensbasierte Werbung weiter — es gibt nichts abzulehnen.",
    "pc5_t": "Cookies verwalten",
    "pc5_b": "Ändere deine Cookie- und Tracking-Einstellungen jederzeit über das Cookie-Banner oder die Einstellungen deines Browsers.",
    "pc6_t": "Standort und Berechtigungen",
    "pc6_b": "Steuere den Zugriff auf Standort, Kamera und Benachrichtigungen in den Einstellungen deines Geräts und widerrufe ihn jederzeit.",
    "pc_note": "Diese Wahlmöglichkeiten stehen allen überall offen — einschließlich der Rechte aus der GDPR (EU/UK) und dem CCPA/CPRA (California). Wir berechnen dir niemals etwas und behandeln dich nicht anders, wenn du sie nutzt.",
    "pc_contact": "Um ein Datenschutzrecht auszuüben, schreib an privacy@2night.co — wir antworten innerhalb von 30 Tagen.",
