    "gal_profile_s": "Du, nach Einbruch der Nacht",
    "tiers_note": "Preise in USD, regional abweichend möglich. Kostenpflichtige Abos werden über den Apple App Store abgerechnet und verlängern sich automatisch bis zur Kündigung — jederzeit in deinen App-Store-Einstellungen verwalten oder kündigen. Siehe unsere AGB.",
    "auth_login": "Anmelden",
    "cg1_b": "Verwende deine eigenen Fotos und echte Angaben. Keine Fake-Profile, kein Identitätsdiebstahl, kein Catfishing.",
    "cg1_t": "Sei echt",
    "cg2_b": "Keine Belästigung, kein Hass, keine Drohungen, keine unaufgeforderten expliziten Inhalte. Behandle andere so, wie du behandelt werden möchtest.",
    "cg2_t": "Sei respektvoll",
    "cg3_b": "2NIGHT ist ausschließlich für Erwachsene. Wer minderjährig ist, wird sofort entfernt.",
    "cg3_t": "Nur ab 18 Jahren",
    "cg4_b": "Kein Verkauf, kein Escort, keine Anwerbung, keine Betrügereien und keine Bitten um Geld, Geschenke oder Krypto von Mitgliedern.",
    "cg4_t": "Kein Geld, kein Business",
    "cg5_b": "Niemanden ohne Zustimmung aufnehmen oder teilen, kein Doxxing, keine privaten Informationen weitergeben.",
    "cg5_t": "Bleib einvernehmlich",
    "cg6_b": "Blockiere und melde jeden, der eine Grenze überschreitet. Unser Team prüft jede Meldung — Melden hält die Nacht sicher.",
    "cg6_t": "Melde, was nicht stimmt",
    "cg_contact": "Etwas Ernstes bemerkt? Schreib uns — wir lesen jede Nachricht.",
    "cg_kicker": "Community",
    "cg_lead": "2NIGHT funktioniert nur, wenn es sich sicher und echt anfühlt. Diese Regeln halten die Nacht für alle gut — wer sie bricht, ist raus.",
    "cg_title": "Community-Richtlinien",
    "community_meta": "2NIGHT Community-Richtlinien — die Regeln, die die Nacht sicher und echt halten.",
    "disc_f1_b": "Setze deinen Status und die Stadt sieht, dass du heute Abend frei bist. Du bestimmst wer, wie weit und wie lange.",
    "disc_f1_t": "Mit einem Tap live gehen",
    "disc_f2_b": "Echte Menschen in deiner Nähe, jetzt gerade frei, die dasselbe wollen. Kein endloses Swipen Richtung Irgendwann.",
    "disc_f2_t": "Der Tonight Feed",
    "disc_f3_b": "Gegenseitiges Interesse öffnet einen Chat. Macht einen Plan und trefft euch — persönlich, noch in derselben Nacht.",
    "disc_f3_t": "Ping, Match, treffen",
    "disc_f4_b": "Von deiner Straße bis zur ganzen Stadt. Deine Mitgliedschaft bestimmt, wie weit die Nacht reichen kann.",
    "disc_f4_t": "Dein Radius, deine Nacht",
    "disc_feat_t": "Gemacht, damit du loslegst",
    "disc_kicker": "Entdecken",
    "disc_lead": "Die One-Night-Dating-App für Menschen, die um 19 Uhr beschließen, jemanden kennenzulernen — heute Abend, nicht morgen.",
    "disc_p1": "Die meisten Dating-Apps planen einen Kaffee in drei Wochen. 2NIGHT ist für die Stunden zwischen jetzt und 2 Uhr nachts gemacht — das Zeitfenster, in dem Pläne wirklich passieren. Geh live, sieh, wer in deiner Nähe unterwegs ist, ping, match und triff dich.",
    "disc_title": "Was ist 2NIGHT?",
    "discover_meta": "Entdecke 2NIGHT — was die One-Night-Dating-App ist und wie sie funktioniert.",
    "nav_blog": "Blog",
    "nav_community": "Community",
    "nav_discover": "Entdecken",
    "sec1_b": "Du entscheidest, wann du live bist, wie weit dein Radius reicht und was du teilst. Geh offline und du verschwindest.",
    "sec1_t": "Du hast immer die Kontrolle",
    "sec2_b": "Nur Personen innerhalb des Radius und der Zielgruppe, die du wählst, können dich sehen — und nur, solange du live bist.",
    "sec2_t": "Privat von Anfang an",
    "sec3_b": "Verschlüsselt bei der Übertragung, streng begrenzter Zugriff und niemals verkauft. Lies die Details in unserer Datenschutzerklärung.",
    "sec3_t": "Deine Daten, geschützt",
    "sec4_b": "Jeden, der dir ein ungutes Gefühl gibt, kannst du sofort blockieren und melden. Unser Team prüft jede Meldung.",
    "sec4_t": "Mit einem Tap blockieren und melden",
    "sec_contact": "Fragen zu Sicherheit oder Datenschutz? Schreib an support@2night.co.",
    "sec_kicker": "Vertrauen & Sicherheit",
    "sec_lead": "Neue Leute kennenzulernen sollte aufregend sein, nicht riskant. So schützt 2NIGHT dich und deine Daten.",
    "sec_note": "Wichtig: 2NIGHT führt keine Hintergrund- oder Identitätsprüfungen durch. Trefft euch in der Öffentlichkeit, sagt einem Freund Bescheid und vertraut eurem Bauchgefühl — siehe unsere Sicherheitstipps.",
    "sec_title": "Deine Sicherheit, von Grund auf.",
    "security_meta": "Vertrauen & Sicherheit bei 2NIGHT — wie wir dich und deine Daten schützen.",
    "tiers_note2": "2NIGHT startet bald. Komm auf die Warteliste — die ersten 20 Mitglieder erhalten 1 Jahr Platinum Black gratis, die nächsten 200 erhalten Gold kostenlos.",
    "hero_make_happen": "Mach 2NIGHT möglich",
