    "waitlist_title": "Unirme a la lista de espera",
    "waitlist_sub": "Sé de los primeros en adueñarte de la noche, estés donde estés.",
    "waitlist_placeholder": "Tu correo",
    "waitlist_button": "Avísame",
    "waitlist_done": "Estás en la lista. Nos vemos esta noche.",
    "about_kicker": "Acerca de 2NIGHT",
    "about_title": "Esta noche, no mañana.",
    "about_lead": "2NIGHT es para ese momento en que, a las 7 de la tarde, decides que de verdad quieres hacer algo — y quieres gente real cerca de ti que sienta lo mismo.",
    "about_story_pull": "La mayoría de las noches mueren en un chat de grupo. “Tenemos que vernos pronto.” Pronto nunca llega.",
    "about_story_t": "La noche en que de verdad sales",
    "about_story_p1": "2NIGHT nació de una idea testaruda: las mejores noches no se planean con tres semanas de antelación. Pasan porque alguien, en algún lugar cercano, está libre ahora mismo y con ganas de moverse. Hicimos la app que convierte ese impulso en un plan real — rápido, en persona, esta noche.",
    "about_story_p2": "Pon tu estado en una línea. Mira quién sale cerca de ti. Ping, match, nos vemos. Sin swipes infinitos hacia “quizá la semana que viene”. Solo la gente que sale esta noche, y el camino más corto para estar en la misma sala.",
    "about_world_t": "En todo el mundo, no ciudad a ciudad",
    "about_world_p1": "2NIGHT no se despliega de una ciudad en una ciudad. Funciona en cualquier parte del mundo — con la gente cerca de ti, estés donde estés esta noche. Aterriza en una ciudad nueva y la noche ya está en marcha.",
    "about_world_p2": "Tú decides hasta dónde llega. Elige tu radio — desde tu calle hasta toda la ciudad — y 2NIGHT te muestra quién sale dentro de él.",
    "about_who1_t": "Viajeros",
    "about_who1_b": "Ciudad nueva, ningún contacto, una sola noche para aprovecharla. Abre 2NIGHT y la noche local ya está frente a ti.",
    "about_who2_t": "Expatriados",
    "about_who2_b": "Estás construyendo una vida en un lugar nuevo. Conoce a gente que sale esta noche en el sitio que ahora llamas casa.",
    "about_who3_t": "Locales",
    "about_who3_b": "Conoces la ciudad — solo te falta compañía para esta noche. Pon tu estado y encuentra a tu gente, sin agendas.",
    "about_design_t": "Diseñada para la noche",
    "about_design_p": "Champán cálido sobre antracita profunda. Editorial, sobria y un punto exclusiva — pensada para sentirse como la mejor sala de la ciudad, no como otro feed ruidoso. Cada pantalla está hecha para quien decide tarde y se mueve rápido.",
    "support_kicker": "Soporte",
    "support_title": "¿En qué podemos ayudarte?",
    "support_lead": "Todo lo que necesitas saber sobre 2NIGHT — y una persona real al otro lado cuando la necesitas.",
    "faq_q7": "¿Cómo tratáis mi privacidad?",
    "faq_a7": "Solo recopilamos lo necesario para ayudarte a conocer gente esta noche, y nunca vendemos tus datos personales. Tú eliges qué es visible para los demás y cuándo compartes tu ubicación. Lee todos los detalles en nuestra Política de privacidad.",
    "faq_a7_link": "Política de privacidad",
    "support_contact_t": "¿Aún necesitas una mano?",
    "support_contact_p": "Escríbenos y una persona real te responderá. Leemos todos los mensajes.",
    "nav_safety": "Seguridad",
    "nav_contact": "Contacto",
    "footer_safety": "Seguridad",
    "footer_contact": "Contacto",
    "contact_kicker": "Contáctanos",
    "screens_disclaimer": "Todas las fotos son solo a modo ilustrativo.",
    "android_soon": "Android — disponible pronto",
    "testimonials_kicker": "Desde la noche",
    "testimonials_title": "Lo que nuestros usuarios dijeron de nosotros",
    "testimonials_sub": "Primeras noches en beta, con sus propias palabras.",
    "testimonials_note": "Citas de usuarios beta. Los nombres y las ciudades son representativos.",
    "testimonial1_q": "Aterricé en Lisboa sin ningún plan. A las 9 de la noche estaba en un bar en una azotea con tres personas que acababa de matchear. Esa es toda la app en una noche.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lisboa",
    "testimonial2_q": "Se acabó el «deberíamos quedar pronto». Puse mi estado, vi quién estaba libre y conocí a alguien esa misma noche. Por fin.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "París",
    "testimonial3_q": "Los Black Events son increíbles. Se siente menos como una app y más como una invitación a la mejor sala de la ciudad.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubái",
    "testimonial4_q": "Ciudad nueva por trabajo, no conocía a nadie. A las dos semanas ya tengo un círculo de verdad — todo por decidir a las 7 que no quería quedarme en casa.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlín",
    "testimonial5_q": "Es rápida, es preciosa y de verdad respeta tu tiempo. Ping, match, quedamos — exactamente como prometen.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "Londres",
    "testimonial6_q": "El Travel Mode es un truco de tramposo. Abro 2NIGHT en cuanto aterrizo y la noche local ya me está esperando.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "Nueva York",
    "safety_kicker": "Seguridad",
    "safety_title": "Conoce gente de forma inteligente.",
    "safety_lead": "2NIGHT está hecha para noches espontáneas, en la vida real. Unos pocos hábitos sencillos las hacen divertidas — y te mantienen al mando cuando conoces a alguien nuevo.",
    "safety_t1_t": "Queda en un lugar público",
    "safety_t1_b": "Para una primera cita, elige un sitio concurrido y bien iluminado — un bar, una cafetería, un lugar popular. Quédate en público hasta que te sientas de verdad cómodo, y no vayas a un lugar privado con alguien que acabas de conocer.",
    "safety_t2_t": "Cuéntale tus planes a un amigo",
    "safety_t2_b": "Dile a alguien de confianza adónde vas, con quién quedas y cuándo esperas volver. Comparte tu ubicación en directo con esa persona durante la noche y avísale después.",
    "safety_t3_t": "Organiza tu propio transporte",
    "safety_t3_b": "Ve y vuelve en tus propios términos. Mantén el móvil cargado, ten claro cómo vas a volver a casa y eres libre de irte cuando quieras — sin dar explicaciones.",
    "safety_t4_t": "Nunca envíes dinero",
    "safety_t4_b": "Nunca envíes dinero, tarjetas regalo ni cripto a alguien que conociste en la app, sea cual sea la historia. Las peticiones de dinero, ayuda financiera o «consejos» de inversión son estafas clásicas — para y denúncialas.",
    "safety_t5_t": "Fíate de tu instinto",
    "safety_t5_b": "Si algo te da mala espina, probablemente lo sea. No le debes tu tiempo a nadie. Termina el chat, deja la cita o llama a un amigo — no hay un motivo equivocado para marcharte.",
    "safety_t6_t": "Denuncia y bloquea",
    "safety_t6_b": "A cualquiera que te haga sentir incómodo puedes bloquearlo y denunciarlo con un toque. Nuestro equipo revisa las denuncias — señalar el mal comportamiento hace que la noche sea más segura para todos.",
    "safety_t7_t": "Protege tu información personal",
    "safety_t7_b": "Mantén los chats dentro de 2NIGHT hasta que confíes en alguien. No compartas tu dirección, tu trabajo, tus datos bancarios ni documentos, y ten cuidado con las fotos que revelan exactamente dónde vives.",
    "safety_t8_t": "Tú tienes el control",
    "safety_t8_b": "Tú decides cuándo estás en directo, hasta dónde llega tu radio y qué compartes. No hacemos verificaciones de antecedentes, así que tu propio criterio siempre va primero.",
    "safety_help_t": "En una emergencia, pide ayuda.",
    "safety_help_p": "Si alguna vez te sientes inseguro o amenazado, contacta primero con los servicios de emergencia locales. Para denunciarnos a alguien o algo, escribe a nuestro equipo — leemos todos los mensajes.",
    "cookie_text": "Usamos cookies para que 2NIGHT funcione y para entender cómo se usa el sitio.",
