    "founders_title": "Dos amigos, una idea terca",
    "founders_role": "Fundador y Socio · Suiza",
    "founders_p1": "Hugo y Jeric, dos amigos de Suiza, chocaban siempre contra el mismo muro: ciudades llenas de gente, chats de grupo llenos de «tenemos que vernos pronto» y nadie de verdad en la calle esta noche.",
    "founders_p2": "Hugo, el fundador, escribe el código. Jeric, su socio, dirige el proyecto y da forma a la experiencia. De una mesa de cocina suiza hasta donde estés esta noche: esa es toda la historia.",
    "founders_sign": "— Hugo y Jeric · Suiza",
