    "gal_profile_s": "Tú, de noche",
    "tiers_note": "Precios en USD; pueden variar según la región. Los planes de pago se facturan a través del App Store de Apple y se renuevan automáticamente hasta su cancelación — gestiónalos o cancélalos cuando quieras en los ajustes del App Store. Consulta nuestros Términos.",
    "auth_login": "Iniciar sesión",
    "cg1_b": "Usa tus propias fotos y datos reales. Nada de perfiles falsos, suplantación de identidad ni catfishing.",
    "cg1_t": "Sé real",
    "cg2_b": "Nada de acoso, odio, amenazas ni contenido explícito no solicitado. Trata a los demás como te gustaría que te trataran.",
    "cg2_t": "Sé respetuoso",
    "cg3_b": "2NIGHT es estrictamente para adultos. Cualquier menor de edad será expulsado de inmediato.",
    "cg3_t": "Solo mayores de 18",
    "cg4_b": "Nada de ventas, escorts, captación, estafas ni pedir dinero, regalos o cripto a otros miembros.",
    "cg4_t": "Ni dinero ni negocios",
    "cg5_b": "No grabes ni compartas a nadie sin su consentimiento, nada de doxxing, nada de compartir información privada.",
    "cg5_t": "Que todo sea consentido",
    "cg6_b": "Bloquea y reporta a quien cruce la línea. Nuestro equipo revisa cada reporte — reportar mantiene la noche segura.",
    "cg6_t": "Reporta lo que no esté bien",
    "cg_contact": "¿Ves algo grave? Escríbenos — leemos cada mensaje.",
    "cg_kicker": "Comunidad",
    "cg_lead": "2NIGHT solo funciona si se siente seguro y real. Estas reglas mantienen la noche bien para todos — si las rompes, estás fuera.",
    "cg_title": "Normas de la comunidad",
    "community_meta": "Normas de la comunidad de 2NIGHT — las reglas que mantienen la noche segura y real.",
    "disc_f1_b": "Activa tu estado y la ciudad ve que estás libre esta noche. Tú controlas quién, hasta dónde y por cuánto tiempo.",
    "disc_f1_t": "Ponte en vivo con un toque",
    "disc_f2_b": "Gente real cerca de ti, libre ahora mismo, que quiere lo mismo. Sin swipear sin fin hacia un algún día.",
    "disc_f2_t": "El Tonight Feed",
    "disc_f3_b": "El interés mutuo abre un chat. Hagan un plan y conózcanse — en persona, esa misma noche.",
    "disc_f3_t": "Ping, match, conóceos",
    "disc_f4_b": "De tu calle a toda la ciudad. Tu membresía define hasta dónde puede llegar la noche.",
    "disc_f4_t": "Tu radio, tu noche",
    "disc_feat_t": "Diseñado para sacarte a la calle",
    "disc_kicker": "Descubre",
    "disc_lead": "La app de citas de una noche para quienes deciden a las 7 de la tarde que quieren conocer a alguien — esta noche, no mañana.",
    "disc_p1": "La mayoría de las apps de citas programan un café para dentro de tres semanas. 2NIGHT está hecha para las horas entre ahora y las 2 de la madrugada — la ventana en la que los planes de verdad ocurren. Ponte en vivo, ve quién está cerca de ti, haz ping, haz match y conóceos.",
    "disc_title": "¿Qué es 2NIGHT?",
    "discover_meta": "Descubre 2NIGHT — qué es la app de citas de una noche y cómo funciona.",
    "nav_blog": "Blog",
    "nav_community": "Comunidad",
    "nav_discover": "Descubre",
    "sec1_b": "Tú decides cuándo estás en vivo, hasta dónde llega tu radio y qué compartes. Ponte fuera de línea y desapareces.",
    "sec1_t": "Siempre tienes el control",
    "sec2_b": "Solo las personas dentro del radio y la audiencia que elijas pueden verte, y únicamente mientras estás en vivo.",
    "sec2_t": "Privado por defecto",
    "sec3_b": "Cifrados en tránsito, con acceso estrictamente limitado y nunca vendidos. Lee los detalles en nuestra Política de Privacidad.",
    "sec3_t": "Tus datos, protegidos",
    "sec4_b": "A cualquiera que te incomode puedes bloquearlo y reportarlo al instante. Nuestro equipo revisa cada reporte.",
    "sec4_t": "Bloquea y reporta con un toque",
    "sec_contact": "¿Dudas sobre seguridad o privacidad? Escribe a support@2night.co.",
    "sec_kicker": "Confianza y seguridad",
    "sec_lead": "Conocer gente nueva debería emocionar, no preocupar. Así protege 2NIGHT a ti y a tus datos.",
    "sec_note": "Importante: 2NIGHT no realiza verificaciones de antecedentes ni de identidad. Quédense en lugares públicos, avisen a un amigo y confíen en su instinto — consulta nuestros consejos de seguridad.",
    "sec_title": "Tu seguridad, por diseño.",
    "security_meta": "Confianza y seguridad en 2NIGHT — cómo te protegemos a ti y a tus datos.",
    "tiers_note2": "2NIGHT se lanza pronto. Únete a la lista de espera — los primeros 20 miembros consiguen 1 año de Platinum Black gratis, y los siguientes 200 consiguen Gold gratis.",
