    "faq_q1": "2NIGHT è gratis?",
    "faq_a1": "Sì. Iscriverti a 2NIGHT e conoscere persone è gratis. Un abbonamento a pagamento è in arrivo, e vedrai esattamente quanto costa nell’app prima che ti venga addebitato qualcosa.",
    "faq_q2": "Quando arriva nella mia città?",
    "faq_a2": "Apriamo le città a ondate. Iscriviti alla lista d’attesa e ti avviseremo nel momento in cui 2NIGHT sarà attiva vicino a te.",
    "faq_q3": "In cosa è diversa dalle altre app di incontri?",
    "faq_a3": "Basta swipe infiniti verso un « chissà quando ». 2NIGHT ti mostra chi è in giro vicino a te proprio ora e ti aiuta a incontrarti davvero — stasera, non tra tre settimane.",
    "faq_q4": "È sicura?",
    "faq_a4": "Decidi tu quando essere visibile, fin dove arriva il tuo raggio e cosa condividi. Blocca e segnala con un tocco, e vai offline per sparire all’istante. Leggi le nostre indicazioni di sicurezza prima di un incontro.",
    "faq_q5": "Cosa ottengo iscrivendomi presto?",
    "faq_a5": "I primi 20 membri ricevono 1 anno di Platinum Black, gratis. I successivi 200 ricevono Gold gratis. I primi arrivati comandano la notte.",
    "faq_q6": "Vendete i miei dati?",
    "faq_a6": "Mai. Non vendiamo i tuoi dati personali e non facciamo tracciamento pubblicitario di terze parti. Hai sempre il controllo — vedi le tue Scelte sulla privacy.",
    "sticky_note": "Iscrizione gratuita · 18+",
    "aria_menu": "Menu",
    "disclaimer_html": "<strong>2NIGHT è riservato agli adulti dai 18 anni in su.</strong> 2NIGHT sarà disponibile a breve; alcune funzioni e il download dall'App Store potrebbero non essere ancora disponibili nella tua regione. Le schermate e le foto dell'app sono solo a scopo illustrativo e le testimonianze provengono da utenti beta e sono rappresentative. 2NIGHT aiuta le persone a incontrarsi, ma <strong>non</strong> effettua controlli sui precedenti o sull'identità — leggi le nostre indicazioni sulla <a href=\"/safety\">Sicurezza</a> e incontra le persone in modo responsabile. Utilizzando 2NIGHT accetti i nostri <a href=\"/terms\">Termini</a> e la nostra <a href=\"/privacy\">Informativa sulla privacy</a>. Apple, il logo Apple e App Store sono marchi di Apple Inc.; 2NIGHT non è affiliata ad Apple Inc. né sponsorizzata o approvata da essa.",
