    "waitlist_done": "Sei in lista. A stasera.",
    "about_kicker": "Chi è 2NIGHT",
    "about_title": "Stasera, non domani.",
    "about_lead": "2NIGHT è per quel momento in cui, alle 19, decidi che hai davvero voglia di fare qualcosa — e vuoi persone vere vicino a te che provano lo stesso.",
    "about_story_pull": "La maggior parte delle serate muore in una chat di gruppo. “Dovremmo vederci presto.” Presto non arriva mai.",
    "about_story_t": "La serata in cui esci davvero",
    "about_story_p1": "2NIGHT è nato attorno a un’idea testarda: le serate migliori non si pianificano con tre settimane d’anticipo. Accadono perché qualcuno, da qualche parte qui vicino, è libero proprio ora e pronto a muoversi. Abbiamo fatto l’app che trasforma quell’impulso in un piano vero — veloce, dal vivo, stasera.",
    "about_story_p2": "Imposta il tuo stato in una riga. Guarda chi esce vicino a te. Ping, match, ci vediamo. Niente swipe infiniti verso “magari la prossima settimana”. Solo le persone che escono stasera, e la via più breve per ritrovarsi nella stessa stanza.",
    "about_world_t": "In tutto il mondo, non città per città",
    "about_world_p1": "2NIGHT non si apre una città alla volta. Funziona ovunque sulla Terra — con le persone vicino a te, ovunque tu sia stasera. Atterra in una città nuova e la notte è già live.",
    "about_world_p2": "Sei tu a decidere fin dove arriva. Scegli il tuo raggio — dalla tua via all’intera città — e 2NIGHT ti mostra chi esce al suo interno.",
    "about_who1_t": "Viaggiatori",
    "about_who1_b": "Città nuova, nessun contatto, una sola notte per farla valere. Apri 2NIGHT e la notte locale è già davanti a te.",
    "about_who2_t": "Expat",
    "about_who2_b": "Stai costruendo una vita in un posto nuovo. Conosci persone che escono stasera nel luogo che ora chiami casa.",
    "about_who3_t": "Gente del posto",
    "about_who3_b": "Conosci la città — ti manca solo compagnia per stasera. Imposta il tuo stato e trova la tua gente, senza bisogno di un’agenda.",
    "about_design_t": "Pensato per la notte",
    "about_design_p": "Champagne caldo su antracite profondo. Editoriale, sobrio e un po’ esclusivo — fatto per dare la sensazione della stanza più bella della città, non dell’ennesimo feed rumoroso. Ogni schermata è pensata per chi decide tardi e si muove in fretta.",
    "support_kicker": "Assistenza",
    "support_title": "Come possiamo aiutarti?",
    "support_lead": "Tutto quello che devi sapere su 2NIGHT — e una persona vera dall’altra parte quando ti serve.",
    "faq_q7": "Come trattate la mia privacy?",
    "faq_a7": "Raccogliamo solo ciò che serve per aiutarti a conoscere persone stasera, e non vendiamo mai i tuoi dati personali. Scegli tu cosa è visibile agli altri e quando condividi la posizione. Tutti i dettagli nella nostra Informativa sulla privacy.",
    "faq_a7_link": "Informativa sulla privacy",
    "support_contact_t": "Ti serve ancora una mano?",
    "support_contact_p": "Scrivici e una persona vera ti risponderà. Leggiamo ogni messaggio.",
