    "testimonials_sub": "Le prime notti in beta, con parole loro.",
    "testimonials_note": "Citazioni di utenti beta. Nomi e città sono rappresentativi.",
    "testimonial1_q": "Sono atterrato a Lisbona senza alcun piano. Alle 21 ero in un rooftop bar con tre persone che avevo appena matchato. È tutta l’app in una sola notte.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lisbona",
    "testimonial2_q": "Basta con i «dovremmo vederci presto». Ho impostato il mio stato, visto chi era libero e ho davvero incontrato qualcuno la sera stessa. Finalmente.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Parigi",
    "testimonial3_q": "I Black Events sono assurdi. Sembra meno un’app e più un invito nella sala più bella della città.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "Città nuova per lavoro, non conoscevo nessuno. Dopo due settimane ho un giro di amici vero — tutto perché alle 19 ho deciso che non volevo restare a casa.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlino",
    "testimonial5_q": "È veloce, è bellissima e rispetta davvero il tuo tempo. Ping, match, ci vediamo — esattamente come promesso.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "Londra",
    "testimonial6_q": "Il Travel Mode è un trucco da videogioco. Apro 2NIGHT appena atterro e la notte locale mi sta già aspettando.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "New York",
    "safety_kicker": "Sicurezza",
    "safety_title": "Conosci gente nel modo intelligente.",
    "safety_lead": "2NIGHT è pensata per notti spontanee, nella vita reale. Poche semplici abitudini le rendono divertenti — e ti tengono al comando quando incontri qualcuno di nuovo.",
    "safety_t1_t": "Vedetevi in un luogo pubblico",
    "safety_t1_b": "Per un primo incontro, scegli un posto affollato e ben illuminato — un bar, un caffè, un locale frequentato. Resta in pubblico finché non ti senti davvero a tuo agio e non andare in un luogo privato con qualcuno che hai appena conosciuto.",
    "safety_t2_t": "Di’ a un amico i tuoi piani",
    "safety_t2_b": "Fai sapere a una persona di fiducia dove vai, chi incontri e quando pensi di tornare. Condividi con lei la tua posizione in tempo reale per la serata e fatti sentire dopo.",
    "safety_t3_t": "Organizza il tuo trasporto",
    "safety_t3_b": "Vai e torna alle tue condizioni. Tieni il telefono carico, sappi come torni a casa e sei libero di andartene quando vuoi — senza dover dare spiegazioni.",
    "safety_t4_t": "Non inviare mai denaro",
    "safety_t4_b": "Non inviare mai denaro, carte regalo o cripto a qualcuno conosciuto sull’app, qualunque sia la storia. Le richieste di contanti, aiuti finanziari o «dritte» di investimento sono truffe classiche — fermati e segnalale.",
    "safety_t5_t": "Fidati del tuo istinto",
    "safety_t5_b": "Se qualcosa ti sembra sbagliato, probabilmente lo è. Non devi il tuo tempo a nessuno. Chiudi la chat, lascia l’incontro o chiama un amico — non esiste un motivo sbagliato per andartene.",
    "safety_t6_t": "Segnala e blocca",
    "safety_t6_b": "Chiunque ti metta a disagio può essere bloccato e segnalato con un tocco. Il nostro team esamina le segnalazioni — segnalare i comportamenti scorretti rende la serata più sicura per tutti.",
    "safety_t7_t": "Proteggi le tue informazioni personali",
    "safety_t7_b": "Tieni le chat dentro 2NIGHT finché non ti fidi di qualcuno. Non condividere il tuo indirizzo di casa, il luogo di lavoro, i dati bancari o i documenti e fai attenzione alle foto che rivelano esattamente dove abiti.",
    "safety_t8_t": "Il controllo è tuo",
    "safety_t8_b": "Decidi tu quando sei online, fin dove arriva il tuo raggio e cosa condividi. Non facciamo controlli sui precedenti, quindi il tuo giudizio viene sempre prima.",
    "safety_help_t": "In caso di emergenza, chiedi aiuto.",
    "safety_help_p": "Se ti senti in pericolo o minacciato, contatta prima i servizi di emergenza locali. Per segnalarci qualcuno o qualcosa, scrivi al nostro team — leggiamo ogni messaggio.",
