    "disc_lead": "L'app di incontri per una notte per chi alle 19 decide di voler conoscere qualcuno — stasera, non domani.",
    "disc_p1": "La maggior parte delle app di incontri fissa un caffè tra tre settimane. 2NIGHT è pensata per le ore tra adesso e le 2 di notte — la finestra in cui i piani succedono davvero. Vai live, guarda chi è in giro vicino a te, fai ping, fai match e incontratevi.",
    "disc_title": "Cos'è 2NIGHT?",
