    "sec1_t": "Hai sempre il controllo",
    "sec2_b": "Solo le persone dentro il raggio e il pubblico che scegli possono vederti, e solo mentre sei live.",
    "sec2_t": "Privato per impostazione predefinita",
    "sec3_b": "Crittografati durante il trasferimento, accesso rigorosamente limitato e mai venduti. Leggi i dettagli nella nostra Informativa sulla privacy.",
    "sec3_t": "I tuoi dati, protetti",
