    "faq_q1": "O 2NIGHT é grátis?",
    "faq_a1": "Sim. Aderir ao 2NIGHT e conhecer pessoas é grátis. Está a caminho uma subscrição paga, e verá exatamente quanto custa na app antes de ser cobrado seja o que for.",
    "faq_q2": "Quando chega à minha cidade?",
    "faq_a2": "Abrimos cidades por vagas. Junte-se à lista de espera e avisamo-lo no momento em que o 2NIGHT ficar disponível perto de si.",
    "faq_q3": "Em que é diferente de outras apps de encontros?",
    "faq_a3": "Acabou o swipe infinito rumo a um « um dia ». O 2NIGHT mostra quem está a sair perto de si agora mesmo e ajuda-o a encontrar-se a sério — esta noite, não daqui a três semanas.",
    "faq_q4": "É seguro?",
    "faq_a4": "É você que decide quando está visível, até onde chega o seu raio e o que partilha. Bloqueie e denuncie com um toque, e fique offline para desaparecer num instante. Leia as nossas orientações de segurança antes de se encontrar.",
    "faq_q5": "O que ganho por aderir cedo?",
    "faq_a5": "Os primeiros 20 membros recebem 1 ano de Platinum Black, grátis. Os 200 seguintes recebem Gold grátis. Os primeiros são os donos da noite.",
    "faq_q6": "Vendem os meus dados?",
    "faq_a6": "Nunca. Não vendemos os seus dados pessoais e não fazemos rastreio publicitário de terceiros. Está sempre no controlo — veja as suas Opções de privacidade.",
    "sticky_note": "Adesão gratuita · 18+",
    "aria_menu": "Menu",
    "disclaimer_html": "<strong>O 2NIGHT é para adultos com 18 anos ou mais.</strong> O 2NIGHT vai ser lançado em breve; algumas funcionalidades e a transferência na App Store podem ainda não estar disponíveis na sua região. Os ecrãs e as fotografias da aplicação são apenas ilustrativos, e os testemunhos são de utilizadores beta e são representativos. O 2NIGHT ajuda as pessoas a conhecerem-se, mas <strong>não</strong> realiza verificações de antecedentes ou de identidade — leia as nossas orientações de <a href=\"/safety\">Segurança</a> e encontre-se com responsabilidade. Ao utilizar o 2NIGHT, concorda com os nossos <a href=\"/terms\">Termos</a> e com a nossa <a href=\"/privacy\">Política de Privacidade</a>. Apple, o logótipo Apple e App Store são marcas comerciais da Apple Inc.; o 2NIGHT não está associado à Apple Inc. nem é patrocinado ou aprovado por ela.",
