    "tiers_note": "Preços em USD, podem variar consoante a região. Os planos pagos são cobrados através da App Store da Apple e renovam-se automaticamente até serem cancelados — gere ou cancela a qualquer momento nas definições da App Store. Consulta os nossos Termos.",
    "auth_login": "Iniciar sessão",
    "cg1_b": "Usa as tuas próprias fotos e dados reais. Nada de perfis falsos, falsificação de identidade ou catfishing.",
    "cg1_t": "Sê verdadeiro",
    "cg2_b": "Nada de assédio, ódio, ameaças ou conteúdo explícito não solicitado. Trata os outros como gostarias de ser tratado.",
    "cg2_t": "Sê respeitoso",
    "cg3_b": "O 2NIGHT é estritamente para adultos. Qualquer menor de idade é removido imediatamente.",
    "cg3_t": "Apenas maiores de 18",
    "cg4_b": "Nada de vendas, acompanhantes, aliciamento, burlas nem pedir dinheiro, presentes ou cripto a outros membros.",
    "cg4_t": "Sem dinheiro, sem negócios",
