    "disc_feat_t": "Feito para te pôr a sair",
    "disc_kicker": "Descobre",
    "disc_lead": "A app de encontros de uma noite para quem decide às 19h que quer conhecer alguém — esta noite, não amanhã.",
    "disc_p1": "A maioria das apps de encontros marca um café para daqui a três semanas. O 2NIGHT foi feito para as horas entre agora e as 2 da manhã — a janela em que os planos acontecem de verdade. Fica ao vivo, vê quem está perto de ti, faz ping, faz match e conheçam-se.",
