    "sec2_t": "Privado por predefinição",
    "sec3_b": "Encriptados em trânsito, acesso estritamente limitado e nunca vendidos. Lê os detalhes na nossa Política de Privacidade.",
    "sec3_t": "Os teus dados, protegidos",
    "sec4_b": "Quem te deixar desconfortável pode ser bloqueado e denunciado num instante. A nossa equipa analisa cada denúncia.",
