    "faq_kicker": "Goed om te weten",
    "faq_title": "Antwoord op je vragen.",
    "faq_q1": "Is 2NIGHT gratis?",
    "faq_a1": "Ja. Aanmelden bij 2NIGHT en mensen ontmoeten is gratis. Er komt een betaald lidmaatschap aan, en je ziet in de app precies wat het kost voordat er iets in rekening wordt gebracht.",
    "faq_q2": "Wanneer lanceert het in mijn stad?",
    "faq_a2": "We openen steden in golven. Schrijf je in op de wachtlijst en we laten het je weten zodra 2NIGHT bij jou in de buurt live gaat.",
    "faq_q3": "Hoe verschilt het van andere dating-apps?",
    "faq_a3": "Geen eindeloos swipen richting „ooit”. 2NIGHT laat zien wie er nu in de buurt op stap is en helpt je elkaar echt te ontmoeten — vanavond, niet over drie weken.",
    "faq_q4": "Is het veilig?",
    "faq_a4": "Jij bepaalt wanneer je live bent, hoe ver je radius reikt en wat je deelt. Blokkeer en rapporteer met één tik, en ga offline om meteen te verdwijnen. Lees onze veiligheidsrichtlijnen voordat je afspreekt.",
    "faq_q5": "Wat krijg ik als ik vroeg meedoe?",
    "faq_a5": "De eerste 20 leden krijgen 1 jaar Platinum Black, gratis. De volgende 200 krijgen Gold gratis. De eersten heersen over de nacht.",
    "faq_q6": "Verkopen jullie mijn gegevens?",
    "faq_a6": "Nooit. We verkopen je persoonlijke gegevens niet en we doen niet aan advertentietracking van derden. Jij houdt altijd de controle — bekijk je Privacykeuzes.",
    "sticky_note": "Gratis aanmelden · 18+",
    "aria_menu": "Menu",
    "disclaimer_html": "<strong>2NIGHT is voor volwassenen van 18 jaar en ouder.</strong> 2NIGHT wordt binnenkort gelanceerd; sommige functies en de download in de App Store zijn mogelijk nog niet beschikbaar in jouw regio. App-schermen en foto's zijn alleen ter illustratie, en de getuigenissen zijn van bètagebruikers en zijn representatief. 2NIGHT helpt mensen elkaar te ontmoeten, maar voert <strong>geen</strong> achtergrond- of identiteitscontroles uit — lees onze <a href=\"/safety\">Veiligheidsrichtlijnen</a> en spreek verantwoord af. Door 2NIGHT te gebruiken ga je akkoord met onze <a href=\"/terms\">Voorwaarden</a> en ons <a href=\"/privacy\">Privacybeleid</a>. Apple, het Apple-logo en App Store zijn handelsmerken van Apple Inc.; 2NIGHT is niet gelieerd aan Apple Inc. en wordt niet door Apple Inc. gesponsord of onderschreven.",
    "swipe_c1_t": "Rooftop, 21:00",
