    "pc_kicker": "Jouw privacy",
    "pc_title": "Jouw privacykeuzes",
    "pc_lead": "Jij houdt de controle over je gegevens op 2NIGHT. Zo maak je op elk moment gebruik van je privacykeuzes.",
    "pc1_t": "Je gegevens inzien",
    "pc1_b": "Vraag een kopie op van de persoonsgegevens die we over je bewaren, en we sturen ze naar je toe.",
    "pc2_t": "Je account en gegevens verwijderen",
    "pc2_b": "Verwijder je account wanneer je wilt via Instellingen → Account → Account verwijderen, of stuur ons een e-mail. We wissen je gegevens, behoudens eventuele wettelijke bewaarplicht.",
    "pc3_t": "Marketing afmelden",
    "pc3_b": "Schakel promotionele e-mails en pushmeldingen uit via Instellingen → Meldingen, of gebruik de afmeldlink in elke e-mail.",
    "pc4_t": "Niet verkopen of delen",
