    "waitlist_done": "Je staat op de lijst. Tot vanavond.",
    "about_kicker": "Over 2NIGHT",
    "about_title": "Vanavond, niet morgen.",
    "about_lead": "2NIGHT is voor dat moment om 19 uur waarop je besluit dat je écht iets wilt doen — en echte mensen bij je in de buurt wilt die hetzelfde voelen.",
    "about_story_pull": "De meeste avonden sterven in een groepschat. “We moeten snel weer eens afspreken.” Snel komt nooit.",
    "about_story_t": "De avond dat je echt uitgaat",
    "about_story_p1": "2NIGHT is gebouwd rond één koppig idee: de beste avonden worden niet drie weken van tevoren gepland. Ze gebeuren omdat iemand, ergens in de buurt, nu vrij is en klaar om te bewegen. We maakten de app die dat impuls omzet in een echt plan — snel, in het echt, vanavond.",
    "about_story_p2": "Zet je status in één regel. Zie wie er bij jou in de buurt uit is. Ping, match, ontmoet. Geen eindeloos swipen richting “misschien volgende week”. Alleen de mensen die vanavond uit zijn, en de kortst mogelijke weg om in dezelfde ruimte te staan.",
    "about_world_t": "Wereldwijd, niet stad voor stad",
    "about_world_p1": "2NIGHT rolt niet één stad tegelijk uit. Het werkt overal ter wereld — met de mensen bij jou in de buurt, waar je vanavond ook bent. Land in een nieuwe stad en de nacht is al live.",
    "about_world_p2": "Jij bepaalt hoe ver het reikt. Kies je straal — van je eigen straat tot de hele stad — en 2NIGHT laat je zien wie er binnen die straal uit is.",
    "about_who1_t": "Reizigers",
    "about_who1_b": "Nieuwe stad, geen contacten, één avond om het te laten tellen. Open 2NIGHT en de lokale nacht ligt al voor je.",
    "about_who2_t": "Expats",
    "about_who2_b": "Een leven opbouwen op een nieuwe plek. Ontmoet mensen die vanavond uit zijn op de plek die je nu thuis noemt.",
    "about_who3_t": "Locals",
    "about_who3_b": "Je kent de stad — je wilt gewoon gezelschap voor vanavond. Zet je status en vind je mensen, geen agenda nodig.",
    "about_design_t": "Ontworpen voor de nacht",
    "about_design_p": "Warme champagne op diep antraciet. Editorial, rustig en een tikje exclusief — gebouwd om aan te voelen als de beste ruimte van de stad, niet als weer een luidruchtige feed. Elk scherm is gemaakt voor mensen die laat beslissen en snel bewegen.",
    "support_kicker": "Support",
    "support_title": "Hoe kunnen we helpen?",
    "support_lead": "Alles wat je over 2NIGHT moet weten — en een echt mens aan de andere kant wanneer je er een nodig hebt.",
    "faq_q7": "Hoe gaan jullie om met mijn privacy?",
    "faq_a7": "We verzamelen alleen wat nodig is om je vanavond mensen te laten ontmoeten, en we verkopen je persoonsgegevens nooit. Jij kiest wat voor anderen zichtbaar is en wanneer je je locatie deelt. Lees alle details in ons Privacybeleid.",
    "faq_a7_link": "Privacybeleid",
    "support_contact_t": "Toch nog hulp nodig?",
    "support_contact_p": "Mail ons en een echt mens reageert. We lezen elk bericht.",
    "nav_safety": "Veiligheid",
    "nav_contact": "Contact",
    "footer_safety": "Veiligheid",
    "footer_contact": "Contact",
    "contact_kicker": "Neem contact op",
    "screens_disclaimer": "Alle foto’s zijn alleen ter illustratie.",
    "android_soon": "Android — binnenkort beschikbaar",
    "testimonials_kicker": "Uit de nacht",
    "testimonials_title": "Wat onze gebruikers over ons zeiden",
    "testimonials_sub": "Vroege bètanachten, in hun eigen woorden.",
    "testimonials_note": "Citaten van bètagebruikers. Namen en steden zijn representatief.",
    "testimonial1_q": "Ik landde in Lissabon zonder enig plan. Om 21 uur stond ik op een rooftopbar met drie mensen die ik net had gematcht. Dat is de hele app in één nacht.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lissabon",
    "testimonial2_q": "Geen “we moeten snel eens afspreken” meer. Ik zette mijn status, zag wie er vrij was en ontmoette echt iemand dezelfde avond. Eindelijk.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Parijs",
    "testimonial3_q": "De Black Events zijn ongelofelijk. Het voelt minder als een app en meer als een uitnodiging voor de mooiste zaal van de stad.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "Nieuwe stad voor werk, kende niemand. Na twee weken heb ik een echte kring — allemaal omdat ik om 19 uur besloot dat ik niet binnen wilde blijven.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlijn",
    "testimonial5_q": "Het is snel, het is prachtig en het respecteert echt je tijd. Ping, match, afspreken — precies zoals beloofd.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "Londen",
    "testimonial6_q": "Travel Mode is een cheatcode. Ik open 2NIGHT zodra ik land en de lokale nacht staat al klaar.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "New York",
    "safety_kicker": "Veiligheid",
    "safety_title": "Ontmoet mensen op de slimme manier.",
    "safety_lead": "2NIGHT is gemaakt voor spontane nachten in het echt. Een paar simpele gewoontes houden ze leuk — en houden jou in controle wanneer je iemand nieuw ontmoet.",
    "safety_t1_t": "Spreek af op een openbare plek",
    "safety_t1_b": "Kies voor een eerste afspraak iets drukbezochts en goed verlichts — een bar, een café, een populaire plek. Blijf op een openbare plek tot je je echt op je gemak voelt, en ga niet naar een privélocatie met iemand die je net hebt ontmoet.",
    "safety_t2_t": "Vertel een vriend je plannen",
    "safety_t2_b": "Laat iemand die je vertrouwt weten waar je heen gaat, met wie je afspreekt en wanneer je terug verwacht te zijn. Deel die nacht je live locatie met diegene en laat achteraf weten dat alles goed is.",
    "safety_t3_t": "Regel je eigen vervoer",
    "safety_t3_b": "Zorg dat je op je eigen voorwaarden komt en gaat. Houd je telefoon opgeladen, weet hoe je thuiskomt, en je bent vrij om weg te gaan wanneer je wilt — zonder uitleg.",
    "safety_t4_t": "Stuur nooit geld",
    "safety_t4_b": "Stuur nooit geld, cadeaubonnen of crypto naar iemand die je op de app hebt ontmoet, wat het verhaal ook is. Verzoeken om geld, financiële hulp of investerings­“tips” zijn klassieke oplichting — stop en meld ze.",
    "safety_t5_t": "Vertrouw op je gevoel",
    "safety_t5_b": "Als iets niet goed voelt, is dat waarschijnlijk ook zo. Je bent niemand je tijd verschuldigd. Beëindig het gesprek, verlaat de afspraak of bel een vriend — er bestaat geen verkeerde reden om weg te lopen.",
    "safety_t6_t": "Melden & blokkeren",
    "safety_t6_b": "Wie je een ongemakkelijk gevoel geeft, kun je met één tik blokkeren en melden. Ons team bekijkt meldingen — slecht gedrag aankaarten houdt de hele nacht veiliger voor iedereen.",
    "safety_t7_t": "Bescherm je persoonlijke gegevens",
    "safety_t7_b": "Houd gesprekken binnen 2NIGHT tot je iemand vertrouwt. Deel niet je thuisadres, werkplek, financiële gegevens of documenten, en wees voorzichtig met foto’s die precies laten zien waar je woont.",
    "safety_t8_t": "Jij hebt de controle",
    "safety_t8_b": "Jij bepaalt wanneer je live bent, hoe ver je straal reikt en wat je deelt. Wij doen geen achtergrondcontroles, dus je eigen oordeel staat altijd voorop.",
    "safety_help_t": "Bel bij nood om hulp.",
    "safety_help_p": "Als je je ooit onveilig of bedreigd voelt, neem dan eerst contact op met de lokale hulpdiensten. Om iemand of iets bij ons te melden, mail je ons team — we lezen elk bericht.",
    "cookie_text": "We gebruiken cookies om 2NIGHT te laten werken en om te begrijpen hoe de site wordt gebruikt.",
    "cookie_accept": "Accepteren",
