    "founders_title": "Twee vrienden, één koppig idee",
    "founders_role": "Oprichter & Partner · Zwitserland",
    "founders_p1": "Hugo en Jeric, twee vrienden uit Zwitserland, liepen steeds tegen dezelfde muur aan: steden vol mensen, groepschats vol „we moeten snel afspreken“ en niemand die vanavond echt op pad is.",
    "founders_p2": "Hugo, de oprichter, schrijft de code. Jeric, zijn partner, leidt het project en geeft vorm aan de ervaring. Van een Zwitserse keukentafel tot waar jij vanavond staat — dat is het hele verhaal.",
