    "cg1_b": "Gebruik je eigen foto's en echte gegevens. Geen nepprofielen, identiteitsfraude of catfishing.",
    "cg1_t": "Wees echt",
    "cg2_b": "Geen intimidatie, haat, bedreigingen of ongevraagde expliciete content. Behandel mensen zoals je zelf behandeld wilt worden.",
    "cg2_t": "Wees respectvol",
    "cg3_b": "2NIGHT is uitsluitend voor volwassenen. Iedereen die minderjarig is, wordt direct verwijderd.",
