    "disc_p1": "De meeste dating-apps plannen een koffie over drie weken. 2NIGHT is gemaakt voor de uren tussen nu en 2 uur 's nachts — het moment waarop plannen echt gebeuren. Ga live, zie wie er bij jou in de buurt op stap is, ping, match en ontmoet.",
