    "gal_membership_s": "Silver · Gold · Platinum",
    "gal_profile_t": "Profil",
    "gal_profile_s": "Ty, po zmroku",
    "tiers_note": "Ceny w USD, mogą się różnić w zależności od regionu. Płatne plany są rozliczane przez Apple App Store i odnawiają się automatycznie do momentu anulowania — zarządzaj nimi lub anuluj w dowolnej chwili w ustawieniach App Store. Zobacz nasz Regulamin.",
    "auth_login": "Zaloguj się",
    "cg1_b": "Używaj własnych zdjęć i prawdziwych danych. Żadnych fałszywych profili, podszywania się ani catfishingu.",
    "cg1_t": "Bądź sobą",
    "cg2_b": "Żadnego nękania, mowy nienawiści, gróźb ani niechcianych treści o charakterze jednoznacznym. Traktuj innych tak, jak sam chciałbyś być traktowany.",
    "cg2_t": "Szanuj innych",
    "cg3_b": "2NIGHT jest wyłącznie dla dorosłych. Każda niepełnoletnia osoba zostaje natychmiast usunięta.",
    "cg3_t": "Tylko 18 lat i więcej",
    "cg4_b": "Żadnej sprzedaży, escortu, naganiania, oszustw ani proszenia członków o pieniądze, prezenty czy krypto.",
    "cg4_t": "Bez pieniędzy, bez biznesu",
    "cg5_b": "Nie nagrywaj ani nie udostępniaj nikogo bez zgody, żadnego doxxingu, żadnego udostępniania prywatnych informacji.",
    "cg5_t": "Tylko za obopólną zgodą",
    "cg6_b": "Blokuj i zgłaszaj każdego, kto przekracza granicę. Nasz zespół sprawdza każde zgłoszenie — zgłaszanie utrzymuje noc bezpieczną.",
    "cg6_t": "Zgłaszaj to, co złe",
    "cg_contact": "Widzisz coś poważnego? Napisz do nas — czytamy każdą wiadomość.",
    "cg_kicker": "Społeczność",
    "cg_lead": "2NIGHT działa tylko wtedy, gdy jest bezpiecznie i prawdziwie. Te zasady utrzymują dobrą noc dla wszystkich — złam je, a wylatujesz.",
    "cg_title": "Zasady społeczności",
    "community_meta": "Zasady społeczności 2NIGHT — reguły, które utrzymują noc bezpieczną i prawdziwą.",
    "cta_join": "Dołącz do listy oczekujących",
    "cta_sub2": "Bądź pierwszy. Najwcześniejsi członkowie rządzą nocą — za darmo.",
    "disc_f1_b": "Ustaw swój status, a miasto widzi, że jesteś wolny dziś wieczorem. Ty decydujesz kto, jak daleko i jak długo.",
    "disc_f1_t": "Wejdź na żywo jednym dotknięciem",
    "disc_f2_b": "Prawdziwi ludzie w pobliżu, wolni właśnie teraz, chcący tego samego. Żadnego niekończącego się przewijania ku „kiedyś”.",
    "disc_f2_t": "Tonight Feed",
    "disc_f3_b": "Wzajemne zainteresowanie otwiera czat. Ustalcie plan i spotkajcie się — na żywo, tej samej nocy.",
    "disc_f3_t": "Ping, match, spotkanie",
    "disc_f4_b": "Od twojej ulicy po całe miasto. Twoje członkostwo ustala, jak daleko sięga noc.",
    "disc_f4_t": "Twój promień, twoja noc",
    "disc_feat_t": "Stworzone, by wyciągnąć cię za drzwi",
