    "waitlist_done": "Вы в списке. До встречи вечером.",
    "about_kicker": "О 2NIGHT",
    "about_title": "Сегодня, а не завтра.",
    "about_lead": "2NIGHT — для того момента, когда в семь вечера ты решаешь, что и правда хочешь чем-то заняться, и хочешь, чтобы рядом были реальные люди, которым хочется того же.",
    "about_story_pull": "Большинство вечеров умирает в групповом чате. «Надо бы скоро встретиться.» Это «скоро» никогда не наступает.",
    "about_story_t": "Вечер, в который ты и правда выходишь",
    "about_story_p1": "2NIGHT построен вокруг одной упрямой мысли: лучшие вечера не планируют за три недели. Они случаются, потому что кто-то где-то рядом свободен прямо сейчас и готов сорваться с места. Мы сделали приложение, которое превращает этот порыв в настоящий план — быстро, вживую, сегодня вечером.",
    "about_story_p2": "Задай статус одной строкой. Смотри, кто вышел рядом с тобой. Ping, мэтч, встреча. Никаких бесконечных свайпов в сторону «может, на следующей неделе». Только те, кто вышел сегодня, и самый короткий путь к тому, чтобы оказаться в одной комнате.",
    "about_world_t": "По всему миру, без привязки к городу",
    "about_world_p1": "2NIGHT не открывается город за городом. Он работает в любой точке мира — с людьми рядом с тобой, где бы ты ни оказался сегодня вечером. Прилетел в новый город — а ночь уже идёт.",
    "about_world_p2": "Ты решаешь, как далеко он дотянется. Выбери свой радиус — от своей улицы до всего города — и 2NIGHT покажет, кто вышел внутри него.",
    "about_who1_t": "Путешественники",
    "about_who1_b": "Новый город, ни одного контакта, один вечер, чтобы он того стоил. Открой 2NIGHT — и местная ночь уже перед тобой.",
    "about_who2_t": "Экспаты",
    "about_who2_b": "Строишь жизнь на новом месте. Знакомься с теми, кто вышел сегодня там, что ты теперь называешь домом.",
    "about_who3_t": "Местные",
    "about_who3_b": "Ты знаешь город — тебе просто нужна компания на сегодня. Задай статус и найди своих людей, без всякого календаря.",
    "about_design_t": "Создано для ночи",
    "about_design_p": "Тёплый шампанский оттенок на глубоком антраците. Редакционное, тихое и слегка закрытое — сделано так, чтобы ощущаться как лучшая комната в городе, а не очередная шумная лента. Каждый экран — для тех, кто решает поздно и действует быстро.",
    "support_kicker": "Поддержка",
    "support_title": "Чем мы можем помочь?",
    "support_lead": "Всё, что нужно знать о 2NIGHT, — и живой человек на другом конце, когда он тебе нужен.",
    "faq_q7": "Как вы обращаетесь с моей приватностью?",
    "faq_a7": "Мы собираем только то, что нужно, чтобы помочь тебе познакомиться сегодня вечером, и никогда не продаём твои персональные данные. Ты сам выбираешь, что видно другим и когда делиться геолокацией. Все подробности — в нашей Политике конфиденциальности.",
    "faq_a7_link": "Политика конфиденциальности",
