    "testimonials_sub": "Первые бета-ночи — их собственными словами.",
    "testimonials_note": "Цитаты бета-пользователей. Имена и города приведены для примера.",
    "testimonial1_q": "Я прилетел в Лиссабон без всяких планов. К девяти вечера я был на крыше-баре с тремя людьми, с которыми только что состыковался. Вот и всё приложение за одну ночь.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Лиссабон",
    "testimonial2_q": "Больше никаких «надо как-нибудь встретиться». Я задала статус, увидела, кто свободен, и в тот же вечер реально с кем-то встретилась. Наконец-то.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Париж",
    "testimonial3_q": "Black Events — это нечто. Это похоже не столько на приложение, сколько на приглашение в лучшее место города.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Дубай",
    "testimonial4_q": "Новый город по работе, не знал ни души. Через две недели у меня настоящий круг общения — и всё потому, что в семь вечера я решил не сидеть дома.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Берлин",
    "testimonial5_q": "Быстро, красиво и реально уважает твоё время. Ping, match, встреча — ровно как обещано.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "Лондон",
    "testimonial6_q": "Travel Mode — это чит-код. Я открываю 2NIGHT в ту же секунду, как приземляюсь, а местная ночь уже ждёт.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "Нью-Йорк",
    "safety_kicker": "Безопасность",
    "safety_title": "Знакомься с людьми с умом.",
    "safety_lead": "2NIGHT создан для спонтанных ночей в реальной жизни. Несколько простых привычек делают их приятными — и держат всё под твоим контролем, когда ты знакомишься с кем-то новым.",
    "safety_t1_t": "Встречайтесь в публичном месте",
    "safety_t1_b": "Для первой встречи выбирай людное и хорошо освещённое место — бар, кафе, популярную точку. Оставайся на людях, пока действительно не почувствуешь себя комфортно, и не отправляйся в укромное место с тем, кого только что встретил.",
    "safety_t2_t": "Расскажи другу о своих планах",
    "safety_t2_b": "Дай знать тому, кому доверяешь, куда ты идёшь, с кем встречаешься и когда планируешь вернуться. Поделись с ним своей геопозицией в реальном времени на эту ночь и отпишись после встречи.",
    "safety_t3_t": "Позаботься о транспорте сам",
    "safety_t3_b": "Добирайся туда и обратно на своих условиях. Держи телефон заряженным, знай, как доберёшься домой, и ты волен уйти в любой момент — без объяснений.",
    "safety_t4_t": "Никогда не отправляй деньги",
    "safety_t4_b": "Никогда не отправляй деньги, подарочные карты или крипту тому, кого встретил в приложении, какой бы ни была история. Просьбы о наличных, финансовой помощи или инвестиционных «советах» — это классическое мошенничество: остановись и сообщи о них.",
    "safety_t5_t": "Доверяй интуиции",
    "safety_t5_b": "Если что-то кажется неправильным, скорее всего, так и есть. Ты никому не должен своего времени. Заверши переписку, уйди со встречи или позвони другу — нет неправильной причины, чтобы уйти.",
    "safety_t6_t": "Жалоба и блокировка",
    "safety_t6_b": "Любого, кто доставляет тебе дискомфорт, можно заблокировать и пожаловаться на него в одно касание. Наша команда проверяет жалобы — сигналы о плохом поведении делают всю ночь безопаснее для всех.",
    "safety_t7_t": "Береги личную информацию",
    "safety_t7_b": "Веди переписку внутри 2NIGHT, пока не начнёшь доверять человеку. Не сообщай домашний адрес, место работы, финансовые данные или документы и будь осторожен с фото, которые выдают, где именно ты живёшь.",
    "safety_t8_t": "Всё под твоим контролем",
    "safety_t8_b": "Ты решаешь, когда быть в эфире, как далеко простирается твой радиус и чем ты делишься. Мы не проводим проверок биографии, поэтому твоё собственное суждение всегда на первом месте.",
    "safety_help_t": "В экстренной ситуации зови на помощь.",
    "safety_help_p": "Если ты когда-либо почувствуешь себя в опасности или под угрозой, сначала свяжись с местными экстренными службами. Чтобы сообщить нам о ком-то или о чём-то, напиши нашей команде — мы читаем каждое сообщение.",
    "cookie_text": "Мы используем файлы cookie, чтобы 2NIGHT работал и чтобы понимать, как используется сайт.",
    "cookie_accept": "Принять",
    "cookie_decline": "Только необходимые",
    "cookie_privacy_link": "Конфиденциальность и cookie",
    "cookie_aria": "Согласие на cookie",
    "founders_title": "Двое друзей, одна упрямая идея",
    "founders_role": "Основатель и партнёр · Швейцария",
    "founders_p1": "Hugo и Jeric, двое друзей из Швейцарии, постоянно упирались в одну и ту же стену: города, полные людей, групповые чаты, полные «надо как-нибудь встретиться», и никого, кто реально вышел бы сегодня вечером.",
    "founders_p2": "Hugo, основатель, пишет код. Jeric, его партнёр, ведёт проект и формирует впечатление. От кухонного стола в Швейцарии до того места, где ты стоишь сегодня вечером, — вот и вся история.",
    "founders_sign": "— Hugo и Jeric · Швейцария",
    "about_cta_t": "Выйди сегодня вечером.",
