    "gal_profile_t": "Профиль",
    "gal_profile_s": "Ты, когда стемнеет",
    "tiers_note": "Цены в USD и могут отличаться в зависимости от региона. Платные подписки оплачиваются через Apple App Store и продлеваются автоматически до отмены — управляйте подпиской или отмените её в любой момент в настройках App Store. См. наши Условия.",
    "auth_login": "Войти",
    "cg1_b": "Используйте собственные фото и реальные данные. Никаких фейковых профилей, выдачи себя за другого или кэтфишинга.",
    "cg1_t": "Будьте настоящими",
    "cg2_b": "Никаких домогательств, ненависти, угроз или нежелательного откровенного контента. Относитесь к людям так, как хотите, чтобы относились к вам.",
    "cg2_t": "Будьте уважительны",
    "cg3_b": "2NIGHT — строго для взрослых. Любой несовершеннолетний удаляется немедленно.",
    "cg3_t": "Только 18 и старше",
    "cg4_b": "Никаких продаж, эскорта, навязывания услуг, мошенничества или просьб к участникам о деньгах, подарках или криптовалюте.",
    "cg4_t": "Без денег, без бизнеса",
    "cg5_b": "Не записывайте и не делитесь никем без согласия, никакого доксинга, никакого распространения личной информации.",
    "cg5_t": "Только по обоюдному согласию",
    "cg6_b": "Блокируйте и жалуйтесь на каждого, кто переходит черту. Наша команда рассматривает каждую жалобу — это сохраняет ночь безопасной.",
    "cg6_t": "Сообщайте о нарушениях",
    "cg_contact": "Заметили что-то серьёзное? Напишите нам — мы читаем каждое сообщение.",
    "cg_kicker": "Сообщество",
    "cg_lead": "2NIGHT работает, только когда всё безопасно и по-настоящему. Эти правила сохраняют ночь хорошей для всех — нарушите их, и вы выбываете.",
    "cg_title": "Правила сообщества",
    "community_meta": "Правила сообщества 2NIGHT — правила, которые сохраняют ночь безопасной и настоящей.",
    "cta_join": "Записаться в список ожидания",
    "cta_sub2": "Будьте первыми. Самые ранние участники владеют ночью — бесплатно.",
    "disc_f1_b": "Установите статус, и город увидит, что вы свободны сегодня вечером. Вы решаете кто, как далеко и как долго.",
    "disc_f1_t": "В эфир одним касанием",
    "disc_f2_b": "Реальные люди рядом с вами, свободные прямо сейчас, желающие того же. Никаких бесконечных свайпов в сторону «когда-нибудь».",
    "disc_f2_t": "Tonight Feed",
    "disc_f3_b": "Взаимный интерес открывает чат. Составьте план и встретьтесь — лично, той же ночью.",
    "disc_f3_t": "Пинг, мэтч, встреча",
    "disc_f4_b": "От вашей улицы до всего города. Ваше членство определяет, как далеко простирается ночь.",
    "disc_f4_t": "Ваш радиус, ваша ночь",
    "disc_feat_t": "Создано, чтобы вытащить вас из дома",
    "disc_kicker": "Узнать",
    "disc_lead": "Приложение для знакомств на одну ночь для тех, кто в 19:00 решает, что хочет кого-то встретить — сегодня, а не завтра.",
    "disc_p1": "Большинство приложений для знакомств назначают кофе через три недели. 2NIGHT создано для часов между «сейчас» и 2 часами ночи — окном, когда планы действительно случаются. Выходите в эфир, смотрите, кто рядом, пингуйте, мэтчитесь и встречайтесь.",
    "disc_title": "Что такое 2NIGHT?",
    "discover_meta": "Узнайте о 2NIGHT — что такое приложение для знакомств на одну ночь и как оно работает.",
    "hero_cta_how": "Посмотреть, как это работает",
