    "nav_join": "Записаться в список ожидания",
    "sec1_b": "Вы решаете, когда вы в эфире, как далеко простирается ваш радиус и чем вы делитесь. Уйдите офлайн — и вы исчезнете.",
    "sec1_t": "Вы всегда под контролем",
    "sec2_b": "Видеть вас могут только люди внутри радиуса и выбранной вами аудитории, и только пока вы в эфире.",
    "sec2_t": "Приватно по умолчанию",
    "sec3_b": "Шифруется при передаче, доступ строго ограничен и никогда не продаётся. Подробности — в нашей Политике конфиденциальности.",
    "sec3_t": "Ваши данные под защитой",
    "sec4_b": "Любого, кто вызывает у вас дискомфорт, можно мгновенно заблокировать и пожаловаться. Наша команда рассматривает каждую жалобу.",
    "sec4_t": "Блокировка и жалоба в одно касание",
    "sec_contact": "Вопросы о безопасности или конфиденциальности? Пишите на support@2night.co.",
    "sec_kicker": "Доверие и безопасность",
    "sec_lead": "Знакомство с новыми людьми должно быть волнующим, а не рискованным. Вот как 2NIGHT защищает вас и ваши данные.",
    "sec_note": "Важно: 2NIGHT не проводит проверок биографии или личности. Встречайтесь в публичных местах, предупредите друга и доверяйте интуиции — см. наши Советы по безопасности.",
    "sec_title": "Ваша безопасность — по замыслу.",
