    "faq_q3": "Чим це відрізняється від інших застосунків для знайомств?",
    "faq_a3": "Жодного нескінченного свайпу в бік «колись». 2NIGHT показує, хто поруч із тобою просто зараз, і допомагає справді зустрітися — сьогодні ввечері, а не за три тижні.",
    "faq_q4": "Це безпечно?",
    "faq_a4": "Ти сам вирішуєш, коли бути онлайн, наскільки далеко сягає твій радіус і чим ділитися. Блокуй і скаржся одним дотиком, а перейшовши в офлайн, зникаєш миттєво. Будь ласка, ознайомся з нашими порадами щодо безпеки перед зустріччю.",
    "faq_q5": "Що я отримаю, приєднавшись рано?",
    "faq_a5": "Перші 20 учасників отримують рік Platinum Black безкоштовно. Наступні 200 отримують Gold безкоштовно. Найперші учасники володіють ніччю.",
    "faq_q6": "Ви продаєте мої дані?",
    "faq_a6": "Ніколи. Ми не продаємо твої персональні дані й не ведемо стороннє рекламне відстеження. Ти завжди контролюєш ситуацію — переглянь свої налаштування приватності.",
    "sticky_note": "Приєднання безкоштовне · 18+",
    "aria_menu": "Меню",
    "disclaimer_html": "<strong>2NIGHT призначений для дорослих віком від 18 років.</strong> 2NIGHT незабаром запускається; деякі функції та завантаження з App Store можуть бути ще недоступні у вашому регіоні. Екрани застосунку та фотографії наведені лише для ілюстрації, а відгуки отримані від користувачів бета-версії та є репрезентативними. 2NIGHT допомагає людям знайомитися, але <strong>не</strong> проводить перевірку біографії чи особи — будь ласка, ознайомтеся з нашими рекомендаціями щодо <a href=\"/safety\">Безпеки</a> та зустрічайтеся відповідально. Використовуючи 2NIGHT, ви погоджуєтеся з нашими <a href=\"/terms\">Умовами</a> та <a href=\"/privacy\">Політикою конфіденційності</a>. Apple, логотип Apple та App Store є товарними знаками Apple Inc.; 2NIGHT не пов’язаний з Apple Inc., не спонсорується та не схвалюється нею.",
