    "pc_kicker": "Ваша приватність",
    "pc_title": "Ваш вибір щодо приватності",
    "pc_lead": "Ви повністю керуєте своїми даними в 2NIGHT. Ось як будь-коли скористатися своїми правами на приватність.",
