    "pc_note": "Ці можливості доступні кожному й усюди — зокрема права, надані GDPR (ЄС/Велика Британія) та CCPA/CPRA (California). Ми ніколи не стягуватимемо плату й не ставитимемося до вас інакше за їх використання.",
