    "gal_membership_t": "Підписка",
    "gal_membership_s": "Silver · Gold · Platinum",
    "gal_profile_t": "Профіль",
    "gal_profile_s": "Ти, коли стемніє",
    "tiers_note": "Ціни в USD і можуть відрізнятися залежно від регіону. Платні підписки оплачуються через Apple App Store і поновлюються автоматично до скасування — керуйте підпискою або скасуйте її будь-коли в налаштуваннях App Store. Перегляньте наші Умови.",
    "auth_login": "Увійти",
    "cg1_b": "Використовуйте власні фото та справжні дані. Жодних фейкових профілів, видавання себе за іншого чи кетфішингу.",
    "cg1_t": "Будьте справжніми",
    "cg2_b": "Жодних домагань, ненависті, погроз чи небажаного відвертого контенту. Ставтеся до людей так, як хотіли б, щоб ставилися до вас.",
    "cg2_t": "Будьте шанобливими",
