    "cg3_t": "Лише 18 і старше",
    "cg4_b": "Жодних продажів, ескорту, нав’язування послуг, шахрайства чи прохань до учасників про гроші, подарунки чи крипту.",
    "cg4_t": "Без грошей, без бізнесу",
