    "disc_f2_t": "Tonight Feed",
    "disc_f3_b": "Взаємний інтерес відкриває чат. Складіть план і зустріньтеся — особисто, тієї ж ночі.",
    "disc_f3_t": "Пінг, метч, зустріч",
