    "disc_p1": "Більшість застосунків для знайомств призначають каву за три тижні. 2NIGHT створено для годин між «зараз» і 2-ю ночі — вікном, коли плани справді відбуваються. Виходьте в ефір, дивіться, хто поруч, пінгуйте, метчтеся та зустрічайтеся.",
