    "sec3_t": "Ваші дані під захистом",
    "sec4_b": "Будь-кого, хто викликає у вас дискомфорт, можна миттєво заблокувати та поскаржитися. Наша команда розглядає кожне повідомлення.",
    "sec4_t": "Блокування й скарга в один дотик",
    "sec_contact": "Питання про безпеку чи конфіденційність? Пишіть на support@2night.co.",
