    "tiers_note": "Ceny v USD a mohou se lišit podle regionu. Placené plány se účtují přes Apple App Store a automaticky se obnovují až do zrušení — kdykoli je spravuj nebo zruš v nastavení App Store. Přečti si naše Podmínky.",
    "auth_login": "Přihlásit se",
    "cg1_b": "Používej vlastní fotky a skutečné údaje. Žádné falešné profily, vydávání se za někoho jiného ani catfishing.",
    "cg1_t": "Buď sám sebou",
    "cg2_b": "Žádné obtěžování, nenávist, výhrůžky ani nevyžádaný explicitní obsah. Chovej se k lidem tak, jak bys chtěl, aby se chovali k tobě.",
    "cg2_t": "Buď ohleduplný",
    "cg3_b": "2NIGHT je výhradně pro dospělé. Každý nezletilý je okamžitě odstraněn.",
    "cg3_t": "Pouze 18 a více",
    "cg4_b": "Žádný prodej, eskort, nabízení služeb, podvody ani žádosti o peníze, dárky nebo krypto od členů.",
    "cg4_t": "Žádné peníze, žádný byznys",
    "cg5_b": "Nikoho nenahrávej ani nesdílej bez souhlasu, žádný doxxing, žádné sdílení soukromých informací.",
    "cg5_t": "Vždy se vzájemným souhlasem",
    "cg6_b": "Zablokuj a nahlas každého, kdo překročí hranici. Náš tým prověřuje každé nahlášení — hlášení udržuje noc bezpečnou.",
    "cg6_t": "Nahlas, co je špatně",
    "cg_contact": "Vidíš něco vážného? Napiš nám — čteme každou zprávu.",
    "cg_kicker": "Komunita",
    "cg_lead": "2NIGHT funguje, jen když je to bezpečné a opravdové. Tato pravidla udržují noc dobrou pro všechny — poruš je a končíš.",
    "cg_title": "Pravidla komunity",
    "community_meta": "Pravidla komunity 2NIGHT — pravidla, která udržují noc bezpečnou a opravdovou.",
    "cta_join": "Přidat se na čekací listinu",
    "cta_sub2": "Buď první. Nejranější členové vládnou noci — zdarma.",
    "disc_f1_b": "Nastav svůj status a město uvidí, že máš dnes večer volno. Ty rozhoduješ kdo, jak daleko a jak dlouho.",
    "disc_f1_t": "Jdi naživo jedním klepnutím",
    "disc_f2_b": "Skuteční lidé poblíž tebe, právě teď volní, chtějící totéž. Žádné nekonečné swipování směrem k „někdy“.",
    "disc_f2_t": "Tonight Feed",
    "disc_f3_b": "Vzájemný zájem otevře chat. Domluvte si plán a sejděte se — osobně, tu samou noc.",
    "disc_f3_t": "Ping, match, sraz",
    "disc_f4_b": "Od tvé ulice po celé město. Tvoje členství určuje, jak daleko noc dosáhne.",
    "disc_f4_t": "Tvůj poloměr, tvoje noc",
    "disc_feat_t": "Stvořeno, aby tě dostalo ven ze dveří",
    "disc_kicker": "Objev",
    "disc_lead": "Seznamovací appka na jednu noc pro lidi, kteří se v 19:00 rozhodnou, že chtějí někoho poznat — dnes večer, ne zítra.",
    "disc_p1": "Většina seznamovacích appek naplánuje kávu za tři týdny. 2NIGHT je stvořeno pro hodiny mezi teď a 2 ráno — okno, kdy se plány skutečně stávají. Jdi naživo, podívej se, kdo je venku poblíž tebe, pingni, matchni a sejdi se.",
    "disc_title": "Co je 2NIGHT?",
    "discover_meta": "Objev 2NIGHT — co je seznamovací appka na jednu noc a jak funguje.",
    "hero_cta_how": "Podívej se, jak to funguje",
    "nav_blog": "Blog",
    "nav_community": "Komunita",
    "nav_discover": "Objev",
    "nav_join": "Přidat se na čekací listinu",
    "sec1_b": "Ty rozhoduješ, kdy jsi naživo, jak daleko sahá tvůj poloměr a co sdílíš. Přejdi do offline a zmizíš.",
    "sec1_t": "Máš to vždy pod kontrolou",
    "sec2_b": "Vidět tě mohou jen lidé v rámci poloměru a publika, které si zvolíš, a jen když jsi naživo.",
    "sec2_t": "Soukromé ve výchozím nastavení",
    "sec3_b": "Šifrováno při přenosu, přístup přísně omezen a nikdy se neprodává. Podrobnosti si přečti v našich Zásadách ochrany soukromí.",
    "sec3_t": "Tvoje data, chráněná",
    "sec4_b": "Kohokoli, kdo tě znepříjemňuje, můžeš okamžitě zablokovat a nahlásit. Náš tým prověřuje každé nahlášení.",
    "sec4_t": "Zablokuj a nahlas jedním klepnutím",
    "sec_contact": "Otázky ohledně bezpečnosti nebo soukromí? Napiš na support@2night.co.",
    "sec_kicker": "Důvěra a bezpečnost",
    "sec_lead": "Poznávání nových lidí by mělo být vzrušující, ne riskantní. Takto 2NIGHT chrání tebe a tvoje data.",
    "sec_note": "Důležité: 2NIGHT neprovádí prověřování minulosti ani totožnosti. Scházej se na veřejnosti, řekni to kamarádovi a věř svému instinktu — viz naše Tipy pro bezpečnost.",
