    "stat_zero_sub": "reclame, trackere sau date vândute",
    "faq_kicker": "Bine de știut",
    "faq_title": "Întrebări, cu răspunsuri.",
    "faq_q1": "2NIGHT este gratuit?",
    "faq_a1": "Da. Înscrierea în 2NIGHT și cunoașterea oamenilor sunt gratuite. Urmează un abonament plătit și vei vedea exact cât costă în aplicație, înainte să ți se perceapă ceva.",
    "faq_q2": "Când se lansează în orașul meu?",
    "faq_a2": "Deschidem orașele în valuri. Înscrie-te pe lista de așteptare și îți scriem în clipa în care 2NIGHT devine disponibil lângă tine.",
    "faq_q3": "Prin ce se deosebește de alte aplicații de dating?",
    "faq_a3": "Gata cu swipe-ul la nesfârșit către „cândva”. 2NIGHT îți arată cine e prin preajmă chiar acum și te ajută să te întâlnești cu adevărat — diseară, nu peste trei săptămâni.",
    "faq_q4": "Este sigur?",
    "faq_a4": "Tu decizi când ești online, cât de departe ajunge raza ta și ce dezvălui. Blochezi și raportezi dintr-o atingere, iar trecând offline dispari instantaneu. Te rugăm să citești ghidul nostru de siguranță înainte de a te întâlni.",
    "faq_q5": "Ce primesc dacă mă înscriu devreme?",
    "faq_a5": "Primii 20 de membri primesc un an de Platinum Black, gratuit. Următorii 200 primesc Gold gratuit. Cei mai timpurii membri stăpânesc noaptea.",
    "faq_q6": "Îmi vindeți datele?",
    "faq_a6": "Niciodată. Nu îți vindem datele personale și nu rulăm urmărire publicitară a terților. Ești mereu la control — vezi-ți opțiunile de confidențialitate.",
    "sticky_note": "Înscriere gratuită · 18+",
    "aria_menu": "Meniu",
    "disclaimer_html": "<strong>2NIGHT este destinat adulților cu vârsta de 18 ani și peste.</strong> 2NIGHT se lansează în curând; este posibil ca unele funcții și descărcarea din App Store să nu fie încă disponibile în regiunea ta. Ecranele aplicației și fotografiile au doar scop ilustrativ, iar testimonialele provin de la utilizatori beta și sunt reprezentative. 2NIGHT ajută oamenii să se cunoască, dar <strong>nu</strong> efectuează verificări de fundal sau de identitate — te rugăm să citești recomandările noastre de <a href=\"/safety\">Siguranță</a> și să te întâlnești responsabil. Utilizând 2NIGHT, ești de acord cu <a href=\"/terms\">Termenii</a> și <a href=\"/privacy\">Politica de confidențialitate</a>. Apple, logoul Apple și App Store sunt mărci comerciale ale Apple Inc.; 2NIGHT nu este afiliat, sponsorizat sau susținut de Apple Inc.",
