    "pc2_b": "Șterge-ți contul oricând din Setări → Cont → Șterge contul sau scrie-ne pe e-mail. Îți ștergem datele, sub rezerva oricărei perioade legale de păstrare.",
    "pc3_t": "Renunță la marketing",
