    "pc4_t": "Nu vindem și nu partajăm",
    "pc4_b": "Nu îți vindem niciodată datele personale și nu le partajăm niciodată pentru publicitate comportamentală între contexte — așa că nu ai la ce să renunți.",
    "pc5_t": "Gestionează cookie-urile",
    "pc5_b": "Modifică-ți oricând preferințele pentru cookie-uri și urmărire prin bannerul de cookie-uri sau din setările browserului.",
    "pc6_t": "Locație și permisiuni",
    "pc6_b": "Controlează accesul la locație, cameră și notificări din setările dispozitivului tău și revocă oricare dintre ele oricând dorești.",
    "pc_note": "Aceste opțiuni sunt disponibile pentru toată lumea, oriunde — inclusiv drepturile acordate de GDPR (UE/UK) și de CCPA/CPRA (California). Nu îți vom percepe niciodată vreo taxă și nu te vom trata diferit pentru că le folosești.",
