    "disc_p1": "Majoritatea aplicațiilor de dating programează o cafea peste trei săptămâni. 2NIGHT e creat pentru orele dintre acum și 2 noaptea — fereastra în care planurile chiar se întâmplă. Intră live, vezi cine e prin preajmă, dă ping, fă match și întâlnește-te.",
