    "pc_kicker": "Az adatvédelmed",
    "pc_title": "Adatvédelmi döntéseid",
    "pc_lead": "A 2NIGHT-on te rendelkezel az adataid felett. Így élhetsz bármikor az adatvédelmi jogaiddal.",
    "pc1_t": "Hozzáférés az adataidhoz",
    "pc1_b": "Kérj másolatot a rólad tárolt személyes adatokról, és elküldjük neked.",
    "pc2_t": "Fiók és adatok törlése",
    "pc2_b": "A fiókodat bármikor törölheted a Beállítások → Fiók → Fiók törlése menüpontban, vagy írj nekünk e-mailt. Töröljük az adataidat, a törvény által előírt megőrzési kötelezettségek függvényében.",
    "pc3_t": "Marketing kikapcsolása",
    "pc3_b": "Kapcsold ki a promóciós e-maileket és a push-értesítéseket a Beállítások → Értesítések menüben, vagy használd a leiratkozási hivatkozást bármelyik e-mailben.",
    "pc4_t": "Nem adjuk el és nem osztjuk meg",
    "pc4_b": "Soha nem adjuk el a személyes adataidat, és soha nem osztjuk meg kontextusokon átívelő viselkedésalapú hirdetés céljából — így nincs is miről lemondanod.",
    "pc5_t": "Sütik kezelése",
    "pc5_b": "A sütik és a nyomkövetés beállításait bármikor módosíthatod a süti sávon vagy a böngésződ beállításain keresztül.",
    "pc6_t": "Helyzet és engedélyek",
    "pc6_b": "A helyadatokhoz, a kamerához és az értesítésekhez való hozzáférést az eszközöd beállításaiban szabályozhatod, és bármelyiket bármikor visszavonhatod.",
    "pc_note": "Ezek a lehetőségek mindenki számára, mindenhol elérhetők — beleértve a GDPR (EU/UK) és a CCPA/CPRA (California) által biztosított jogokat is. Soha nem számítunk fel díjat, és nem bánunk veled másként azért, mert élsz velük.",
    "pc_contact": "Adatvédelmi jogod gyakorlásához írj a privacy@2night.co címre — 30 napon belül válaszolunk.",
