    "founders_p1": "Hugo és Jeric, két svájci barát, mindig ugyanabba a falba ütközött: emberekkel teli városok, „nemsokára össze kéne jönnünk” üzenetekkel teli csoportok, és ma este senki sincs igazán kint.",
