    "disc_p1": "A legtöbb társkereső app három hét múlvára szervez egy kávét. A 2NIGHT a most és hajnali 2 közötti órákra készült — arra az ablakra, amikor a tervek tényleg megvalósulnak. Menj élőbe, nézd meg, ki van a közeledben, pingelj, matchelj és találkozz.",
