    "sec4_t": "Letiltás és jelentés egyetlen koppintással",
    "sec_contact": "Kérdésed van a biztonságról vagy az adatvédelemről? Írj a support@2night.co címre.",
    "sec_kicker": "Bizalom és biztonság",
    "sec_lead": "Új emberek megismerésének izgalmasnak kellene lennie, nem kockázatosnak. Így véd téged és az adataidat a 2NIGHT.",
    "sec_note": "Fontos: a 2NIGHT nem végez háttér- vagy személyazonossági ellenőrzést. Találkozz nyilvános helyen, szólj egy barátodnak, és bízz a megérzéseidben — lásd a Biztonsági tippjeinket.",
