    "faq_q1": "Är 2NIGHT gratis?",
    "faq_a1": "Ja. Det är gratis att gå med i 2NIGHT och att träffa folk. Ett betalt medlemskap är på väg, och du ser exakt vad det kostar i appen innan något debiteras.",
    "faq_q2": "När lanseras det i min stad?",
