    "faq_q3": "Hur skiljer det sig från andra dejtingappar?",
    "faq_a3": "Inget oändligt swipande mot ett ”någon gång”. 2NIGHT visar vilka som är ute nära dig just nu och hjälper dig att faktiskt träffas — i kväll, inte om tre veckor.",
    "faq_q4": "Är det säkert?",
    "faq_a4": "Du bestämmer när du är live, hur långt din radie når och vad du delar. Blockera och anmäl med en knapptryckning, och gå offline för att försvinna direkt. Läs gärna våra säkerhetsråd innan du träffas.",
    "faq_q5": "Vad får jag för att gå med tidigt?",
    "faq_a5": "De första 20 medlemmarna får ett år av Platinum Black, gratis. De nästa 200 får gratis Gold. De allra tidigaste medlemmarna äger natten.",
    "faq_q6": "Säljer ni mina data?",
