    "waitlist_done": "Du står på listan. Vi ses i kväll.",
    "about_kicker": "Om 2NIGHT",
    "about_title": "Ikväll, inte imorgon.",
    "about_lead": "2NIGHT är för stunden då du kl 19 bestämmer dig för att du faktiskt vill göra något — och vill ha riktiga människor nära dig som känner likadant.",
    "about_story_pull": "De flesta kvällar dör i en gruppchatt. ”Vi borde ses snart.” Snart kommer aldrig.",
    "about_story_t": "Kvällen då du faktiskt går ut",
    "about_story_p1": "2NIGHT byggdes kring en envis idé: de bästa kvällarna planeras inte tre veckor i förväg. De händer för att någon, någonstans i närheten, är ledig just nu och redo att dra. Vi gjorde appen som förvandlar den impulsen till en riktig plan — snabbt, på riktigt, ikväll.",
    "about_story_p2": "Sätt din status på en rad. Se vilka som är ute nära dig. Pinga, matcha, ses. Inget oändligt svajpande mot ”kanske nästa vecka”. Bara folket som är ute ikväll, och kortaste möjliga väg till att vara i samma rum.",
    "about_world_t": "Världen över, inte stad för stad",
    "about_world_p1": "2NIGHT rullas inte ut en stad i taget. Det funkar var som helst på jorden — med folk nära dig, var du än råkar vara ikväll. Landa i en ny stad och kvällen är redan igång.",
    "about_world_p2": "Du bestämmer hur långt det når. Välj din radie — från din gata till hela staden — och 2NIGHT visar vilka som är ute inom den.",
    "about_who1_t": "Resenärer",
    "about_who1_b": "Ny stad, inga kontakter, en kväll att få att räknas. Öppna 2NIGHT och den lokala kvällen ligger redan framför dig.",
    "about_who2_t": "Utlandsboende",
    "about_who2_b": "Du bygger ett liv på en ny plats. Träffa folk som är ute ikväll där du nu kallar hemma.",
    "about_who3_t": "Lokalbor",
    "about_who3_b": "Du kan staden — du vill bara ha sällskap för ikväll. Sätt din status och hitta ditt folk, utan kalender.",
    "about_design_t": "Designad för natten",
    "about_design_p": "Varm champagne mot djup antracit. Redaktionell, stillsam och en gnutta exklusiv — byggd för att kännas som stadens bästa rum, inte ännu ett stökigt flöde. Varje skärm är gjord för folk som bestämmer sent och rör sig snabbt.",
    "support_kicker": "Support",
    "support_title": "Hur kan vi hjälpa till?",
    "support_lead": "Allt du behöver veta om 2NIGHT — och en riktig människa i andra änden när du behöver det.",
    "faq_q7": "Hur hanterar ni min integritet?",
    "faq_a7": "Vi samlar bara in det som behövs för att hjälpa dig träffa folk ikväll, och vi säljer aldrig dina personuppgifter. Du väljer vad som syns för andra och när du delar din plats. Läs alla detaljer i vår integritetspolicy.",
    "faq_a7_link": "Integritetspolicy",
    "support_contact_t": "Behöver du fortfarande en hand?",
    "support_contact_p": "Mejla oss så hör en riktig person av sig. Vi läser varje meddelande.",
    "nav_safety": "Säkerhet",
    "nav_contact": "Kontakt",
    "footer_safety": "Säkerhet",
    "footer_contact": "Kontakt",
    "contact_kicker": "Kontakta oss",
    "screens_disclaimer": "Alla foton är endast för illustration.",
    "android_soon": "Android — kommer snart",
    "testimonials_kicker": "Från natten",
    "testimonials_title": "Vad våra användare sa om oss",
    "testimonials_sub": "Tidiga betanätter, med deras egna ord.",
    "testimonials_note": "Citat från betaanvändare. Namn och städer är representativa.",
    "testimonial1_q": "Jag landade i Lissabon utan några planer. Vid nio var jag på en takbar med tre personer jag precis matchat med. Det är hela appen på en enda kväll.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lissabon",
    "testimonial2_q": "Inga fler ”vi borde ses snart”. Jag satte min status, såg vilka som var lediga och träffade faktiskt någon samma kväll. Äntligen.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Paris",
    "testimonial3_q": "Black Events är overkligt bra. Det känns mindre som en app och mer som en inbjudan till stadens bästa rum.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "Ny stad för jobbet, kände ingen. Två veckor in har jag en riktig krets — allt för att jag vid sju bestämde att jag inte ville stanna hemma.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlin",
    "testimonial5_q": "Den är snabb, vacker och respekterar faktiskt din tid. Ping, match, möte — precis som lovat.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "London",
    "testimonial6_q": "Travel Mode är ett fuskkod. Jag öppnar 2NIGHT i samma sekund jag landar och stadens natt väntar redan.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "New York",
    "safety_kicker": "Säkerhet",
    "safety_title": "Träffa folk på det smarta sättet.",
    "safety_lead": "2NIGHT är byggt för spontana nätter i verkliga livet. Några enkla vanor håller dem roliga — och håller dig i kontroll när du träffar någon ny.",
    "safety_t1_t": "Ses på en offentlig plats",
    "safety_t1_b": "Välj ett livligt och välbelyst ställe för en första träff — en bar, ett kafé, ett populärt ställe. Stanna på en offentlig plats tills du verkligen känner dig trygg, och gå inte till en privat plats med någon du precis träffat.",
    "safety_t2_t": "Berätta dina planer för en vän",
    "safety_t2_b": "Låt någon du litar på veta vart du ska, vem du ska träffa och när du väntas vara tillbaka. Dela din liveplats med dem under kvällen och hör av dig efteråt.",
    "safety_t3_t": "Ordna din egen transport",
    "safety_t3_b": "Ta dig dit och hem på dina egna villkor. Håll telefonen laddad, vet hur du tar dig hem, och du är fri att gå när du vill — utan att behöva förklara.",
    "safety_t4_t": "Skicka aldrig pengar",
    "safety_t4_b": "Skicka aldrig pengar, presentkort eller krypto till någon du träffat i appen, oavsett historien. Förfrågningar om kontanter, ekonomisk hjälp eller investerings­”tips” är klassiska bedrägerier — sluta och anmäl dem.",
    "safety_t5_t": "Lita på din magkänsla",
    "safety_t5_b": "Om något känns fel är det förmodligen det. Du är aldrig skyldig någon din tid. Avsluta chatten, lämna träffen eller ring en vän — det finns ingen fel anledning att gå därifrån.",
    "safety_t6_t": "Anmäl och blockera",
    "safety_t6_b": "Vem som helst som får dig att känna dig obekväm kan blockeras och anmälas med en knapptryckning. Vårt team granskar anmälningar — att flagga dåligt beteende gör hela natten tryggare för alla.",
    "safety_t7_t": "Skydda dina personuppgifter",
    "safety_t7_b": "Håll chatten inom 2NIGHT tills du litar på någon. Dela inte din hemadress, arbetsplats, ekonomiska uppgifter eller dokument, och var eftertänksam med foton som avslöjar exakt var du bor.",
    "safety_t8_t": "Du har kontrollen",
    "safety_t8_b": "Du bestämmer när du är live, hur långt din radie sträcker sig och vad du delar. Vi gör inga bakgrundskontroller, så ditt eget omdöme kommer alltid först.",
    "safety_help_t": "Ring efter hjälp i en nödsituation.",
    "safety_help_p": "Om du någonsin känner dig otrygg eller hotad, kontakta först de lokala räddningstjänsterna. För att anmäla någon eller något till oss, mejla vårt team — vi läser varje meddelande.",
    "cookie_text": "Vi använder cookies för att 2NIGHT ska fungera och för att förstå hur webbplatsen används.",
    "cookie_accept": "Acceptera",
    "cookie_decline": "Endast nödvändiga",
    "cookie_privacy_link": "Integritet och cookies",
    "cookie_aria": "Cookie-samtycke",
    "founders_title": "Två vänner, en envis idé",
    "founders_role": "Grundare & Delägare · Schweiz",
    "founders_p1": "Hugo och Jeric, två vänner från Schweiz, stötte hela tiden på samma vägg: städer fulla av människor, gruppchattar fulla av ”vi borde ses snart” och ingen som faktiskt var ute i kväll.",
    "founders_p2": "Hugo, grundaren, skriver koden. Jeric, hans delägare, driver projektet och formar upplevelsen. Från ett schweiziskt köksbord till var du än står i kväll — det är hela historien.",
