    "disc_p1": "De flesta dejtingappar bokar in en kaffe tre veckor framåt. 2NIGHT är byggd för timmarna mellan nu och klockan 2 på natten — fönstret där planer faktiskt blir av. Gå live, se vilka som är ute nära dig, pinga, matcha och träffas.",
