    "faq_title": "Spørsmål, besvart.",
    "faq_q1": "Er 2NIGHT gratis?",
    "faq_a1": "Ja. Det er gratis å bli med i 2NIGHT og å møte folk. Et betalt medlemskap er på vei, og du ser nøyaktig hva det koster i appen før noe belastes.",
    "faq_q2": "Når lanseres det i min by?",
    "faq_a2": "Vi åpner byer i bølger. Bli med på ventelisten, så sender vi deg en melding i det øyeblikket 2NIGHT går live i nærheten av deg.",
    "faq_q3": "Hvordan skiller det seg fra andre datingapper?",
    "faq_a3": "Ingen endeløs sveiping mot «en gang i fremtiden». 2NIGHT viser hvem som er ute i nærheten av deg akkurat nå og hjelper deg å faktisk møtes — i kveld, ikke om tre uker.",
    "faq_q4": "Er det trygt?",
    "faq_a4": "Du bestemmer når du er live, hvor langt radiusen din rekker og hva du deler. Blokker og rapporter med ett trykk, og gå offline for å forsvinne umiddelbart. Vennligst les vår sikkerhetsveiledning før du møtes.",
    "faq_q5": "Hva får jeg for å bli med tidlig?",
    "faq_a5": "De første 20 medlemmene får 1 år med Platinum Black, gratis. De neste 200 får gratis Gold. De aller tidligste medlemmene eier natten.",
    "faq_q6": "Selger dere dataene mine?",
    "faq_a6": "Aldri. Vi selger ikke dine personopplysninger og vi driver ikke tredjeparts annonsesporing. Du har alltid kontrollen — se dine personvernvalg.",
    "sticky_note": "Gratis å bli med · 18+",
    "aria_menu": "Meny",
    "disclaimer_html": "<strong>2NIGHT er for voksne på 18 år og oppover.</strong> 2NIGHT lanseres snart; enkelte funksjoner og nedlasting fra App Store er kanskje ikke tilgjengelig i din region ennå. Appskjermer og bilder er kun ment som illustrasjon, og omtaler er fra betabrukere og er representative. 2NIGHT hjelper folk med å møtes, men gjennomfører <strong>ikke</strong> bakgrunns- eller identitetssjekker — vennligst les vår veiledning om <a href=\"/safety\">Sikkerhet</a> og møt ansvarlig. Ved å bruke 2NIGHT godtar du våre <a href=\"/terms\">Vilkår</a> og <a href=\"/privacy\">Personvernregler</a>. Apple, Apple-logoen og App Store er varemerker for Apple Inc.; 2NIGHT er ikke tilknyttet, sponset eller godkjent av Apple Inc.",
    "swipe_c1_t": "Takterrasse, kl. 21",
