    "waitlist_done": "Du er på listen. Vi ses i kveld.",
    "about_kicker": "Om 2NIGHT",
    "about_title": "I kveld, ikke i morgen.",
    "about_lead": "2NIGHT er for øyeblikket da du kl. 19 bestemmer deg for at du faktisk vil gjøre noe — og vil ha ekte folk nær deg som føler det samme.",
    "about_story_pull": "De fleste kvelder dør i en gruppechat. «Vi burde finne på noe snart.» Snart kommer aldri.",
    "about_story_t": "Kvelden du faktisk drar ut",
    "about_story_p1": "2NIGHT ble bygd rundt én sta idé: de beste nettene planlegges ikke tre uker i forveien. De skjer fordi noen, et sted i nærheten, er ledig akkurat nå og klar til å dra. Vi laget appen som gjør den impulsen om til en ekte plan — raskt, i virkeligheten, i kveld.",
    "about_story_p2": "Sett statusen din på én linje. Se hvem som er ute nær deg. Ping, match, møtes. Ingen endeløs swiping mot «kanskje neste uke». Bare folkene som er ute i kveld, og den korteste mulige veien til å være i samme rom.",
    "about_world_t": "Over hele verden, ikke by for by",
    "about_world_p1": "2NIGHT rulles ikke ut én by om gangen. Det fungerer hvor som helst på jorden — med folk nær deg, hvor enn du tilfeldigvis er i kveld. Land i en ny by, og natten er allerede i gang.",
    "about_world_p2": "Du bestemmer hvor langt det rekker. Velg radiusen din — fra gata di til hele byen — og 2NIGHT viser deg hvem som er ute innenfor den.",
    "about_who1_t": "Reisende",
    "about_who1_b": "Ny by, ingen kontakter, én kveld som skal telle. Åpne 2NIGHT, og den lokale natten ligger allerede foran deg.",
    "about_who2_t": "Utflyttere",
    "about_who2_b": "Du bygger et liv et nytt sted. Møt folk som er ute i kveld der du nå kaller hjemme.",
    "about_who3_t": "Lokale",
    "about_who3_b": "Du kan byen — du vil bare ha selskap for i kveld. Sett statusen din og finn folkene dine, uten kalender.",
    "about_design_t": "Designet for natten",
    "about_design_p": "Varm champagne mot dyp antrasitt. Redaksjonell, stillferdig og litt eksklusiv — bygd for å føles som det beste rommet i byen, ikke enda en støyende feed. Hver skjerm er laget for folk som bestemmer seg sent og handler raskt.",
    "support_kicker": "Støtte",
    "support_title": "Hvordan kan vi hjelpe?",
    "support_lead": "Alt du trenger å vite om 2NIGHT — og et ekte menneske i andre enden når du trenger det.",
    "faq_q7": "Hvordan håndterer dere personvernet mitt?",
    "faq_a7": "Vi samler kun inn det som trengs for å hjelpe deg å møte folk i kveld, og vi selger aldri personopplysningene dine. Du velger hva som er synlig for andre og når du deler posisjonen din. Les alle detaljene i personvernerklæringen vår.",
    "faq_a7_link": "Personvernerklæring",
    "support_contact_t": "Trenger du fortsatt en hånd?",
    "support_contact_p": "Send oss en e-post, så svarer et ekte menneske. Vi leser hver melding.",
    "nav_safety": "Sikkerhet",
    "nav_contact": "Kontakt",
    "footer_safety": "Sikkerhet",
    "footer_contact": "Kontakt",
    "contact_kicker": "Kontakt oss",
    "screens_disclaimer": "Alle bilder er kun til illustrasjon.",
    "android_soon": "Android — kommer snart",
    "testimonials_kicker": "Fra natten",
    "testimonials_title": "Hva brukerne våre sa om oss",
    "testimonials_sub": "Tidlige betanetter, med deres egne ord.",
    "testimonials_note": "Sitater fra betabrukere. Navn og byer er representative.",
    "testimonial1_q": "Jeg landet i Lisboa uten noen planer. Klokka ni satt jeg på en takbar med tre personer jeg nettopp hadde matchet med. Det er hele appen på én kveld.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lisboa",
    "testimonial2_q": "Ikke mer ”vi burde finne på noe snart”. Jeg satte statusen min, så hvem som var ledige, og møtte faktisk noen samme kveld. Endelig.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Paris",
    "testimonial3_q": "Black Events er helt vilt. Det føles mindre som en app og mer som en invitasjon til byens beste rom.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "Ny by for jobb, kjente ingen. To uker inn har jeg en ekte krets — alt fordi jeg klokka sju bestemte meg for at jeg ikke ville bli hjemme.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlin",
    "testimonial5_q": "Den er rask, den er vakker, og den respekterer faktisk tiden din. Ping, match, møt — akkurat som lovet.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "London",
    "testimonial6_q": "Travel Mode er en juksekode. Jeg åpner 2NIGHT i det sekundet jeg lander, og den lokale natten venter allerede.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "New York",
    "safety_kicker": "Sikkerhet",
    "safety_title": "Møt folk på den smarte måten.",
    "safety_lead": "2NIGHT er laget for spontane netter i virkeligheten. Noen enkle vaner holder dem morsomme — og gir deg kontroll når du møter noen nye.",
    "safety_t1_t": "Møtes på et offentlig sted",
    "safety_t1_b": "Velg et travelt og godt opplyst sted til en første date — en bar, en kafé, et populært sted. Bli på et offentlig sted til du virkelig føler deg trygg, og ikke dra til et privat sted med noen du nettopp har møtt.",
    "safety_t2_t": "Fortell en venn om planene dine",
    "safety_t2_b": "La noen du stoler på få vite hvor du skal, hvem du skal møte, og når du forventer å være tilbake. Del live-posisjonen din med dem for kvelden, og sjekk inn etterpå.",
    "safety_t3_t": "Ordne din egen transport",
    "safety_t3_b": "Kom deg dit og hjem på dine egne premisser. Hold telefonen oppladet, vit hvordan du kommer deg hjem, og du står fritt til å dra når du vil — uten å måtte forklare deg.",
    "safety_t4_t": "Send aldri penger",
    "safety_t4_b": "Send aldri penger, gavekort eller krypto til noen du har møtt i appen, uansett historie. Forespørsler om kontanter, økonomisk hjelp eller investerings­”tips” er klassisk svindel — stopp og rapporter dem.",
    "safety_t5_t": "Stol på magefølelsen",
    "safety_t5_b": "Hvis noe føles galt, er det sannsynligvis det. Du skylder aldri noen tiden din. Avslutt chatten, forlat møtet eller ring en venn — det finnes ingen feil grunn til å gå.",
    "safety_t6_t": "Rapporter og blokker",
    "safety_t6_b": "Alle som gjør deg ukomfortabel, kan blokkeres og rapporteres med ett trykk. Teamet vårt gjennomgår rapporter — å flagge dårlig oppførsel gjør hele natten tryggere for alle.",
    "safety_t7_t": "Beskytt personopplysningene dine",
    "safety_t7_b": "Hold chatten inne i 2NIGHT til du stoler på noen. Ikke del hjemmeadressen, arbeidsplassen, økonomiske detaljer eller dokumenter, og vær varsom med bilder som avslører nøyaktig hvor du bor.",
    "safety_t8_t": "Du har kontrollen",
    "safety_t8_b": "Du bestemmer når du er live, hvor langt radiusen din rekker, og hva du deler. Vi gjør ikke bakgrunnssjekker, så din egen dømmekraft kommer alltid først.",
    "safety_help_t": "I en nødssituasjon, ring etter hjelp.",
    "safety_help_p": "Hvis du noen gang føler deg utrygg eller truet, kontakt de lokale nødetatene først. For å rapportere noen eller noe til oss, send teamet vårt en e-post — vi leser hver melding.",
    "cookie_text": "Vi bruker informasjonskapsler for å holde 2NIGHT i gang og for å forstå hvordan nettstedet brukes.",
    "cookie_accept": "Godta",
    "cookie_decline": "Bare nødvendige",
    "cookie_privacy_link": "Personvern og informasjonskapsler",
    "cookie_aria": "Samtykke til informasjonskapsler",
    "founders_title": "To venner, én sta idé",
    "founders_role": "Grunnlegger og partner · Sveits",
    "founders_p1": "Hugo og Jeric, to venner fra Sveits, traff stadig den samme veggen: byer fulle av folk, gruppechatter fulle av «vi burde finne på noe snart» og ingen som faktisk var ute i kveld.",
    "founders_p2": "Hugo, grunnleggeren, skriver koden. Jeric, partneren hans, driver prosjektet og former opplevelsen. Fra et sveitsisk kjøkkenbord til der du står i kveld — det er hele historien.",
