    "waitlist_done": "Du er på listen. Vi ses i aften.",
    "about_kicker": "Om 2NIGHT",
    "about_title": "I aften, ikke i morgen.",
    "about_lead": "2NIGHT er til det øjeblik, hvor du kl. 19 beslutter dig for, at du faktisk vil lave noget — og vil have rigtige mennesker i nærheden, der føler det samme.",
    "about_story_pull": "De fleste aftener dør i en gruppechat. »Vi burde ses snart.« Snart kommer aldrig.",
    "about_story_t": "Aftenen, hvor du faktisk går ud",
    "about_story_p1": "2NIGHT blev bygget omkring én stædig idé: de bedste nætter planlægges ikke tre uger i forvejen. De sker, fordi nogen, et sted i nærheden, er fri lige nu og klar til at tage afsted. Vi lavede appen, der gør den impuls til en rigtig plan — hurtigt, i virkeligheden, i aften.",
    "about_story_p2": "Sæt din status på én linje. Se, hvem der er ude i nærheden af dig. Ping, match, mødes. Ingen endeløs swipen mod »måske i næste uge«. Kun de folk, der er ude i aften, og den kortest mulige vej til at være i samme rum.",
    "about_world_t": "Hele verden over, ikke by for by",
    "about_world_p1": "2NIGHT rulles ikke ud én by ad gangen. Det virker hvor som helst på kloden — med folk i nærheden af dig, hvor end du tilfældigvis er i aften. Land i en ny by, og natten er allerede i gang.",
    "about_world_p2": "Du bestemmer, hvor langt det rækker. Vælg din radius — fra din gade til hele byen — og 2NIGHT viser dig, hvem der er ude inden for den.",
    "about_who1_t": "Rejsende",
    "about_who1_b": "Ny by, ingen kontakter, én aften, der skal tælle. Åbn 2NIGHT, og den lokale nat ligger allerede foran dig.",
    "about_who2_t": "Udlandsdanskere",
    "about_who2_b": "Du bygger et liv et nyt sted. Mød folk, der er ude i aften der, hvor du nu kalder hjemme.",
    "about_who3_t": "Lokale",
    "about_who3_b": "Du kender byen — du vil bare have selskab til i aften. Sæt din status og find dine folk, uden kalender.",
    "about_design_t": "Designet til natten",
    "about_design_p": "Varm champagne mod dyb antracit. Redaktionel, stilfærdig og en smule eksklusiv — bygget til at føles som det bedste rum i byen, ikke endnu et larmende feed. Hver skærm er lavet til folk, der beslutter sig sent og handler hurtigt.",
    "support_kicker": "Support",
    "support_title": "Hvordan kan vi hjælpe?",
    "support_lead": "Alt, hvad du har brug for at vide om 2NIGHT — og et rigtigt menneske i den anden ende, når du har brug for det.",
    "faq_q7": "Hvordan håndterer I mit privatliv?",
    "faq_a7": "Vi indsamler kun det, der er nødvendigt for at hjælpe dig med at møde folk i aften, og vi sælger aldrig dine personoplysninger. Du vælger, hvad der er synligt for andre, og hvornår du deler din placering. Læs alle detaljerne i vores privatlivspolitik.",
    "faq_a7_link": "Privatlivspolitik",
    "support_contact_t": "Mangler du stadig en hånd?",
    "support_contact_p": "Skriv til os, så vender et rigtigt menneske tilbage. Vi læser hver eneste besked.",
    "nav_safety": "Sikkerhed",
    "nav_contact": "Kontakt",
    "footer_safety": "Sikkerhed",
    "footer_contact": "Kontakt",
    "contact_kicker": "Kontakt os",
    "screens_disclaimer": "Alle billeder er kun til illustration.",
    "android_soon": "Android — snart tilgængelig",
    "testimonials_kicker": "Fra natten",
    "testimonials_title": "Hvad vores brugere sagde om os",
    "testimonials_sub": "Tidlige beta-aftener, med deres egne ord.",
    "testimonials_note": "Citater fra beta-brugere. Navne og byer er repræsentative.",
    "testimonial1_q": "Jeg landede i Lissabon uden nogen planer. Klokken ni sad jeg på en tagbar med tre personer, jeg lige havde matchet med. Det er hele appen på én aften.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lissabon",
    "testimonial2_q": "Ikke flere ”vi burde mødes snart”. Jeg satte min status, så hvem der var ledige, og mødte faktisk nogen samme aften. Endelig.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Paris",
    "testimonial3_q": "Black Events er helt vildt. Det føles mindre som en app og mere som en invitation til byens bedste rum.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "Ny by for arbejdet, kendte ingen. To uger inde har jeg en rigtig omgangskreds — alt sammen fordi jeg klokken syv besluttede, at jeg ikke ville blive hjemme.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlin",
    "testimonial5_q": "Den er hurtig, den er smuk, og den respekterer faktisk din tid. Ping, match, mød — præcis som lovet.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "London",
    "testimonial6_q": "Travel Mode er en snydekode. Jeg åbner 2NIGHT i det sekund, jeg lander, og den lokale nat venter allerede.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "New York",
    "safety_kicker": "Sikkerhed",
    "safety_title": "Mød folk på den smarte måde.",
    "safety_lead": "2NIGHT er bygget til spontane aftener i det virkelige liv. Et par enkle vaner holder dem sjove — og holder dig i kontrol, når du møder nogen nye.",
    "safety_t1_t": "Mødes på et offentligt sted",
    "safety_t1_b": "Vælg et travlt og godt oplyst sted til en første date — en bar, en café, et populært sted. Bliv på et offentligt sted, indtil du virkelig føler dig tryg, og tag ikke til et privat sted med nogen, du lige har mødt.",
    "safety_t2_t": "Fortæl en ven om dine planer",
    "safety_t2_b": "Lad nogen, du stoler på, vide, hvor du skal hen, hvem du skal møde, og hvornår du forventer at være tilbage. Del din live-placering med dem for aftenen, og meld tilbage bagefter.",
    "safety_t3_t": "Sørg selv for transport",
    "safety_t3_b": "Kom selv derhen og hjem på dine egne præmisser. Hold telefonen opladet, vid, hvordan du kommer hjem, og du er fri til at gå, når du vil — uden at skulle forklare dig.",
    "safety_t4_t": "Send aldrig penge",
    "safety_t4_b": "Send aldrig penge, gavekort eller krypto til nogen, du har mødt i appen, uanset historien. Anmodninger om kontanter, økonomisk hjælp eller investerings­”tips” er klassisk svindel — stop og anmeld dem.",
    "safety_t5_t": "Stol på din mavefornemmelse",
    "safety_t5_b": "Hvis noget føles forkert, er det sandsynligvis det. Du skylder aldrig nogen din tid. Afslut chatten, forlad mødet eller ring til en ven — der er ingen forkert grund til at gå.",
    "safety_t6_t": "Anmeld og bloker",
    "safety_t6_b": "Enhver, der gør dig utilpas, kan blokeres og anmeldes med et tryk. Vores team gennemgår anmeldelser — at flagge dårlig opførsel gør hele natten tryggere for alle.",
    "safety_t7_t": "Beskyt dine personlige oplysninger",
    "safety_t7_b": "Hold chatten inde i 2NIGHT, indtil du stoler på nogen. Del ikke din hjemmeadresse, arbejdsplads, økonomiske oplysninger eller dokumenter, og vær påpasselig med billeder, der afslører præcis, hvor du bor.",
    "safety_t8_t": "Du har kontrollen",
    "safety_t8_b": "Du bestemmer, hvornår du er live, hvor langt din radius rækker, og hvad du deler. Vi laver ikke baggrundstjek, så din egen dømmekraft kommer altid først.",
    "safety_help_t": "Ring efter hjælp i en nødsituation.",
    "safety_help_p": "Hvis du nogensinde føler dig utryg eller truet, så kontakt de lokale alarmtjenester først. For at anmelde nogen eller noget til os, send vores team en e-mail — vi læser hver besked.",
    "cookie_text": "Vi bruger cookies for at holde 2NIGHT kørende og for at forstå, hvordan siden bruges.",
    "cookie_accept": "Accepter",
    "cookie_decline": "Kun nødvendige",
    "cookie_privacy_link": "Privatliv og cookies",
    "cookie_aria": "Cookie-samtykke",
    "founders_title": "To venner, én stædig idé",
    "founders_role": "Grundlægger og partner · Schweiz",
    "founders_p1": "Hugo og Jeric, to venner fra Schweiz, ramte hele tiden den samme mur: byer fulde af mennesker, gruppechats fulde af »vi burde mødes snart« og ingen, der rent faktisk var ude i aften.",
    "founders_p2": "Hugo, grundlæggeren, skriver koden. Jeric, hans partner, driver projektet og former oplevelsen. Fra et schweizisk køkkenbord til der, hvor du står i aften — det er hele historien.",
