    "disc_p1": "De fleste datingapps aftaler en kaffe tre uger ude i fremtiden. 2NIGHT er bygget til timerne mellem nu og klokken 2 om natten — vinduet, hvor planer faktisk bliver til noget. Gå live, se hvem der er ude i nærheden, ping, match og mødes.",
