    "pc_lead": "Sinä hallitset tietojasi 2NIGHT-sovelluksessa. Näin teet yksityisyysvalintasi milloin tahansa.",
    "pc1_t": "Pääse käsiksi tietoihisi",
    "pc1_b": "Pyydä kopio sinusta tallentamistamme henkilötiedoista, niin lähetämme ne sinulle.",
    "pc2_t": "Poista tilisi ja tietosi",
    "pc2_b": "Poista tilisi milloin tahansa kohdasta Asetukset → Tili → Poista tili, tai lähetä meille sähköpostia. Poistamme tietosi mahdollista lakisääteistä säilytysvelvollisuutta lukuun ottamatta.",
    "pc3_t": "Kieltäydy markkinoinnista",
    "pc3_b": "Poista markkinointisähköpostit ja push-ilmoitukset käytöstä kohdassa Asetukset → Ilmoitukset, tai käytä minkä tahansa sähköpostin tilauksen peruutuslinkkiä.",
    "pc4_t": "Ei myyntiä eikä jakamista",
    "pc4_b": "Emme koskaan myy henkilötietojasi emmekä koskaan jaa niitä kontekstien väliseen käyttäytymispohjaiseen mainontaan – kieltäydyttävää ei ole.",
    "pc5_t": "Hallitse evästeitä",
    "pc5_b": "Muuta eväste- ja seuranta-asetuksiasi milloin tahansa evästebannerin tai selainasetustesi kautta.",
    "pc6_t": "Sijainti ja käyttöoikeudet",
    "pc6_b": "Hallitse sijainnin, kameran ja ilmoitusten käyttöoikeuksia laitteesi asetuksista, ja peruuta mikä tahansa niistä koska tahansa.",
    "pc_note": "Nämä valinnat ovat kaikkien saatavilla kaikkialla – mukaan lukien GDPR:n (EU/UK) ja CCPA/CPRA:n (California) myöntämät oikeudet. Emme koskaan veloita sinulta tai kohtele sinua eri tavalla niiden käyttämisestä.",
