    "faq_q4": "Είναι ασφαλές;",
    "faq_a4": "Εσύ αποφασίζεις πότε είσαι live, πόσο μακριά φτάνει η ακτίνα σου και τι μοιράζεσαι. Μπλόκαρε και ανέφερε με ένα άγγιγμα, και πήγαινε offline για να εξαφανιστείς ακαριαία. Παρακαλούμε διάβασε τις οδηγίες ασφαλείας μας πριν συναντηθείς.",
    "faq_q5": "Τι κερδίζω αν εγγραφώ νωρίς;",
    "faq_a5": "Τα πρώτα 20 μέλη παίρνουν 1 χρόνο Platinum Black, δωρεάν. Τα επόμενα 200 παίρνουν δωρεάν Gold. Τα πιο πρώιμα μέλη ορίζουν τη νύχτα.",
