    "aria_menu": "Μενού",
    "disclaimer_html": "<strong>Το 2NIGHT απευθύνεται σε ενήλικες 18 ετών και άνω.</strong> Το 2NIGHT κυκλοφορεί σύντομα· ορισμένες λειτουργίες και η λήψη από το App Store ενδέχεται να μην είναι ακόμη διαθέσιμες στην περιοχή σας. Οι οθόνες της εφαρμογής και οι φωτογραφίες είναι μόνο ενδεικτικές, και οι μαρτυρίες προέρχονται από χρήστες beta και είναι αντιπροσωπευτικές. Το 2NIGHT βοηθά τους ανθρώπους να γνωριστούν, αλλά <strong>δεν</strong> διενεργεί ελέγχους ιστορικού ή ταυτότητας — διαβάστε τις οδηγίες μας για την <a href=\"/safety\">Ασφάλεια</a> και συναντηθείτε υπεύθυνα. Χρησιμοποιώντας το 2NIGHT αποδέχεστε τους <a href=\"/terms\">Όρους</a> και την <a href=\"/privacy\">Πολιτική Απορρήτου</a> μας. Η Apple, το λογότυπο της Apple και το App Store είναι εμπορικά σήματα της Apple Inc.· το 2NIGHT δεν συνδέεται, δεν χορηγείται ούτε εγκρίνεται από την Apple Inc.",
