    "gal_membership_t": "Συνδρομή",
    "gal_membership_s": "Silver · Gold · Platinum",
    "gal_profile_t": "Προφίλ",
    "gal_profile_s": "Εσύ, όταν πέφτει η νύχτα",
    "tiers_note": "Οι τιμές είναι σε USD και ενδέχεται να διαφέρουν ανά περιοχή. Τα επί πληρωμή πλάνα χρεώνονται μέσω του App Store της Apple και ανανεώνονται αυτόματα έως την ακύρωση — διαχειρίσου ή ακύρωσε ανά πάσα στιγμή από τις ρυθμίσεις του App Store. Δες τους Όρους μας.",
    "auth_login": "Σύνδεση",
    "cg1_b": "Χρησιμοποίησε δικές σου φωτογραφίες και πραγματικά στοιχεία. Όχι ψεύτικα προφίλ, υπόδυση ταυτότητας ή catfishing.",
    "cg1_t": "Να είσαι αληθινός",
    "cg2_b": "Όχι παρενόχληση, μίσος, απειλές ή ανεπιθύμητο σαφές περιεχόμενο. Να φέρεσαι στους άλλους όπως θα ήθελες να σου φέρονται.",
    "cg2_t": "Να είσαι σεβαστικός",
    "cg3_b": "Το 2NIGHT είναι αυστηρά για ενήλικες. Όποιος είναι ανήλικος αφαιρείται αμέσως.",
    "cg3_t": "Μόνο 18 ετών και άνω",
    "cg4_b": "Όχι πωλήσεις, συνοδεία, άγρα, απάτες ή αιτήματα προς μέλη για χρήματα, δώρα ή crypto.",
    "cg4_t": "Όχι χρήματα, όχι δουλειές",
    "cg5_b": "Μην καταγράφεις ή μοιράζεσαι κανέναν χωρίς συναίνεση, όχι doxxing, όχι κοινοποίηση προσωπικών πληροφοριών.",
    "cg5_t": "Κράτα το συναινετικό",
    "cg6_b": "Μπλόκαρε και κατάγγειλε όποιον ξεπερνά τα όρια. Η ομάδα μας εξετάζει κάθε αναφορά — η επισήμανση κρατά τη νύχτα ασφαλή.",
    "cg6_t": "Κατάγγειλε ό,τι δεν πάει καλά",
    "cg_contact": "Βλέπεις κάτι σοβαρό; Στείλε μας email — διαβάζουμε κάθε μήνυμα.",
    "cg_kicker": "Κοινότητα",
    "cg_lead": "Το 2NIGHT λειτουργεί μόνο αν νιώθεις ασφάλεια και αυθεντικότητα. Αυτοί οι κανόνες κρατούν τη νύχτα καλή για όλους — παραβίασέ τους και βγαίνεις έξω.",
    "cg_title": "Κανόνες κοινότητας",
    "community_meta": "Κανόνες κοινότητας 2NIGHT — οι κανόνες που κρατούν τη νύχτα ασφαλή και αυθεντική.",
    "cta_join": "Μπες στη λίστα αναμονής",
    "cta_sub2": "Μπες πρώτος. Τα πιο πρώιμα μέλη ορίζουν τη νύχτα — δωρεάν.",
    "disc_f1_b": "Όρισε την κατάστασή σου και η πόλη βλέπει ότι είσαι ελεύθερος απόψε. Εσύ ελέγχεις ποιον, πόσο μακριά και για πόσο.",
    "disc_f1_t": "Βγες live με ένα άγγιγμα",
    "disc_f2_b": "Πραγματικοί άνθρωποι κοντά σου, ελεύθεροι τώρα, που θέλουν το ίδιο. Όχι ατελείωτο swiping προς κάποια μέρα.",
    "disc_f2_t": "Tonight Feed",
    "disc_f3_b": "Το αμοιβαίο ενδιαφέρον ανοίγει μια συνομιλία. Κάνε ένα πλάνο και συναντηθείτε — από κοντά, την ίδια νύχτα.",
    "disc_f3_t": "Ping, ταίριασμα, συνάντηση",
    "disc_f4_b": "Από τον δρόμο σου μέχρι όλη την πόλη. Η συνδρομή σου ορίζει πόσο μακριά μπορεί να φτάσει η νύχτα.",
    "disc_f4_t": "Η ακτίνα σου, η νύχτα σου",
    "disc_feat_t": "Φτιαγμένο για να σε βγάλει από την πόρτα",
    "disc_kicker": "Ανακάλυψε",
    "disc_lead": "Η εφαρμογή γνωριμιών για μία νύχτα, για όσους στις 7 το απόγευμα αποφασίζουν ότι θέλουν να γνωρίσουν κάποιον — απόψε, όχι αύριο.",
    "disc_p1": "Οι περισσότερες εφαρμογές γνωριμιών κανονίζουν έναν καφέ τρεις εβδομάδες μετά. Το 2NIGHT είναι φτιαγμένο για τις ώρες ανάμεσα στο τώρα και τις 2 τα ξημερώματα — το παράθυρο όπου τα σχέδια πραγματικά γίνονται. Βγες live, δες ποιος είναι έξω κοντά σου, κάνε ping, ταίριαξε και συναντήσου.",
    "disc_title": "Τι είναι το 2NIGHT;",
    "discover_meta": "Ανακάλυψε το 2NIGHT — τι είναι η εφαρμογή γνωριμιών για μία νύχτα και πώς λειτουργεί.",
    "hero_cta_how": "Δες πώς λειτουργεί",
    "nav_blog": "Blog",
    "nav_community": "Κοινότητα",
    "nav_discover": "Ανακάλυψε",
    "nav_join": "Μπες στη λίστα αναμονής",
    "sec1_b": "Εσύ αποφασίζεις πότε είσαι live, πόσο μακριά φτάνει η ακτίνα σου και τι μοιράζεσαι. Βγες offline και εξαφανίζεσαι.",
    "sec1_t": "Έχεις πάντα τον έλεγχο",
    "sec2_b": "Μόνο όσοι βρίσκονται εντός της ακτίνας και του κοινού που επιλέγεις μπορούν να σε δουν, και μόνο όσο είσαι live.",
    "sec2_t": "Ιδιωτικό από προεπιλογή",
    "sec3_b": "Κρυπτογραφημένο κατά τη μεταφορά, η πρόσβαση αυστηρά περιορισμένη και ποτέ δεν πωλείται. Διάβασε τις λεπτομέρειες στην Πολιτική Απορρήτου μας.",
    "sec3_t": "Τα δεδομένα σου, προστατευμένα",
    "sec4_b": "Όποιος σε κάνει να νιώθεις άβολα μπορεί να μπλοκαριστεί και να καταγγελθεί αμέσως. Η ομάδα μας εξετάζει κάθε αναφορά.",
    "sec4_t": "Μπλόκαρε & κατάγγειλε με ένα άγγιγμα",
    "sec_contact": "Ερωτήσεις για την ασφάλεια ή το απόρρητο; Στείλε email στο support@2night.co.",
    "sec_kicker": "Εμπιστοσύνη & Ασφάλεια",
    "sec_lead": "Το να γνωρίζεις νέους ανθρώπους πρέπει να είναι συναρπαστικό, όχι επικίνδυνο. Δες πώς το 2NIGHT προστατεύει εσένα και τα δεδομένα σου.",
    "sec_note": "Σημαντικό: το 2NIGHT δεν διενεργεί ελέγχους ιστορικού ή ταυτότητας. Συναντηθείτε σε δημόσιο χώρο, πες το σε έναν φίλο και εμπιστεύσου το ένστικτό σου — δες τις συμβουλές ασφάλειάς μας.",
    "sec_title": "Η ασφάλειά σου, εκ σχεδιασμού.",
    "security_meta": "Εμπιστοσύνη & Ασφάλεια στο 2NIGHT — πώς προστατεύουμε εσένα και τα δεδομένα σου.",
    "swipe_hint": "Σύρε δεξιά για να μπεις · αριστερά για να προσπεράσεις",
    "tiers_note2": "Το 2NIGHT κυκλοφορεί σύντομα. Μπες στη λίστα αναμονής — τα πρώτα 20 μέλη παίρνουν 1 χρόνο Platinum Black δωρεάν, και τα επόμενα 200 παίρνουν Gold δωρεάν.",
    "waitlist_button2": "Κράτα τη θέση μου",
    "waitlist_close": "Κλείσιμο",
