    "waitlist_kicker": "Πρώιμη πρόσβαση",
    "waitlist_perk": "Τα πρώτα 20 μέλη παίρνουν 1 χρόνο Platinum Black, δωρεάν. Τα επόμενα 200 παίρνουν μια δωρεάν συνδρομή Gold. Θα σου στείλουμε μήνυμα τη στιγμή που η εφαρμογή θα είναι έτοιμη.",
    "waitlist_perk_short": "Τα πρώτα 20 παίρνουν 1 χρόνο Platinum Black, δωρεάν. Τα επόμενα 200 παίρνουν Gold δωρεάν.",
