    "stat_founders_big": "İlk 20",
    "stat_founders_sub": "1 yıl Platinum Black’i ücretsiz kazanır",
    "stat_zero_big": "Sıfır",
    "stat_zero_sub": "reklam, izleyici veya satılan veri",
    "faq_kicker": "Bilmekte fayda var",
    "faq_title": "Sorular, yanıtlandı.",
    "faq_q1": "2NIGHT ücretsiz mi?",
    "faq_a1": "Evet. 2NIGHT’a katılmak ve insanlarla tanışmak ücretsiz. Ücretli bir üyelik yolda; ne kadar tuttuğunu, hiçbir ücret alınmadan önce uygulamada tam olarak göreceksin.",
    "faq_q2": "Şehrimde ne zaman kullanıma açılacak?",
    "faq_a2": "Şehirleri dalgalar halinde açıyoruz. Bekleme listesine katıl, 2NIGHT yakınında yayına girdiği an sana mesaj atalım.",
    "faq_q3": "Diğer flört uygulamalarından farkı ne?",
    "faq_a3": "“Bir gün” için sonsuz kaydırma yok. 2NIGHT şu anda yakınında dışarıda olanları gösterir ve gerçekten buluşmana yardım eder — üç hafta sonra değil, bu gece.",
    "faq_q4": "Güvenli mi?",
    "faq_a4": "Ne zaman canlı olacağına, yarıçapının ne kadar uzağa ulaşacağına ve neyi paylaşacağına sen karar verirsin. Tek dokunuşla engelle ve bildir, anında kaybolmak için çevrimdışı ol. Lütfen buluşmadan önce güvenlik rehberimizi oku.",
    "faq_q5": "Erken katıldığımda ne kazanırım?",
    "faq_a5": "İlk 20 üye 1 yıl Platinum Black’i ücretsiz alır. Sonraki 200 üye ücretsiz Gold alır. En erken üyeler geceye sahip olur.",
    "faq_q6": "Verilerimi satıyor musunuz?",
    "faq_a6": "Asla. Kişisel verilerini satmıyoruz ve üçüncü taraf reklam takibi yapmıyoruz. Kontrol her zaman sende — Gizlilik Tercihlerine göz at.",
    "sticky_note": "Katılım ücretsiz · 18+",
    "aria_menu": "Menü",
    "disclaimer_html": "<strong>2NIGHT, 18 yaş ve üzeri yetişkinler içindir.</strong> 2NIGHT çok yakında kullanıma sunulacak; bazı özellikler ve App Store indirmesi bölgenizde henüz mevcut olmayabilir. Uygulama ekranları ve fotoğraflar yalnızca örnek amaçlıdır ve görüşler beta kullanıcılardan alınmış olup temsil niteliğindedir. 2NIGHT, insanların tanışmasına yardımcı olur ancak geçmiş veya kimlik kontrolü <strong>yapmaz</strong> — lütfen <a href=\"/safety\">Güvenlik</a> rehberimizi okuyun ve sorumlu bir şekilde buluşun. 2NIGHT'i kullanarak <a href=\"/terms\">Koşullar</a> ve <a href=\"/privacy\">Gizlilik Politikası</a> belgelerimizi kabul etmiş olursunuz. Apple, Apple logosu ve App Store, Apple Inc.'in ticari markalarıdır; 2NIGHT, Apple Inc. ile bağlantılı değildir, onun tarafından desteklenmez veya onaylanmaz.",
    "swipe_c1_t": "Teras, 21.00",
    "swipe_c1_s": "Şimdi canlı · 1,2 km",
