    "pc_kicker": "Gizliliğiniz",
    "pc_title": "Gizlilik tercihleriniz",
    "pc_lead": "2NIGHT'ta verileriniz sizin kontrolünüzde. Gizlilik tercihlerinizi dilediğiniz zaman şöyle kullanabilirsiniz.",
    "pc1_t": "Verilerinize erişin",
    "pc1_b": "Hakkınızda tuttuğumuz kişisel verilerin bir kopyasını isteyin, biz de size gönderelim.",
    "pc2_t": "Hesabınızı ve verilerinizi silin",
    "pc2_b": "Hesabınızı dilediğiniz zaman Ayarlar → Hesap → Hesabı sil yolundan silin ya da bize e-posta gönderin. Yasal saklama yükümlülükleri saklı kalmak kaydıyla verilerinizi sileriz.",
    "pc3_t": "Pazarlamadan çıkın",
    "pc3_b": "Tanıtım e-postalarını ve anlık bildirimleri Ayarlar → Bildirimler yolundan kapatın ya da herhangi bir e-postadaki abonelikten çıkma bağlantısını kullanın.",
    "pc4_t": "Satış ve paylaşım yok",
    "pc4_b": "Kişisel verilerinizi asla satmayız ve bağlamlar arası davranışsal reklamcılık için asla paylaşmayız — vazgeçmeniz gereken bir şey yok.",
    "pc5_t": "Çerezleri yönetin",
    "pc5_b": "Çerez ve izleme tercihlerinizi dilediğiniz zaman çerez bildirimi ya da tarayıcı ayarlarınız üzerinden değiştirin.",
    "pc6_t": "Konum ve izinler",
    "pc6_b": "Konum, kamera ve bildirim erişimini cihaz ayarlarınızdan yönetin ve bunlardan herhangi birini istediğiniz zaman geri alın.",
    "pc_note": "Bu tercihler herkese, her yerde sunulur — GDPR (AB/Birleşik Krallık) ve CCPA/CPRA (California) tarafından tanınan haklar dâhil. Bunları kullandığınız için sizden asla ücret almaz ya da size farklı davranmayız.",
    "pc_contact": "Bir gizlilik hakkınızı kullanmak için privacy@2night.co adresine e-posta gönderin — 30 gün içinde yanıt veririz.",
    "footer_privacy_choices": "Gizlilik tercihleriniz",
