    "tiers_note": "Fiyatlar USD cinsindendir ve bölgeye göre değişebilir. Ücretli planlar Apple App Store üzerinden faturalandırılır ve iptal edilene kadar otomatik olarak yenilenir — App Store ayarlarından istediğin zaman yönet veya iptal et. Koşullarımıza göz at.",
