    "faq_kicker": "من الجيد معرفته",
    "faq_title": "الأسئلة، مُجابة.",
    "faq_q1": "هل 2NIGHT مجاني؟",
    "faq_a1": "نعم. الانضمام إلى 2NIGHT ومقابلة الناس مجانيان. هناك عضوية مدفوعة في الطريق، وسترى داخل التطبيق بالضبط كم تكلفتها قبل أن يُخصم أي مبلغ.",
    "faq_q2": "متى يُطلق في مدينتي؟",
    "faq_a2": "نفتتح المدن على دفعات. انضمّ إلى قائمة الانتظار وسنراسلك في اللحظة التي يصبح فيها 2NIGHT متاحًا بالقرب منك.",
    "faq_q3": "ما الذي يميّزه عن تطبيقات المواعدة الأخرى؟",
    "faq_a3": "لا مزيد من التمرير اللانهائي نحو «يومًا ما». يُظهر لك 2NIGHT من هم في الخارج بالقرب منك الآن ويساعدك على اللقاء فعلًا — الليلة، لا بعد ثلاثة أسابيع.",
    "faq_q4": "هل هو آمن؟",
    "faq_a4": "أنت من يقرّر متى تكون متاحًا، وإلى أي مدى يصل نطاقك، وما الذي تشاركه. احظر وأبلغ بنقرة واحدة، وانتقل إلى وضع عدم الاتصال لتختفي فورًا. يُرجى قراءة إرشادات السلامة لدينا قبل أن تلتقي.",
    "faq_q5": "ماذا أحصل عند الانضمام مبكرًا؟",
    "faq_a5": "يحصل أول 20 عضوًا على سنة من Platinum Black مجانًا. ويحصل الـ200 التالون على Gold مجانًا. الأعضاء الأوائل يملكون الليل.",
    "faq_q6": "هل تبيعون بياناتي؟",
