    "sticky_note": "الانضمام مجاني · 18+",
    "aria_menu": "القائمة",
    "disclaimer_html": "<strong>تطبيق 2NIGHT مخصص للبالغين من سن 18 عامًا فما فوق.</strong> سيُطلق 2NIGHT قريبًا؛ وقد لا تتوفر بعض الميزات وتنزيل App Store في منطقتك بعد. شاشات التطبيق والصور لأغراض التوضيح فقط، والشهادات من مستخدمي النسخة التجريبية وهي تمثيلية. يساعد 2NIGHT الأشخاص على الالتقاء لكنه <strong>لا</strong> يجري عمليات تحقق من الخلفية أو الهوية — يُرجى قراءة إرشادات <a href=\"/safety\">السلامة</a> والالتقاء بمسؤولية. باستخدامك 2NIGHT فإنك توافق على <a href=\"/terms\">الشروط</a> و<a href=\"/privacy\">سياسة الخصوصية</a> الخاصة بنا. تُعد Apple وشعار Apple وApp Store علامات تجارية لشركة Apple Inc.؛ و2NIGHT غير مرتبط بشركة Apple Inc. وغير مدعوم أو معتمد منها.",
