    "founders_role": "المؤسس والشريك · سويسرا",
    "founders_p1": "كان Hugo وJeric، صديقان من سويسرا، يصطدمان دائمًا بالجدار نفسه: مدن مليئة بالناس، ومحادثات جماعية مليئة بعبارة «لازم نخرج قريبًا»، ولا أحد في الخارج فعلًا الليلة.",
    "founders_p2": "Hugo، المؤسس، يكتب الكود. وJeric، شريكه، يدير المشروع ويصوغ التجربة. من طاولة مطبخ في سويسرا إلى حيث تقف الليلة — تلك هي القصة كاملة.",
    "founders_sign": "— Hugo وJeric · سويسرا",
