    "tiers_note": "الأسعار بالدولار الأمريكي (USD) وقد تختلف حسب المنطقة. تُحصَّل رسوم الخطط المدفوعة عبر Apple App Store وتتجدد تلقائيًا حتى الإلغاء — يمكنك الإدارة أو الإلغاء في أي وقت من إعدادات App Store. اطّلع على الشروط الخاصة بنا.",
    "auth_login": "تسجيل الدخول",
    "cg1_b": "استخدم صورك الحقيقية وبياناتك الفعلية. لا حسابات مزيفة ولا انتحال للهوية ولا خداع.",
    "cg1_t": "كن حقيقياً",
