    "disc_kicker": "اكتشف",
    "disc_lead": "تطبيق المواعدة لليلة واحدة لمن يقررون الساعة السابعة مساءً أنهم يريدون لقاء شخص ما — الليلة، لا غداً.",
    "disc_p1": "معظم تطبيقات المواعدة تحدد موعد قهوة بعد ثلاثة أسابيع. أما 2NIGHT فمصمم للساعات بين الآن والثانية صباحاً — النافذة التي تتحقق فيها الخطط فعلاً. ابدأ البث، شاهد من بالقرب منك، نبّه، تطابق والتقِ.",
