    "faq_q4": "האם זה בטוח?",
    "faq_a4": "אתה מחליט מתי אתה פעיל, עד כמה רחוק מגיע הרדיוס שלך ומה אתה משתף. חסום ודווח בנגיעה אחת, ועבור למצב לא מקוון כדי להיעלם מיד. אנא קרא את הנחיות הבטיחות שלנו לפני שאתם נפגשים.",
