    "sticky_note": "הצטרפות בחינם · 18+",
    "aria_menu": "תפריט",
    "disclaimer_html": "<strong>‏2NIGHT מיועד למבוגרים מגיל 18 ומעלה.</strong> ‏2NIGHT יושק בקרוב; ייתכן שחלק מהתכונות וההורדה מ‑App Store עדיין אינם זמינים באזורך. מסכי האפליקציה והתמונות נועדו להמחשה בלבד, וההמלצות הן ממשתמשי גרסת בטא והן מייצגות. ‏2NIGHT עוזר לאנשים להיפגש אך <strong>אינו</strong> מבצע בדיקות רקע או זהות — אנא קראו את הנחיות <a href=\"/safety\">הבטיחות</a> שלנו והיפגשו באחריות. בשימוש ב‑2NIGHT אתם מסכימים <a href=\"/terms\">לתנאים</a> ול<a href=\"/privacy\">מדיניות הפרטיות</a> שלנו. ‏Apple, הלוגו של Apple ו‑App Store הם סימנים מסחריים של Apple Inc.; ‏2NIGHT אינו מסונף ל‑Apple Inc., אינו ממומן על ידה ואינו מאושר על ידה.",
