    "about_kicker": "אודות 2NIGHT",
    "about_title": "הערב, לא מחר.",
    "about_lead": "‏2NIGHT היא בשביל הרגע שבו בשבע בערב אתם מחליטים שבא לכם באמת לעשות משהו — ורוצים אנשים אמיתיים לידכם שמרגישים בדיוק אותו דבר.",
    "about_story_pull": "רוב הלילות מתים בצ'אט קבוצתי. «אנחנו חייבים להיפגש בקרוב.» בקרוב אף פעם לא מגיע.",
    "about_story_t": "הערב שבו אתם באמת יוצאים",
    "about_story_p1": "‏2NIGHT נבנתה סביב רעיון עקשן אחד: הלילות הכי טובים לא מתוכננים שלושה שבועות מראש. הם קורים כי מישהו, אי שם בקרבת מקום, פנוי ממש עכשיו ומוכן לזוז. בנינו את האפליקציה שהופכת את הדחף הזה לתוכנית אמיתית — מהר, פנים אל פנים, הערב.",
    "about_story_p2": "הגדירו סטטוס בשורה אחת. ראו מי בחוץ לידכם. Ping, התאמה, נפגשים. בלי החלקות אינסופיות לעבר «אולי בשבוע הבא». רק האנשים שיוצאים הערב, והדרך הקצרה ביותר להיות באותו חדר.",
    "about_world_t": "בכל העולם, לא עיר-עיר",
    "about_world_p1": "‏2NIGHT לא נפתחת עיר אחת בכל פעם. היא עובדת בכל מקום בעולם — עם האנשים שלידכם, בכל מקום שבו אתם נמצאים הערב. נחתו בעיר חדשה והלילה כבר חי.",
    "about_world_p2": "אתם מחליטים עד כמה רחוק זה מגיע. בחרו את הרדיוס שלכם — מהרחוב שלכם ועד כל העיר — ו-2NIGHT מראה לכם מי בחוץ בתוכו.",
    "about_who1_t": "מטיילים",
    "about_who1_b": "עיר חדשה, אפס אנשי קשר, לילה אחד כדי שזה ייחשב. פתחו את 2NIGHT והלילה המקומי כבר מולכם.",
    "about_who2_t": "אקספטים",
    "about_who2_b": "אתם בונים חיים במקום חדש. הכירו אנשים שיוצאים הערב במקום שאתם קוראים לו עכשיו בית.",
    "about_who3_t": "מקומיים",
    "about_who3_b": "אתם מכירים את העיר — אתם פשוט רוצים חברה להערב. הגדירו סטטוס ומצאו את האנשים שלכם, בלי צורך ביומן.",
    "about_design_t": "מעוצבת ללילה",
    "about_design_p": "שמפניה חמה על פחם עמוק. עריכתית, שקטה וקצת אקסקלוסיבית — בנויה כדי להרגיש כמו החדר הכי טוב בעיר, לא עוד פיד רועש. כל מסך נעשה למי שמחליט מאוחר וזז מהר.",
    "support_kicker": "תמיכה",
    "support_title": "איך נוכל לעזור?",
    "support_lead": "כל מה שצריך לדעת על 2NIGHT — ובן אדם אמיתי בצד השני כשצריך אותו.",
    "faq_q7": "איך אתם מטפלים בפרטיות שלי?",
    "faq_a7": "אנחנו אוספים רק את מה שנחוץ כדי לעזור לכם להכיר אנשים הערב, ולעולם לא מוכרים את הנתונים האישיים שלכם. אתם בוחרים מה גלוי לאחרים ומתי אתם משתפים מיקום. קראו את כל הפרטים במדיניות הפרטיות שלנו.",
