    "testimonial1_q": "נחתתי בליסבון בלי שום תוכניות. עד תשע בערב כבר ישבתי בבר על הגג עם שלושה אנשים שזה עתה עשיתי איתם Match. זו כל האפליקציה בלילה אחד.",
