    "testimonial1_c": "ליסבון",
    "testimonial2_q": "נגמרו ה”בוא ניפגש מתישהו”. הגדרתי את הסטטוס שלי, ראיתי מי פנוי, ובאמת נפגשתי עם מישהו באותו ערב. סוף סוף.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "פריז",
    "testimonial3_q": "ה-Black Events הם לא יאומנו. זה מרגיש פחות כמו אפליקציה ויותר כמו הזמנה לחדר הכי טוב בעיר.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "דובאי",
    "testimonial4_q": "עיר חדשה בשביל העבודה, לא הכרתי אף אחד. אחרי שבועיים יש לי חבורה אמיתית — והכול בגלל שבשבע בערב החלטתי שאני לא רוצה להישאר בבית.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "ברלין",
    "testimonial5_q": "היא מהירה, היא יפה, והיא באמת מכבדת את הזמן שלך. Ping, Match, נפגשים — בדיוק כמו שהובטח.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "לונדון",
    "testimonial6_q": "Travel Mode זה ממש קוד רמאות. אני פותח את 2NIGHT ברגע שאני נוחת, והלילה המקומי כבר מחכה.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "ניו יורק",
    "safety_kicker": "בטיחות",
    "safety_title": "להכיר אנשים בדרך החכמה.",
    "safety_lead": "‏2NIGHT נבנתה ללילות ספונטניים ואמיתיים. כמה הרגלים פשוטים שומרים עליהם כיפיים — ושומרים אתכם בשליטה כשאתם פוגשים מישהו חדש.",
    "safety_t1_t": "להיפגש במקום ציבורי",
    "safety_t1_b": "לפגישה ראשונה, בחרו מקום הומה ומואר היטב — בר, בית קפה, מקום פופולרי. הישארו במקום ציבורי עד שתרגישו באמת בנוח, ואל תלכו למקום פרטי עם מישהו שרק הכרתם.",
    "safety_t2_t": "ספרו לחבר על התוכניות שלכם",
    "safety_t2_b": "תנו למישהו שאתם סומכים עליו לדעת לאן אתם הולכים, את מי אתם פוגשים, ומתי אתם צפויים לחזור. שתפו איתו את המיקום החי שלכם לאורך הערב, ועדכנו אותו אחר כך.",
    "safety_t3_t": "סדרו לעצמכם הסעה",
    "safety_t3_b": "הגיעו וחזרו בתנאים שלכם. שמרו על הטלפון טעון, דעו איך אתם חוזרים הביתה, ואתם חופשיים לעזוב מתי שתרצו — בלי שום הסבר.",
    "safety_t4_t": "לעולם אל תשלחו כסף",
    "safety_t4_b": "לעולם אל תשלחו כסף, כרטיסי מתנה או קריפטו למישהו שהכרתם באפליקציה, לא משנה מה הסיפור. בקשות למזומן, לעזרה כספית או ל”טיפים” על השקעות הן הונאות קלאסיות — עצרו ודווחו עליהן.",
    "safety_t5_t": "סמכו על האינטואיציה שלכם",
    "safety_t5_b": "אם משהו מרגיש לא בסדר, כנראה שזה אכן כך. אתם אף פעם לא חייבים לאף אחד את הזמן שלכם. סיימו את הצ׳אט, עזבו את הפגישה או התקשרו לחבר — אין סיבה לא נכונה ללכת.",
    "safety_t6_t": "דווחו וחסמו",
    "safety_t6_b": "כל מי שגורם לכם לאי-נוחות אפשר לחסום ולדווח עליו בלחיצה אחת. הצוות שלנו בודק דיווחים — סימון התנהגות לא תקינה הופך את כל הלילה לבטוח יותר לכולם.",
    "safety_t7_t": "הגנו על המידע האישי שלכם",
    "safety_t7_b": "שמרו על השיחות בתוך 2NIGHT עד שאתם סומכים על מישהו. אל תשתפו את כתובת הבית, מקום העבודה, פרטים פיננסיים או מסמכים, והיו זהירים עם תמונות שחושפות בדיוק איפה אתם גרים.",
    "safety_t8_t": "השליטה בידיים שלכם",
    "safety_t8_b": "אתם מחליטים מתי אתם פעילים, עד כמה הרדיוס שלכם מגיע, ומה אתם משתפים. אנחנו לא מבצעים בדיקות רקע, ולכן שיקול הדעת שלכם תמיד קודם.",
    "safety_help_t": "במקרה חירום, התקשרו לעזרה.",
    "safety_help_p": "אם אי פעם אתם מרגישים לא בטוחים או מאוימים, פנו קודם לשירותי החירום המקומיים. כדי לדווח לנו על מישהו או על משהו, שלחו מייל לצוות שלנו — אנחנו קוראים כל הודעה.",
    "cookie_text": "אנחנו משתמשים בעוגיות כדי ש-2NIGHT תמשיך לעבוד וכדי להבין כיצד נעשה שימוש באתר.",
    "cookie_accept": "אישור",
    "cookie_decline": "חיוניות בלבד",
