    "founders_p1": "Hugo ו-Jeric, שני חברים משווייץ, נתקלו שוב ושוב באותו קיר: ערים מלאות אנשים, קבוצות וואטסאפ מלאות ב„חייבים להיפגש בקרוב“ ואף אחד שלא באמת בחוץ הלילה.",
    "founders_p2": "Hugo, המייסד, כותב את הקוד. Jeric, השותף שלו, מנהל את הפרויקט ומעצב את החוויה. משולחן מטבח בשווייץ ועד למקום שבו אתה נמצא הלילה — זה כל הסיפור.",
