    "tiers_note": "המחירים בדולר אמריקאי (USD) ועשויים להשתנות לפי אזור. מסלולים בתשלום מחויבים דרך ה-App Store של Apple ומתחדשים אוטומטית עד לביטול — נהלו או בטלו בכל עת בהגדרות ה-App Store. עיינו בתנאים שלנו.",
    "auth_login": "התחברות",
    "cg1_b": "השתמשו בתמונות שלכם ובפרטים אמיתיים. בלי פרופילים מזויפים, התחזות או הולכת שולל.",
