    "faq_q1": "2NIGHTは無料ですか？",
    "faq_a1": "はい。2NIGHTへの参加も、人との出会いも無料です。有料メンバーシップは準備中で、いくらかかるのかは請求が発生する前にアプリでご確認いただけます。",
    "faq_q2": "私の街ではいつ始まりますか？",
    "faq_a2": "都市は段階的に順次オープンしていきます。ウェイトリストに登録すれば、2NIGHTがあなたの近くで利用可能になった瞬間にお知らせします。",
    "faq_q3": "他のデート アプリと何が違うのですか？",
    "faq_a3": "「いつか」に向けた終わりのないスワイプはもうありません。2NIGHTは今この瞬間にあなたの近くで出かけている人を表示し、本当に出会えるようサポートします — 3週間後ではなく、今夜。",
    "faq_q4": "安全ですか？",
    "faq_a4": "いつオンラインになるか、半径をどこまで広げるか、何を共有するかはあなたが決めます。ブロックと報告はワンタップ、オフラインにすれば瞬時に姿を消せます。お会いになる前に、必ず安全ガイダンスをお読みください。",
    "faq_q5": "早期参加するとどんな特典がありますか？",
    "faq_a5": "最初の20名のメンバーはPlatinum Blackを1年間無料で獲得します。次の200名は無料でGoldを獲得します。最も早く参加したメンバーが夜を制します。",
    "faq_q6": "私のデータを販売しますか？",
    "faq_a6": "決してしません。あなたの個人データを販売することはなく、第三者の広告トラッキングも行いません。常にあなたがコントロールできます — プライバシー設定をご覧ください。",
