    "aria_menu": "メニュー",
    "disclaimer_html": "<strong>2NIGHTは18歳以上の成人向けです。</strong> 2NIGHTは近日公開予定です。一部の機能やApp Storeでのダウンロードは、お住まいの地域ではまだご利用いただけない場合があります。アプリの画面や写真はイメージであり、お客様の声はベータ版ユーザーによるもので代表的な一例です。2NIGHTは出会いをサポートしますが、経歴や身元の確認は<strong>行いません</strong>。<a href=\"/safety\">安全</a>に関するガイダンスをお読みいただき、責任を持ってお会いください。2NIGHTをご利用いただくことで、<a href=\"/terms\">利用規約</a>および<a href=\"/privacy\">プライバシーポリシー</a>に同意したものとみなされます。Apple、Appleのロゴ、App StoreはApple Inc.の商標です。2NIGHTはApple Inc.と提携、後援、または推奨される関係にはありません。",
