    "founders_p1": "スイス出身の友人同士、HugoとJericはいつも同じ壁にぶつかっていた。人であふれる街、「近いうちに集まろう」で埋まったグループチャット、それなのに今夜実際に出かけている人は誰もいない。",
    "founders_p2": "創業者のHugoがコードを書く。共同経営者のJericがプロジェクトを動かし、体験をかたちづくる。スイスの台所のテーブルから、今夜あなたが立っているその場所まで——それがすべての物語だ。",
