    "disc_kicker": "見つける",
    "disc_lead": "午後7時に「今夜誰かに会いたい」と決める人のための、一夜のデーティングアプリ—明日ではなく、今夜。",
    "disc_p1": "ほとんどのデーティングアプリは3週間先のコーヒーを予定します。2NIGHTは今から午前2時までの数時間のために作られています—計画が実際に動き出す時間帯。ライブになって、近くにいる人を見て、ピンを送り、マッチして、会う。",
