    "faq_q5": "早期加入能获得什么？",
    "faq_a5": "前20名会员免费获赠一年Platinum Black。接下来的200名免费获赠Gold。最早加入的人，主宰这座城市的夜晚。",
    "faq_q6": "你们会出售我的数据吗？",
