    "about_kicker": "关于 2NIGHT",
    "about_title": "就在今晚，不是明天。",
    "about_lead": "2NIGHT 属于晚上七点那一刻——你真的决定要去做点什么，也想要身边有同样心情的真实的人。",
    "about_story_pull": "大多数夜晚都死在群聊里。“改天一起出来玩吧。”而改天从未到来。",
    "about_story_t": "你真的会出门的那一晚",
    "about_story_p1": "2NIGHT 源于一个固执的念头：最棒的夜晚不是提前三周计划出来的。它们之所以发生，是因为附近某处某个人此刻有空、随时愿意行动。我们做了这款应用，把那股冲动变成真实的计划——快速、当面、就在今晚。",
    "about_story_p2": "用一句话设置你的状态。看看身边谁出来了。Ping、匹配、见面。不必无休止地滑向“也许下周”。只有今晚出来的人，以及走进同一个房间的最短路径。",
    "about_world_t": "全球通用，不局限于某座城市",
    "about_world_p1": "2NIGHT 不是一座城市一座城市地慢慢开放。它在地球上任何地方都能用——和此刻身边的人，无论今晚你恰好在哪里。落地一座新城市，夜晚已然鲜活。",
    "about_world_p2": "延伸多远，由你决定。选择你的范围——从你的街区到整座城市——2NIGHT 就会告诉你范围内谁出来了。",
    "about_who1_t": "旅行者",
    "about_who1_b": "新城市，没有人脉，只有一晚要尽兴。打开 2NIGHT，本地的夜晚已在你眼前。",
    "about_who2_t": "外派与移居者",
    "about_who2_b": "在新的地方建立生活。在你如今称之为家的地方，遇见今晚出来的人。",
    "about_who3_t": "本地人",
    "about_who3_b": "你了解这座城市——只是想找个今晚作伴的人。设置好状态，找到你的同道，不必看日历。",
    "about_design_t": "为夜晚而设计",
    "about_design_p": "深炭灰之上，温润香槟色。杂志质感、安静，又带一点专属感——做成全城最好的那个房间，而不是又一个喧闹的信息流。每一个界面，都为那些决定得晚、行动得快的人而生。",
    "support_kicker": "支持",
    "support_title": "我们能帮你什么？",
    "support_lead": "关于 2NIGHT 你需要知道的一切——在你需要时，另一端有真人回应。",
    "faq_q7": "你们如何处理我的隐私？",
    "faq_a7": "我们只收集帮助你今晚结识他人所必需的信息，且绝不出售你的个人数据。你可以选择对他人展示什么、何时分享位置。完整细节请阅读我们的隐私政策。",
    "faq_a7_link": "隐私政策",
    "support_contact_t": "还需要帮忙吗？",
    "support_contact_p": "给我们发邮件，会有真人回复你。我们会读每一条消息。",
    "nav_safety": "安全",
