    "footer_safety": "安全",
    "footer_contact": "联系我们",
    "contact_kicker": "联系我们",
    "screens_disclaimer": "所有照片仅供示意。",
    "android_soon": "Android — 即将上线",
    "testimonials_kicker": "来自夜晚",
    "testimonials_title": "用户对我们的评价",
    "testimonials_sub": "测试版最初的那些夜晚，由他们亲口讲述。",
    "testimonials_note": "引用自测试版用户。姓名和城市仅为示例。",
    "testimonial1_q": "我落地里斯本时一点计划都没有。到了晚上九点，我已经和三个刚 Match 的人在天台酒吧了。一整个晚上，就把这款 app 讲透了。",
    "testimonial1_n": "Marco",
    "testimonial1_c": "里斯本",
    "testimonial2_q": "再也没有那种「改天一起约吧」了。我设好状态，看到谁有空，当晚就真的见到了人。终于。",
    "testimonial2_n": "Léa",
    "testimonial2_c": "巴黎",
    "testimonial3_q": "Black Events 简直不真实。它不像一款 app，更像是进入这座城市最好房间的邀请函。",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "迪拜",
    "testimonial4_q": "因为工作来到新城市，一个人都不认识。两周后我就有了真正的圈子——全都源于晚上七点决定不想待在家里。",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "柏林",
    "testimonial5_q": "它很快，很美，而且真的尊重你的时间。Ping、Match、见面——和承诺的分毫不差。",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "伦敦",
    "testimonial6_q": "Travel Mode 简直就是作弊码。我一落地就打开 2NIGHT，当地的夜晚已经在等我了。",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "纽约",
    "safety_kicker": "安全",
    "safety_title": "用聪明的方式认识新朋友。",
    "safety_lead": "2NIGHT 为即兴、真实的夜晚而生。几个简单的习惯能让它们更尽兴——也能让你在认识新朋友时始终掌控全局。",
    "safety_t1_t": "在公共场所见面",
    "safety_t1_b": "第一次见面，选一个人多、灯光明亮的地方——酒吧、咖啡馆或热门去处。在你真正感到自在之前，请一直待在公共场所，不要和刚认识的人单独去私密场所。",
    "safety_t2_t": "把行程告诉朋友",
    "safety_t2_b": "让你信任的人知道你要去哪里、见谁、预计什么时候回来。把当晚的实时位置分享给他们，事后也记得报个平安。",
    "safety_t3_t": "自行安排往返交通",
    "safety_t3_b": "按自己的方式去和回。保持手机有电，想好怎么回家，你随时可以离开——无需任何解释。",
    "safety_t4_t": "绝不转账",
    "safety_t4_b": "无论对方编出什么故事，都绝不要给在 app 上认识的人转钱、礼品卡或加密货币。索要现金、金钱帮助或投资「内幕」都是典型的骗局——立刻停下并举报。",
    "safety_t5_t": "相信你的直觉",
    "safety_t5_b": "如果哪里觉得不对劲，那多半就是不对劲。你从不欠任何人时间。结束聊天、离开见面，或给朋友打个电话——离开从来不需要理由。",
    "safety_t6_t": "举报和拉黑",
    "safety_t6_b": "任何让你感到不适的人，都可以一键拉黑并举报。我们的团队会审核举报——标记不良行为能让整个夜晚对所有人都更安全。",
    "safety_t7_t": "保护你的个人信息",
