    "faq_a3": "不再為了“某一天”無休止地滑動。2NIGHT為你呈現此刻就在你附近外出的人，幫你真正見上面 — 就在今晚，而非三週後。",
    "faq_q4": "它安全嗎？",
    "faq_a4": "何時上線、範圍半徑有多大、分享什麼，全由你決定。一鍵封鎖與檢舉，切換離線即可瞬間隱身。見面前，請先閱讀我們的安全指南。",
    "faq_q5": "早期加入能獲得什麼？",
    "faq_a5": "前20名會員免費獲贈一年Platinum Black。接下來的200名免費獲贈Gold。最早加入的人，主宰這座城市的夜晚。",
