    "about_story_pull": "大多數夜晚都死在群組聊天裡。「改天一起出來玩吧。」而改天從未到來。",
    "about_story_t": "你真的會出門的那一晚",
    "about_story_p1": "2NIGHT 源於一個固執的念頭：最棒的夜晚不是提前三週計畫出來的。它們之所以發生，是因為附近某處某個人此刻有空、隨時願意行動。我們做了這款應用程式，把那股衝動變成真實的計畫——快速、當面、就在今晚。",
    "about_story_p2": "用一句話設定你的狀態。看看身邊誰出來了。Ping、配對、見面。不必無休止地滑向「也許下週」。只有今晚出來的人，以及走進同一個房間的最短路徑。",
    "about_world_t": "全球通用，不侷限於某座城市",
    "about_world_p1": "2NIGHT 不是一座城市一座城市地慢慢開放。它在地球上任何地方都能用——和此刻身邊的人，無論今晚你恰好在哪裡。落地一座新城市，夜晚已然鮮活。",
    "about_world_p2": "延伸多遠，由你決定。選擇你的範圍——從你的街區到整座城市——2NIGHT 就會告訴你範圍內誰出來了。",
    "about_who1_t": "旅行者",
    "about_who1_b": "新城市，沒有人脈，只有一晚要盡興。打開 2NIGHT，當地的夜晚已在你眼前。",
    "about_who2_t": "外派與移居者",
    "about_who2_b": "在新的地方建立生活。在你如今稱之為家的地方，遇見今晚出來的人。",
    "about_who3_t": "在地人",
    "about_who3_b": "你了解這座城市——只是想找個今晚作伴的人。設定好狀態，找到你的同道，不必看行事曆。",
    "about_design_t": "為夜晚而設計",
    "about_design_p": "深炭灰之上，溫潤香檳色。雜誌質感、安靜，又帶一點專屬感——做成全城最好的那個房間，而不是又一個喧鬧的資訊流。每一個畫面，都為那些決定得晚、行動得快的人而生。",
    "support_kicker": "支援",
    "support_title": "我們能幫你什麼？",
    "support_lead": "關於 2NIGHT 你需要知道的一切——在你需要時，另一端有真人回應。",
    "faq_q7": "你們如何處理我的隱私？",
    "faq_a7": "我們只收集幫助你今晚結識他人所必需的資訊，且絕不出售你的個人資料。你可以選擇對他人展示什麼、何時分享位置。完整細節請閱讀我們的隱私權政策。",
    "faq_a7_link": "隱私權政策",
    "support_contact_t": "還需要幫忙嗎？",
    "support_contact_p": "給我們寄電子郵件，會有真人回覆你。我們會讀每一則訊息。",
    "nav_safety": "安全",
    "nav_contact": "聯絡我們",
    "footer_safety": "安全",
    "footer_contact": "聯絡我們",
    "contact_kicker": "聯絡我們",
    "screens_disclaimer": "所有照片僅供示意。",
    "android_soon": "Android — 即將上線",
    "testimonials_kicker": "來自夜晚",
    "testimonials_title": "使用者對我們的評價",
    "testimonials_sub": "測試版最初的那些夜晚，由他們親口講述。",
    "testimonials_note": "引用自測試版使用者。姓名和城市僅為示例。",
    "testimonial1_q": "我抵達里斯本時一點計畫都沒有。到了晚上九點，我已經和三個剛 Match 的人在天台酒吧了。一整個晚上，就把這款 app 講透了。",
    "testimonial1_n": "Marco",
    "testimonial1_c": "里斯本",
    "testimonial2_q": "再也沒有那種「改天一起約吧」了。我設好狀態，看到誰有空，當晚就真的見到了人。終於。",
    "testimonial2_n": "Léa",
    "testimonial2_c": "巴黎",
    "testimonial3_q": "Black Events 簡直不真實。它不像一款 app，更像是進入這座城市最好房間的邀請函。",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "杜拜",
    "testimonial4_q": "因為工作來到新城市，一個人都不認識。兩週後我就有了真正的圈子——全都源於晚上七點決定不想待在家裡。",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "柏林",
    "testimonial5_q": "它很快，很美，而且真的尊重你的時間。Ping、Match、見面——和承諾的分毫不差。",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "倫敦",
    "testimonial6_q": "Travel Mode 簡直就是作弊碼。我一抵達就打開 2NIGHT，當地的夜晚已經在等我了。",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "紐約",
    "safety_kicker": "安全",
    "safety_title": "用聰明的方式認識新朋友。",
    "safety_lead": "2NIGHT 為即興、真實的夜晚而生。幾個簡單的習慣能讓它們更盡興——也能讓你在認識新朋友時始終掌控全局。",
    "safety_t1_t": "在公共場所見面",
    "safety_t1_b": "第一次見面，選一個人多、燈光明亮的地方——酒吧、咖啡館或熱門去處。在你真正感到自在之前，請一直待在公共場所，不要和剛認識的人單獨去私密場所。",
    "safety_t2_t": "把行程告訴朋友",
    "safety_t2_b": "讓你信任的人知道你要去哪裡、見誰、預計什麼時候回來。把當晚的即時位置分享給他們，事後也記得報個平安。",
    "safety_t3_t": "自行安排往返交通",
    "safety_t3_b": "按自己的方式去和回。保持手機有電，想好怎麼回家，你隨時可以離開——無需任何解釋。",
    "safety_t4_t": "絕不轉帳",
    "safety_t4_b": "無論對方編出什麼故事，都絕不要給在 app 上認識的人轉錢、禮品卡或加密貨幣。索要現金、金錢幫助或投資「內幕」都是典型的騙局——立刻停下並檢舉。",
    "safety_t5_t": "相信你的直覺",
    "safety_t5_b": "如果哪裡覺得不對勁，那多半就是不對勁。你從不欠任何人時間。結束聊天、離開見面，或給朋友打個電話——離開從來不需要理由。",
    "safety_t6_t": "檢舉和封鎖",
    "safety_t6_b": "任何讓你感到不適的人，都可以一鍵封鎖並檢舉。我們的團隊會審核檢舉——標記不良行為能讓整個夜晚對所有人都更安全。",
    "safety_t7_t": "保護你的個人資訊",
    "safety_t7_b": "在真正信任對方之前，把聊天保留在 2NIGHT 內。不要透露你的住址、工作單位、財務資訊或證件，對會暴露你確切住處的照片也要多加留意。",
    "safety_t8_t": "一切由你掌控",
    "safety_t8_b": "由你決定什麼時候上線、半徑覆蓋多遠、分享什麼。我們不做背景調查，所以你自己的判斷永遠是第一位的。",
    "safety_help_t": "遇到緊急情況，請求助。",
    "safety_help_p": "如果你感到不安全或受到威脅，請先聯絡當地的緊急救援服務。要向我們檢舉某人或某事，請寄電子郵件給我們的團隊——我們會讀每一封郵件。",
    "cookie_text": "我們使用 Cookie 來維持 2NIGHT 的正常運作，並了解網站的使用情況。",
    "cookie_accept": "接受",
    "cookie_decline": "僅必要",
    "cookie_privacy_link": "隱私與 Cookie",
