    "founders_p1": "來自瑞士的兩個朋友 Hugo 和 Jeric 一直撞上同一堵牆：城市裡到處是人，群組裡滿是「我們改天聚聚吧」，卻沒人真的今晚出門。",
    "founders_p2": "創辦人 Hugo 負責寫程式碼。他的合夥人 Jeric 負責推進專案、打磨體驗。從瑞士的廚房餐桌，到你今晚所站的任何地方——這就是全部的故事。",
