    "pc_kicker": "회원님의 개인정보",
    "pc_title": "개인정보 선택권",
    "pc_lead": "2NIGHT에서는 회원님의 데이터를 회원님이 직접 관리합니다. 언제든지 개인정보 선택권을 행사하는 방법을 안내해 드립니다.",
    "pc1_t": "내 데이터 열람",
    "pc1_b": "저희가 보유한 회원님의 개인정보 사본을 요청하시면 보내 드립니다.",
    "pc2_t": "계정 및 데이터 삭제",
    "pc2_b": "설정 → 계정 → 계정 삭제 에서 언제든지 계정을 삭제하거나 저희에게 이메일을 보내실 수 있습니다. 법적 보존 의무가 있는 경우를 제외하고 회원님의 데이터를 삭제합니다.",
    "pc3_t": "마케팅 수신 거부",
    "pc3_b": "설정 → 알림 에서 프로모션 이메일과 푸시 알림을 끄거나, 이메일에 포함된 수신 거부 링크를 이용하세요.",
    "pc4_t": "판매 및 공유 금지",
    "pc4_b": "저희는 회원님의 개인정보를 절대 판매하지 않으며, 교차 맥락 행동 기반 광고를 위해 공유하지도 않습니다 — 별도로 거부하실 것이 없습니다.",
    "pc5_t": "쿠키 관리",
    "pc5_b": "쿠키 배너 또는 브라우저 설정을 통해 언제든지 쿠키 및 추적 환경설정을 변경하실 수 있습니다.",
    "pc6_t": "위치 및 권한",
    "pc6_b": "위치, 카메라, 알림 접근 권한을 기기 설정에서 관리하고 언제든지 철회하실 수 있습니다.",
    "pc_note": "이러한 선택권은 GDPR(EU/영국)과 CCPA/CPRA(California)가 부여하는 권리를 포함하여, 어디에 있는 누구에게나 제공됩니다. 이를 행사하셨다는 이유로 요금을 청구하거나 차별하는 일은 절대 없습니다.",
    "pc_contact": "개인정보 권리를 행사하시려면 privacy@2night.co 로 이메일을 보내 주세요 — 30일 이내에 답변해 드립니다.",
