    "founders_p1": "스위스 출신의 두 친구 Hugo와 Jeric은 늘 같은 벽에 부딪혔다. 사람으로 가득한 도시, “조만간 한번 보자”로 가득한 단톡방, 그런데 오늘 밤 정작 밖에 나와 있는 사람은 아무도 없다.",
