    "faq_q1": "2NIGHT ใช้ฟรีไหม？",
    "faq_a1": "ใช่ การเข้าร่วม 2NIGHT และการพบปะผู้คนนั้นฟรี สมาชิกแบบมีค่าใช้จ่ายกำลังจะมา และคุณจะเห็นชัดเจนในแอปว่ามีค่าใช้จ่ายเท่าไร ก่อนที่จะถูกเรียกเก็บใด ๆ",
    "faq_q2": "จะเปิดให้บริการในเมืองของฉันเมื่อไหร่？",
    "faq_a2": "เราเปิดเมืองเป็นรอบ ๆ ลงชื่อในรายชื่อรอ แล้วเราจะแจ้งคุณทันทีที่ 2NIGHT เปิดให้บริการใกล้คุณ",
    "faq_q3": "มันต่างจากแอปหาคู่อื่นอย่างไร？",
    "faq_a3": "ไม่มีการปัดไม่รู้จบเพื่อ “สักวันหนึ่ง” อีกต่อไป 2NIGHT แสดงให้เห็นว่าใครออกมาอยู่ใกล้คุณตอนนี้ และช่วยให้คุณได้พบกันจริง ๆ — คืนนี้เลย ไม่ใช่อีกสามสัปดาห์ข้างหน้า",
    "faq_q4": "ปลอดภัยไหม？",
    "faq_a4": "คุณเป็นคนตัดสินใจเองว่าจะออนไลน์เมื่อไหร่ จะขยายรัศมีไกลแค่ไหน และจะแชร์อะไร บล็อกและรายงานได้ในแตะเดียว และสลับเป็นออฟไลน์เพื่อหายตัวไปทันที โปรดอ่านคำแนะนำด้านความปลอดภัยของเราก่อนนัดพบ",
    "faq_q5": "สมัครเร็วได้อะไรบ้าง？",
