    "about_title": "คืนนี้ ไม่ใช่พรุ่งนี้",
    "about_lead": "2NIGHT มีไว้สำหรับวินาทีที่คุณตัดสินใจตอนหนึ่งทุ่มว่าอยากออกไปทำอะไรสักอย่างจริง ๆ — และอยากเจอคนจริง ๆ ใกล้ตัวที่รู้สึกแบบเดียวกัน",
    "about_story_pull": "ค่ำคืนส่วนใหญ่ตายในกลุ่มแชต “ไว้เจอกันเร็ว ๆ นี้นะ” แล้วเร็ว ๆ นี้ก็ไม่เคยมาถึง",
    "about_story_t": "ค่ำคืนที่คุณได้ออกไปจริง ๆ",
    "about_story_p1": "2NIGHT สร้างขึ้นจากความคิดดื้อ ๆ ข้อเดียว: ค่ำคืนที่ดีที่สุดไม่ได้วางแผนล่วงหน้าสามสัปดาห์ มันเกิดขึ้นเพราะมีใครสักคนที่ไหนสักแห่งใกล้ ๆ ว่างตอนนี้ และพร้อมจะออกไป เราจึงทำแอปที่เปลี่ยนแรงกระตุ้นนั้นให้เป็นแพลนจริง — เร็ว ตัวต่อตัว คืนนี้",
    "about_story_p2": "ตั้งสถานะด้วยบรรทัดเดียว ดูว่าใครออกมาใกล้คุณ Ping จับคู่ เจอกัน ไม่มีการปัดไปเรื่อย ๆ สู่ “ไว้สัปดาห์หน้าก็แล้วกัน” มีแค่คนที่ออกมาคืนนี้ กับเส้นทางที่สั้นที่สุดที่จะได้อยู่ในห้องเดียวกัน",
    "about_world_t": "ทั่วโลก ไม่จำกัดแค่บางเมือง",
    "about_world_p1": "2NIGHT ไม่ได้ทยอยเปิดทีละเมือง มันใช้ได้ทุกที่บนโลก — กับคนที่อยู่ใกล้คุณ ไม่ว่าคืนนี้คุณจะบังเอิญอยู่ที่ไหน ลงเครื่องในเมืองใหม่ แล้วค่ำคืนก็ไลฟ์อยู่แล้ว",
    "about_world_p2": "คุณตัดสินใจเองว่าจะไปไกลแค่ไหน เลือกรัศมีของคุณ — ตั้งแต่ถนนหน้าบ้านไปจนทั่วทั้งเมือง — แล้ว 2NIGHT จะแสดงว่าใครออกมาอยู่ในนั้น",
    "about_who1_t": "นักเดินทาง",
    "about_who1_b": "เมืองใหม่ ไม่มีคอนแทกต์ มีคืนเดียวที่ต้องให้คุ้ม เปิด 2NIGHT แล้วค่ำคืนของท้องถิ่นก็อยู่ตรงหน้าคุณแล้ว",
    "about_who2_t": "ชาวต่างถิ่น",
    "about_who2_b": "กำลังสร้างชีวิตในที่ใหม่ เจอคนที่ออกมาคืนนี้ในที่ที่ตอนนี้คุณเรียกว่าบ้าน",
    "about_who3_t": "คนท้องถิ่น",
    "about_who3_b": "คุณรู้จักเมืองดีอยู่แล้ว — แค่อยากมีเพื่อนสำหรับคืนนี้ ตั้งสถานะแล้วหาคนของคุณ ไม่ต้องเปิดปฏิทินเลย",
    "about_design_t": "ออกแบบมาเพื่อค่ำคืน",
    "about_design_p": "แชมเปญอุ่นละมุนบนสีถ่านเข้ม สไตล์นิตยสาร เงียบ และเอ็กซ์คลูซีฟนิด ๆ — สร้างมาให้รู้สึกเหมือนห้องที่ดีที่สุดในเมือง ไม่ใช่ฟีดเสียงดังอีกอัน ทุกหน้าจอทำมาเพื่อคนที่ตัดสินใจช้าแต่ลงมือเร็ว",
