    "safety_kicker": "ความปลอดภัย",
    "safety_title": "เจอผู้คนอย่างชาญฉลาด",
    "safety_lead": "2NIGHT สร้างขึ้นเพื่อค่ำคืนจริงที่เกิดขึ้นแบบสด ๆ นิสัยง่าย ๆ ไม่กี่อย่างช่วยให้สนุก — และช่วยให้คุณคุมเกมได้เมื่อเจอคนใหม่",
    "safety_t1_t": "นัดเจอในที่สาธารณะ",
    "safety_t1_b": "สำหรับการเจอครั้งแรก เลือกที่ที่คนพลุกพล่านและมีแสงสว่างพอ — บาร์ คาเฟ่ หรือที่ที่คนนิยม อยู่ในที่สาธารณะจนกว่าคุณจะรู้สึกสบายใจจริง ๆ และอย่าไปยังสถานที่ส่วนตัวกับคนที่คุณเพิ่งรู้จัก",
    "safety_t2_t": "บอกแผนให้เพื่อนรู้",
    "safety_t2_b": "บอกคนที่คุณไว้ใจว่าจะไปไหน เจอใคร และคาดว่าจะกลับเมื่อไหร่ แชร์ตำแหน่งสด ๆ ให้เขาในคืนนั้น แล้วเช็กอินหลังกลับด้วย",
    "safety_t3_t": "จัดการเดินทางเอง",
    "safety_t3_b": "ไปและกลับด้วยวิธีของคุณเอง ชาร์จโทรศัพท์ให้พร้อม รู้ว่าจะกลับบ้านยังไง และคุณมีอิสระที่จะกลับเมื่อไหร่ก็ได้ — ไม่ต้องอธิบายอะไร",
    "safety_t4_t": "อย่าโอนเงินเด็ดขาด",
    "safety_t4_b": "อย่าโอนเงิน บัตรของขวัญ หรือคริปโตให้คนที่คุณเจอในแอปเด็ดขาด ไม่ว่าจะเล่าเรื่องอะไรมา การขอเงินสด ความช่วยเหลือทางการเงิน หรือ “ทิป” การลงทุน คือกลโกงคลาสสิก — หยุดแล้วรายงานเลย",
    "safety_t5_t": "เชื่อสัญชาตญาณของคุณ",
    "safety_t5_b": "ถ้ารู้สึกว่ามีอะไรไม่ถูกต้อง มันก็มักจะเป็นอย่างนั้น คุณไม่เคยติดค้างเวลาให้ใคร จบแชต ออกจากการนัด หรือโทรหาเพื่อน — ไม่มีเหตุผลไหนผิดที่จะเดินจากไป",
    "safety_t6_t": "รายงานและบล็อก",
    "safety_t6_b": "ใครก็ตามที่ทำให้คุณอึดอัดสามารถถูกบล็อกและรายงานได้ในแตะเดียว ทีมงานของเราจะตรวจสอบรายงาน — การแจ้งพฤติกรรมไม่ดีช่วยให้ทั้งค่ำคืนปลอดภัยขึ้นสำหรับทุกคน",
    "safety_t7_t": "ปกป้องข้อมูลส่วนตัวของคุณ",
    "safety_t7_b": "เก็บการแชตไว้ใน 2NIGHT จนกว่าคุณจะไว้ใจอีกฝ่าย อย่าบอกที่อยู่บ้าน ที่ทำงาน ข้อมูลการเงิน หรือเอกสารของคุณ และระวังรูปภาพที่เผยให้เห็นว่าคุณอยู่ที่ไหนแน่ชัด",
    "safety_t8_t": "คุณคือคนคุมเกม",
    "safety_t8_b": "คุณเป็นคนตัดสินใจว่าจะออนไลน์เมื่อไหร่ รัศมีไกลแค่ไหน และจะแชร์อะไร เราไม่ได้ตรวจสอบประวัติ ดังนั้นวิจารณญาณของคุณเองมาก่อนเสมอ",
    "safety_help_t": "ในกรณีฉุกเฉิน ขอความช่วยเหลือ",
