    "tiers_note": "Giá tính bằng USD và có thể thay đổi theo khu vực. Các gói trả phí được tính phí qua Apple App Store và tự động gia hạn cho đến khi hủy — quản lý hoặc hủy bất cứ lúc nào trong cài đặt App Store của bạn. Xem Điều khoản của chúng tôi.",
    "auth_login": "Đăng nhập",
    "cg1_b": "Dùng ảnh thật và thông tin thật của bạn. Không hồ sơ giả, mạo danh hay lừa tình.",
    "cg1_t": "Hãy là chính mình",
    "cg2_b": "Không quấy rối, thù ghét, đe dọa hay gửi nội dung khiêu dâm khi chưa được yêu cầu. Đối xử với người khác theo cách bạn muốn được đối xử.",
    "cg2_t": "Hãy tôn trọng",
    "cg3_b": "2NIGHT chỉ dành cho người trưởng thành. Bất kỳ ai chưa đủ tuổi sẽ bị loại ngay lập tức.",
    "cg3_t": "Chỉ từ 18 tuổi trở lên",
