    "cg6_t": "Báo cáo điều sai trái",
    "cg_contact": "Thấy điều gì nghiêm trọng? Email cho chúng tôi — chúng tôi đọc mọi tin nhắn.",
    "cg_kicker": "Cộng đồng",
    "cg_lead": "2NIGHT chỉ hiệu quả khi nó an toàn và chân thật. Những quy tắc này giữ cho đêm tốt đẹp cho mọi người — vi phạm là bạn bị loại.",
