    "cta_sub2": "Vào trước tiên. Những thành viên sớm nhất làm chủ màn đêm — miễn phí.",
    "disc_f1_b": "Đặt trạng thái và cả thành phố biết bạn rảnh tối nay. Bạn kiểm soát ai, xa bao nhiêu và trong bao lâu.",
    "disc_f1_t": "Lên sóng chỉ một chạm",
    "disc_f2_b": "Người thật gần bạn, rảnh ngay bây giờ, muốn điều giống bạn. Không vuốt mãi để chờ một ngày nào đó.",
    "disc_f2_t": "Tonight Feed",
    "disc_f3_b": "Sự quan tâm chung mở ra cuộc trò chuyện. Lên kế hoạch và gặp nhau — trực tiếp, ngay trong đêm.",
    "disc_f3_t": "Ping, ghép đôi, gặp gỡ",
    "disc_f4_b": "Từ con phố của bạn đến cả thành phố. Gói thành viên quyết định đêm của bạn vươn xa đến đâu.",
    "disc_f4_t": "Bán kính của bạn, đêm của bạn",
    "disc_feat_t": "Tạo ra để đưa bạn ra khỏi nhà",
    "disc_kicker": "Khám phá",
    "disc_lead": "Ứng dụng hẹn hò một đêm cho những ai quyết định lúc 7 giờ tối rằng họ muốn gặp ai đó — tối nay, không phải ngày mai.",
    "disc_p1": "Hầu hết ứng dụng hẹn hò xếp lịch cà phê ba tuần sau. 2NIGHT được tạo ra cho những giờ giữa bây giờ và 2 giờ sáng — khoảng thời gian mà kế hoạch thực sự xảy ra. Lên sóng, xem ai đang ra ngoài gần bạn, ping, ghép đôi và gặp gỡ.",
