    "nav_join": "Tham gia danh sách chờ",
    "sec1_b": "Bạn quyết định khi nào lên sóng, bán kính vươn xa đến đâu và chia sẻ những gì. Ngoại tuyến là bạn biến mất.",
    "sec1_t": "Bạn luôn nắm quyền kiểm soát",
