    "sec2_t": "Riêng tư mặc định",
    "sec3_b": "Mã hóa khi truyền, quyền truy cập bị giới hạn nghiêm ngặt và không bao giờ bị bán. Đọc chi tiết trong Chính sách quyền riêng tư của chúng tôi.",
    "sec3_t": "Dữ liệu của bạn, được bảo vệ",
    "sec4_b": "Bất kỳ ai khiến bạn khó chịu đều có thể bị chặn và báo cáo ngay lập tức. Đội ngũ của chúng tôi xem xét mọi báo cáo.",
    "sec4_t": "Chặn và báo cáo chỉ một chạm",
