    "faq_q1": "Apakah 2NIGHT gratis?",
    "faq_a1": "Ya. Bergabung di 2NIGHT dan bertemu orang itu gratis. Keanggotaan berbayar sedang disiapkan, dan kamu akan melihat persis berapa harganya di aplikasi sebelum ada tagihan apa pun.",
    "faq_q2": "Kapan diluncurkan di kotaku?",
    "faq_a2": "Kami membuka kota secara bertahap. Bergabunglah di daftar tunggu dan kami akan mengabarimu begitu 2NIGHT hadir di dekatmu.",
    "faq_q3": "Apa bedanya dengan aplikasi kencan lain?",
    "faq_a3": "Tak ada geser tanpa henti menuju “suatu hari nanti.” 2NIGHT menunjukkan siapa yang sedang keluar di dekatmu sekarang juga dan membantumu benar-benar bertemu — malam ini, bukan tiga minggu lagi.",
    "faq_q4": "Apakah aman?",
    "faq_a4": "Kamu yang menentukan kapan kamu aktif, sejauh apa radiusmu, dan apa yang kamu bagikan. Blokir dan laporkan dalam sekali ketuk, lalu pergi offline untuk menghilang seketika. Mohon baca panduan Keamanan kami sebelum bertemu.",
    "faq_q5": "Apa yang kudapat jika bergabung lebih awal?",
    "faq_a5": "20 anggota pertama mendapatkan Platinum Black 1 tahun, gratis. 200 berikutnya mendapatkan Gold gratis. Anggota paling awal yang menguasai malam.",
    "faq_q6": "Apakah kalian menjual dataku?",
    "faq_a6": "Tidak pernah. Kami tidak menjual data pribadimu dan kami tidak menjalankan pelacakan iklan pihak ketiga. Kamu selalu memegang kendali — lihat Pilihan Privasimu.",
    "sticky_note": "Gratis untuk bergabung · 18+",
    "aria_menu": "Menu",
    "disclaimer_html": "<strong>2NIGHT diperuntukkan bagi orang dewasa berusia 18 tahun ke atas.</strong> 2NIGHT akan segera diluncurkan; beberapa fitur dan unduhan App Store mungkin belum tersedia di wilayah Anda. Tampilan dan foto aplikasi hanya untuk ilustrasi, dan testimoni berasal dari pengguna beta serta bersifat representatif. 2NIGHT membantu orang bertemu tetapi <strong>tidak</strong> melakukan pemeriksaan latar belakang atau identitas — silakan baca panduan <a href=\"/safety\">Keselamatan</a> kami dan bertemulah secara bertanggung jawab. Dengan menggunakan 2NIGHT, Anda menyetujui <a href=\"/terms\">Ketentuan</a> dan <a href=\"/privacy\">Kebijakan Privasi</a> kami. Apple, logo Apple, dan App Store adalah merek dagang Apple Inc.; 2NIGHT tidak berafiliasi dengan, disponsori, atau didukung oleh Apple Inc.",
