    "pc_note": "Pilihan ini tersedia untuk semua orang, di mana pun — termasuk hak yang diberikan oleh GDPR (UE/UK) dan CCPA/CPRA (California). Kami tidak akan pernah membebankan biaya atau memperlakukan Anda berbeda karena menggunakannya.",
