    "gal_membership_t": "Keanggotaan",
    "gal_membership_s": "Silver · Gold · Platinum",
    "gal_profile_t": "Profil",
    "gal_profile_s": "Kamu, saat malam tiba",
    "tiers_note": "Harga dalam USD dan dapat berbeda menurut wilayah. Paket berbayar ditagih melalui Apple App Store dan diperpanjang otomatis sampai dibatalkan — kelola atau batalkan kapan saja di pengaturan App Store kamu. Lihat Ketentuan kami.",
    "auth_login": "Masuk",
    "cg1_b": "Gunakan foto sendiri dan detail yang asli. Tidak ada profil palsu, peniruan identitas, atau catfishing.",
    "cg1_t": "Jadilah nyata",
    "cg2_b": "Tidak ada pelecehan, ujaran kebencian, ancaman, atau konten eksplisit yang tidak diminta. Perlakukan orang lain seperti kamu ingin diperlakukan.",
    "cg2_t": "Saling menghormati",
    "cg3_b": "2NIGHT khusus untuk orang dewasa. Siapa pun yang di bawah umur langsung dikeluarkan.",
    "cg3_t": "Hanya usia 18 ke atas",
    "cg4_b": "Tidak ada jual beli, prostitusi, penawaran, penipuan, atau meminta uang, hadiah, atau kripto dari anggota.",
    "cg4_t": "Tanpa uang, tanpa bisnis",
    "cg5_b": "Tidak merekam atau membagikan siapa pun tanpa izin, tidak doxing, tidak membagikan informasi pribadi.",
    "cg5_t": "Jaga tetap atas persetujuan",
    "cg6_b": "Blokir dan laporkan siapa pun yang melewati batas. Tim kami meninjau setiap laporan — pelaporan menjaga malam tetap aman.",
    "cg6_t": "Laporkan yang salah",
    "cg_contact": "Melihat sesuatu yang serius? Email kami — kami baca setiap pesan.",
    "cg_kicker": "Komunitas",
    "cg_lead": "2NIGHT hanya berfungsi jika terasa aman dan nyata. Aturan ini menjaga malam tetap baik untuk semua orang — langgar dan kamu dikeluarkan.",
    "cg_title": "Pedoman Komunitas",
