    "faq_kicker": "Baik untuk diketahui",
    "faq_title": "Soalan, dijawab.",
    "faq_q1": "Adakah 2NIGHT percuma?",
    "faq_a1": "Ya. Menyertai 2NIGHT dan bertemu orang adalah percuma. Keahlian berbayar sedang dalam perjalanan, dan anda akan melihat dengan tepat berapa harganya di dalam aplikasi sebelum sebarang caj dikenakan.",
    "faq_q2": "Bila ia dilancarkan di bandar saya?",
    "faq_a2": "Kami membuka bandar secara berperingkat. Sertai senarai menunggu dan kami akan menghubungi anda sebaik sahaja 2NIGHT mula beroperasi berdekatan anda.",
    "faq_q3": "Apa bezanya dengan aplikasi temu janji lain?",
    "faq_a3": "Tiada leretan tanpa henti menuju “suatu hari nanti.” 2NIGHT menunjukkan siapa yang sedang keluar berdekatan anda sekarang dan membantu anda benar-benar bertemu — malam ini, bukan tiga minggu lagi.",
    "faq_q4": "Adakah ia selamat?",
    "faq_a4": "Anda yang menentukan bila anda aktif, sejauh mana radius anda dan apa yang anda kongsi. Sekat dan laporkan dengan satu ketikan, dan pergi luar talian untuk hilang serta-merta. Sila baca panduan Keselamatan kami sebelum anda bertemu.",
    "faq_q5": "Apa yang saya dapat dengan menyertai awal?",
    "faq_a5": "20 ahli pertama mendapat Platinum Black 1 tahun, percuma. 200 seterusnya mendapat Gold percuma. Ahli terawal menguasai malam.",
    "faq_q6": "Adakah anda menjual data saya?",
    "faq_a6": "Tidak sama sekali. Kami tidak menjual data peribadi anda dan kami tidak menjalankan penjejakan iklan pihak ketiga. Anda sentiasa memegang kawalan — lihat Pilihan Privasi anda.",
    "sticky_note": "Percuma untuk menyertai · 18+",
    "aria_menu": "Menu",
    "disclaimer_html": "<strong>2NIGHT adalah untuk orang dewasa berumur 18 tahun ke atas.</strong> 2NIGHT akan dilancarkan tidak lama lagi; sesetengah ciri dan muat turun App Store mungkin belum tersedia di wilayah anda. Paparan dan foto aplikasi adalah untuk ilustrasi sahaja, dan testimoni adalah daripada pengguna beta serta bersifat mewakili. 2NIGHT membantu orang bertemu tetapi <strong>tidak</strong> menjalankan semakan latar belakang atau identiti — sila baca panduan <a href=\"/safety\">Keselamatan</a> kami dan bertemu dengan bertanggungjawab. Dengan menggunakan 2NIGHT, anda bersetuju dengan <a href=\"/terms\">Terma</a> dan <a href=\"/privacy\">Dasar Privasi</a> kami. Apple, logo Apple dan App Store ialah tanda dagangan Apple Inc.; 2NIGHT tidak bergabung dengan, ditaja atau disokong oleh Apple Inc.",
    "swipe_c1_t": "Rooftop, 9 malam",
    "swipe_c1_s": "Sedang berlangsung · 1.2 km",
    "swipe_c2_t": "Persembahan live malam ini",
    "swipe_c2_s": "Dalam talian · sebentar tadi",
    "swipe_c3_t": "Siapa yang keluar malam ini?",
