    "pc_kicker": "Privasi anda",
    "pc_title": "Pilihan privasi anda",
    "pc_lead": "Anda yang mengawal data anda di 2NIGHT. Inilah cara menggunakan pilihan privasi anda, pada bila-bila masa.",
    "pc1_t": "Akses data anda",
    "pc1_b": "Minta salinan data peribadi yang kami simpan tentang anda, dan kami akan menghantarkannya kepada anda.",
    "pc2_t": "Padam akaun & data anda",
    "pc2_b": "Padam akaun anda pada bila-bila masa di Tetapan → Akaun → Padam akaun, atau hantar e-mel kepada kami. Kami memadam data anda, tertakluk kepada sebarang penyimpanan yang dikehendaki undang-undang.",
    "pc3_t": "Berhenti menerima pemasaran",
    "pc3_b": "Matikan e-mel promosi dan pemberitahuan tolak di Tetapan → Pemberitahuan, atau gunakan pautan berhenti melanggan dalam mana-mana e-mel.",
    "pc4_t": "Tidak menjual atau berkongsi",
    "pc4_b": "Kami tidak pernah menjual data peribadi anda dan tidak pernah berkongsinya untuk pengiklanan tingkah laku merentas konteks — jadi tiada apa yang perlu anda tolak.",
    "pc5_t": "Urus kuki",
    "pc5_b": "Tukar pilihan kuki dan penjejakan anda pada bila-bila masa melalui sepanduk kuki atau tetapan pelayar anda.",
    "pc6_t": "Lokasi & kebenaran",
    "pc6_b": "Kawal akses lokasi, kamera dan pemberitahuan dari tetapan peranti anda, dan batalkan mana-mana satu bila-bila masa anda mahu.",
    "pc_note": "Pilihan ini tersedia untuk semua orang, di mana-mana sahaja — termasuk hak yang diberikan oleh GDPR (EU/UK) dan CCPA/CPRA (California). Kami tidak akan sesekali mengenakan bayaran atau memperlakukan anda secara berbeza kerana menggunakannya.",
