    "waitlist_placeholder": "E-mel anda",
    "waitlist_button": "Beritahu saya",
    "waitlist_done": "Anda kini dalam senarai. Jumpa malam ini.",
    "about_kicker": "Perihal 2NIGHT",
    "about_title": "Malam ini, bukan esok.",
    "about_lead": "2NIGHT untuk saat anda memutuskan pada jam 7 malam bahawa anda benar-benar mahu buat sesuatu — dan mahu orang sebenar berdekatan yang merasakan perkara yang sama.",
    "about_story_pull": "Kebanyakan malam mati dalam group chat. “Jom lepak satu hari nanti.” Hari nanti itu tak pernah tiba.",
    "about_story_t": "Malam anda benar-benar keluar",
    "about_story_p1": "2NIGHT dibina berpaksikan satu idea degil: malam terbaik tidak dirancang tiga minggu lebih awal. Ia berlaku kerana seseorang, di suatu tempat berdekatan, lapang sekarang dan bersedia bergerak. Kami buat aplikasi yang menukar desakan itu menjadi rancangan sebenar — pantas, bersemuka, malam ini.",
    "about_story_p2": "Tetapkan status anda dalam satu baris. Lihat siapa yang keluar berdekatan anda. Ping, padan, jumpa. Tiada leretan tanpa henti menuju “mungkin minggu depan”. Hanya orang yang keluar malam ini, dan laluan paling singkat untuk berada di ruang yang sama.",
    "about_world_t": "Seluruh dunia, tidak terhad ikut bandar",
    "about_world_p1": "2NIGHT tidak dilancarkan satu bandar pada satu masa. Ia berfungsi di mana sahaja di muka bumi — dengan orang berdekatan anda, di mana sahaja anda berada malam ini. Mendarat di bandar baharu dan malamnya sudah hidup.",
    "about_world_p2": "Anda yang menentukan sejauh mana jangkauannya. Pilih radius anda — dari jalan anda hingga seluruh bandar — dan 2NIGHT menunjukkan siapa yang keluar di dalamnya.",
    "about_who1_t": "Pengembara",
    "about_who1_b": "Bandar baharu, tiada kenalan, satu malam untuk dijadikan bermakna. Buka 2NIGHT dan malam tempatan sudah terbentang di hadapan anda.",
    "about_who2_t": "Ekspatriat",
    "about_who2_b": "Membina kehidupan di tempat baharu. Temui orang yang keluar malam ini di tempat yang kini anda panggil rumah.",
    "about_who3_t": "Penduduk tempatan",
    "about_who3_b": "Anda kenal bandar ini — anda cuma mahu teman untuk malam ini. Tetapkan status anda dan cari orang anda, tanpa perlu kalendar.",
    "about_design_t": "Direka untuk malam",
    "about_design_p": "Champagne hangat pada arang pekat. Bergaya editorial, tenang, dan sedikit eksklusif — dibina agar terasa seperti ruang terbaik di bandar, bukan suapan bising yang lain. Setiap skrin dibuat untuk orang yang membuat keputusan lewat dan bertindak pantas.",
    "support_kicker": "Sokongan",
    "support_title": "Bagaimana kami boleh bantu?",
    "support_lead": "Segala yang anda perlu tahu tentang 2NIGHT — dan manusia sebenar di hujung sana apabila anda memerlukannya.",
    "faq_q7": "Bagaimana anda mengendalikan privasi saya?",
    "faq_a7": "Kami hanya mengumpul apa yang diperlukan untuk membantu anda bertemu orang malam ini, dan kami tidak pernah menjual data peribadi anda. Anda memilih apa yang kelihatan kepada orang lain dan bila anda berkongsi lokasi. Baca butiran penuh dalam Dasar Privasi kami.",
    "faq_a7_link": "Dasar Privasi",
    "support_contact_t": "Masih perlukan bantuan?",
    "support_contact_p": "E-mel kami dan orang sebenar akan membalas anda. Kami membaca setiap mesej.",
    "nav_safety": "Keselamatan",
    "nav_contact": "Hubungi",
    "footer_safety": "Keselamatan",
    "footer_contact": "Hubungi",
    "contact_kicker": "Hubungi kami",
    "screens_disclaimer": "Semua foto hanya untuk ilustrasi.",
    "android_soon": "Android — akan tiba tidak lama lagi",
    "testimonials_kicker": "Dari malam",
    "testimonials_title": "Apa kata pengguna tentang kami",
    "testimonials_sub": "Malam-malam beta awal, dalam kata-kata mereka sendiri.",
    "testimonials_note": "Petikan daripada pengguna beta. Nama dan bandar bersifat perwakilan.",
    "testimonial1_q": "Saya mendarat di Lisbon tanpa sebarang rancangan. Menjelang 9 malam saya sudah di bar atas bumbung bersama tiga orang yang baru saya Match. Itulah keseluruhan aplikasi ini dalam satu malam.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lisbon",
    "testimonial2_q": "Tiada lagi “jom lepak nanti.” Saya tetapkan status, lihat siapa yang lapang, dan benar-benar bertemu seseorang pada malam yang sama. Akhirnya.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Paris",
    "testimonial3_q": "Black Events memang luar biasa. Ia bukan seperti aplikasi, tetapi lebih seperti jemputan ke ruang terbaik di bandar.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "Bandar baharu kerana kerja, tidak kenal sesiapa. Dua minggu kemudian saya sudah ada kumpulan rakan yang sebenar — semuanya bermula daripada keputusan jam 7 malam bahawa saya tak mahu duduk di rumah.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlin",
    "testimonial5_q": "Pantas, indah, dan benar-benar menghormati masa anda. Ping, Match, bertemu — tepat seperti yang dijanjikan.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "London",
    "testimonial6_q": "Travel Mode ibarat kod tipu. Saya buka 2NIGHT sebaik sahaja mendarat dan malam tempatan sudah menanti.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "New York",
    "safety_kicker": "Keselamatan",
    "safety_title": "Bertemu orang dengan cara yang bijak.",
    "safety_lead": "2NIGHT dibina untuk malam yang spontan dan nyata. Beberapa tabiat mudah memastikan ia tetap seronok — dan membolehkan anda terus memegang kawalan apabila bertemu orang baharu.",
    "safety_t1_t": "Bertemu di tempat awam",
    "safety_t1_b": "Untuk pertemuan pertama, pilih tempat yang sibuk dan terang — bar, kafe, tempat yang popular. Kekal di tempat awam sehingga anda benar-benar berasa selesa, dan jangan pergi ke lokasi peribadi dengan orang yang baru anda kenali.",
    "safety_t2_t": "Beritahu rancangan kepada rakan",
    "safety_t2_b": "Beritahu seseorang yang anda percayai ke mana anda pergi, bertemu siapa, dan bila anda dijangka pulang. Kongsi lokasi langsung anda dengan mereka pada malam itu dan beri tahu mereka selepas itu.",
    "safety_t3_t": "Uruskan pengangkutan anda sendiri",
    "safety_t3_b": "Pergi dan pulang mengikut cara anda sendiri. Pastikan telefon anda bercas, tahu cara anda pulang, dan anda bebas untuk beredar bila-bila masa anda mahu — tanpa perlu penjelasan.",
    "safety_t4_t": "Jangan sekali-kali hantar wang",
    "safety_t4_b": "Jangan sekali-kali menghantar wang, kad hadiah, atau kripto kepada orang yang anda temui dalam aplikasi, walau apa pun ceritanya. Permintaan wang tunai, bantuan kewangan, atau “tip” pelaburan ialah penipuan klasik — berhenti dan laporkan.",
    "safety_t5_t": "Percaya gerak hati anda",
    "safety_t5_b": "Jika ada sesuatu yang terasa tidak kena, biasanya memang begitu. Anda tak pernah terhutang masa kepada sesiapa. Tamatkan sembang, tinggalkan pertemuan, atau hubungi rakan — tiada sebab yang salah untuk beredar.",
    "safety_t6_t": "Laporkan & sekat",
    "safety_t6_b": "Sesiapa yang membuat anda berasa tidak selesa boleh disekat dan dilaporkan dengan satu ketikan. Pasukan kami menyemak laporan — menandakan kelakuan buruk menjadikan seluruh malam lebih selamat untuk semua.",
    "safety_t7_t": "Lindungi maklumat peribadi anda",
    "safety_t7_b": "Kekalkan sembang di dalam 2NIGHT sehingga anda mempercayai seseorang. Jangan kongsi alamat rumah, tempat kerja, butiran kewangan, atau dokumen anda, dan berhati-hati dengan foto yang mendedahkan lokasi tepat tempat tinggal anda.",
    "safety_t8_t": "Anda yang memegang kawalan",
    "safety_t8_b": "Anda yang menentukan bila anda dalam talian, sejauh mana radius anda, dan apa yang anda kongsi. Kami tidak menjalankan semakan latar belakang, jadi pertimbangan anda sendiri sentiasa diutamakan.",
    "safety_help_t": "Dalam kecemasan, minta bantuan.",
    "safety_help_p": "Jika anda berasa tidak selamat atau terancam, hubungi perkhidmatan kecemasan tempatan terlebih dahulu. Untuk melaporkan seseorang atau sesuatu kepada kami, e-mel pasukan kami — kami membaca setiap mesej.",
    "cookie_text": "Kami menggunakan kuki untuk memastikan 2NIGHT berfungsi dan untuk memahami cara laman ini digunakan.",
