    "founders_p1": "Hugo dan Jeric, dua sahabat dari Switzerland, sentiasa terlanggar tembok yang sama: bandar penuh dengan orang, sembang kumpulan penuh dengan „kita patut keluar tak lama lagi“, tetapi malam ini tiada siapa yang benar-benar keluar.",
    "founders_p2": "Hugo, pengasasnya, menulis kod. Jeric, rakan kongsinya, menerajui projek dan membentuk pengalaman. Dari sebuah meja dapur di Switzerland hingga ke tempat anda berdiri malam ini — itulah keseluruhan ceritanya.",
