    "pc_kicker": "आपकी प्राइवेसी",
    "pc_title": "आपके प्राइवेसी विकल्प",
    "pc_lead": "2NIGHT पर आपके डेटा का नियंत्रण आपके हाथ में है। यहाँ बताया गया है कि आप अपने प्राइवेसी विकल्पों का इस्तेमाल कभी भी कैसे कर सकते हैं।",
    "pc1_t": "अपना डेटा देखें",
    "pc1_b": "आपके बारे में हमारे पास मौजूद व्यक्तिगत डेटा की एक कॉपी माँगें, और हम उसे आपको भेज देंगे।",
    "pc2_t": "अपना अकाउंट और डेटा हटाएँ",
    "pc2_b": "अपना अकाउंट कभी भी सेटिंग्स → अकाउंट → अकाउंट हटाएँ में जाकर हटाएँ, या हमें ईमेल करें। हम आपका डेटा मिटा देते हैं, बशर्ते कोई कानूनी रोक न हो।",
    "pc3_t": "मार्केटिंग से बाहर निकलें",
    "pc3_b": "प्रोमोशनल ईमेल और पुश नोटिफिकेशन सेटिंग्स → नोटिफिकेशन में बंद करें, या किसी भी ईमेल में दिए अनसब्सक्राइब लिंक का इस्तेमाल करें।",
    "pc4_t": "न बेचना, न साझा करना",
    "pc4_b": "हम आपका व्यक्तिगत डेटा कभी नहीं बेचते और क्रॉस-कॉन्टेक्स्ट बिहेवियरल विज्ञापन के लिए कभी साझा नहीं करते — इसलिए इससे बाहर निकलने जैसा कुछ है ही नहीं।",
    "pc5_t": "कुकीज़ प्रबंधित करें",
    "pc5_b": "अपनी कुकी और ट्रैकिंग प्राथमिकताएँ कभी भी कुकी बैनर या अपने ब्राउज़र की सेटिंग्स के ज़रिए बदलें।",
    "pc6_t": "लोकेशन और अनुमतियाँ",
    "pc6_b": "अपने डिवाइस की सेटिंग्स से लोकेशन, कैमरा और नोटिफिकेशन की पहुँच नियंत्रित करें, और इनमें से किसी को भी जब चाहें वापस ले लें।",
    "pc_note": "ये विकल्प हर किसी के लिए, हर जगह उपलब्ध हैं — इनमें GDPR (EU/UK) और CCPA/CPRA (California) द्वारा दिए गए अधिकार भी शामिल हैं। इनका इस्तेमाल करने पर हम आपसे कभी कोई शुल्क नहीं लेंगे और न ही आपके साथ अलग व्यवहार करेंगे।",
    "pc_contact": "प्राइवेसी अधिकार का इस्तेमाल करने के लिए privacy@2night.co पर ईमेल करें — हम 30 दिनों के भीतर जवाब देते हैं।",
