    "about_kicker": "2NIGHT के बारे में",
    "about_title": "आज रात, कल नहीं।",
    "about_lead": "2NIGHT उस पल के लिए है जब शाम 7 बजे आप तय करते हैं कि आप सचमुच कुछ करना चाहते हैं — और चाहते हैं कि आपके पास असली लोग हों जो वही महसूस करते हों।",
    "about_story_pull": "ज़्यादातर रातें किसी ग्रुप चैट में ही दम तोड़ देती हैं। “जल्दी ही मिलते हैं।” वो जल्दी कभी नहीं आती।",
    "about_story_t": "वो रात जब आप सचमुच बाहर निकलते हैं",
    "about_story_p1": "2NIGHT एक ज़िद्दी सोच के इर्द-गिर्द बना है: सबसे अच्छी रातें तीन हफ़्ते पहले प्लान नहीं की जातीं। वे इसलिए होती हैं क्योंकि कोई न कोई पास में अभी फ्री है और चलने को तैयार है। हमने वो ऐप बनाया जो इस आवेग को एक असली प्लान में बदल देता है — तेज़ी से, आमने-सामने, आज रात।",
    "about_story_p2": "अपना स्टेटस एक लाइन में सेट करें। देखें कौन आपके पास बाहर है। Ping करें, मैच करें, मिलें। “शायद अगले हफ़्ते” की ओर बेमतलब स्वाइप नहीं। बस वही लोग जो आज रात बाहर हैं, और एक ही कमरे में पहुँचने का सबसे छोटा रास्ता।",
    "about_world_t": "दुनिया भर में, किसी शहर तक सीमित नहीं",
    "about_world_p1": "2NIGHT एक-एक शहर करके नहीं आ रहा। यह धरती पर कहीं भी काम करता है — आपके पास के लोगों के साथ, आज रात आप जहाँ भी हों। किसी नए शहर में उतरें और रात पहले से ही चल रही है।",
    "about_world_p2": "आप तय करते हैं कि यह कितनी दूर तक पहुँचे। अपना दायरा चुनें — अपनी गली से लेकर पूरे शहर तक — और 2NIGHT आपको दिखाता है कि उसमें कौन बाहर है।",
    "about_who1_t": "यात्री",
    "about_who1_b": "नया शहर, कोई जान-पहचान नहीं, इसे यादगार बनाने के लिए एक रात। 2NIGHT खोलें और स्थानीय रात पहले से ही आपके सामने है।",
    "about_who2_t": "प्रवासी",
    "about_who2_b": "किसी नई जगह ज़िंदगी बसा रहे हैं। उन लोगों से मिलें जो आज रात उसी जगह बाहर हैं जिसे अब आप घर कहते हैं।",
    "about_who3_t": "स्थानीय लोग",
    "about_who3_b": "आप शहर को जानते हैं — आपको बस आज रात के लिए साथ चाहिए। अपना स्टेटस सेट करें और अपने लोग खोजें, किसी कैलेंडर की ज़रूरत नहीं।",
    "about_design_t": "रात के लिए डिज़ाइन की गई",
    "about_design_p": "गहरे चारकोल पर गर्म शैंपेन। एडिटोरियल, शांत और थोड़ी एक्सक्लूसिव — ऐसी बनी कि शहर का सबसे बेहतरीन कमरा लगे, न कि एक और शोरगुल वाला फ़ीड। हर स्क्रीन उन लोगों के लिए बनी है जो देर से तय करते हैं और तेज़ चलते हैं।",
    "support_kicker": "सहायता",
    "support_title": "हम कैसे मदद कर सकते हैं?",
    "support_lead": "2NIGHT के बारे में आपको जो भी जानना चाहिए — और ज़रूरत पड़ने पर दूसरी तरफ़ एक असली इंसान।",
    "faq_q7": "आप मेरी प्राइवेसी कैसे संभालते हैं?",
    "faq_a7": "हम केवल वही इकट्ठा करते हैं जो आज रात आपको लोगों से मिलाने के लिए ज़रूरी है, और हम आपका व्यक्तिगत डेटा कभी नहीं बेचते। आप तय करते हैं कि दूसरों को क्या दिखे और लोकेशन कब साझा करें। पूरी जानकारी हमारी Privacy Policy में पढ़ें।",
    "faq_a7_link": "Privacy Policy",
    "support_contact_t": "फिर भी मदद चाहिए?",
    "support_contact_p": "हमें ईमेल करें और एक असली इंसान आपको जवाब देगा। हम हर संदेश पढ़ते हैं।",
    "nav_safety": "सुरक्षा",
