    "faq_kicker": "জানা ভালো",
    "faq_title": "প্রশ্ন, উত্তরসহ।",
    "faq_q1": "2NIGHT কি বিনামূল্যে?",
    "faq_a1": "হ্যাঁ। 2NIGHT-এ যোগ দেওয়া আর মানুষের সঙ্গে দেখা করা বিনামূল্যে। একটি অর্থপ্রদত্ত সদস্যপদ আসছে, আর কিছু চার্জ হওয়ার আগেই অ্যাপে আপনি ঠিক দেখতে পাবেন তার দাম কত।",
    "faq_q2": "এটা আমার শহরে কবে চালু হবে?",
    "faq_a2": "আমরা শহরগুলো ধাপে ধাপে চালু করি। অপেক্ষমাণ তালিকায় যোগ দিন, আর 2NIGHT আপনার কাছে চালু হওয়ার সঙ্গে সঙ্গে আমরা আপনাকে বার্তা পাঠাব।",
    "faq_q3": "অন্য ডেটিং অ্যাপ থেকে এটা কীভাবে আলাদা?",
    "faq_a3": "“কোনো একদিন”-এর দিকে অবিরাম সোয়াইপ নয়। 2NIGHT দেখায় এখন আপনার কাছে কে বেরিয়েছে এবং আপনাকে সত্যিই দেখা করতে সাহায্য করে — আজ রাতেই, তিন সপ্তাহ পরে নয়।",
    "faq_q4": "এটা কি নিরাপদ?",
    "faq_a4": "আপনি ঠিক করেন কখন আপনি লাইভ থাকবেন, আপনার পরিধি কতদূর পৌঁছাবে এবং আপনি কী শেয়ার করবেন। এক ট্যাপে ব্লক ও রিপোর্ট করুন, আর সঙ্গে সঙ্গে অদৃশ্য হতে অফলাইনে যান। দেখা করার আগে দয়া করে আমাদের নিরাপত্তা নির্দেশিকা পড়ুন।",
    "faq_q5": "আগে যোগ দিলে আমি কী পাব?",
    "faq_a5": "প্রথম ২০ জন সদস্য ১ বছরের Platinum Black, বিনামূল্যে পান। পরবর্তী ২০০ জন বিনামূল্যে Gold পান। সবচেয়ে আগে যোগ দেওয়া সদস্যরাই রাতের মালিক।",
    "faq_q6": "আপনারা কি আমার ডেটা বিক্রি করেন?",
    "faq_a6": "কখনও না। আমরা আপনার ব্যক্তিগত ডেটা বিক্রি করি না এবং তৃতীয় পক্ষের বিজ্ঞাপন ট্র্যাকিং চালাই না। নিয়ন্ত্রণ সবসময় আপনার হাতে — আপনার গোপনীয়তা পছন্দ দেখুন।",
    "sticky_note": "যোগ দেওয়া বিনামূল্যে · ১৮+",
    "aria_menu": "মেনু",
    "disclaimer_html": "<strong>2NIGHT ১৮ বছর ও তার বেশি বয়সী প্রাপ্তবয়স্কদের জন্য।</strong> 2NIGHT শীঘ্রই চালু হচ্ছে; কিছু বৈশিষ্ট্য এবং App Store ডাউনলোড এখনও আপনার অঞ্চলে উপলব্ধ নাও থাকতে পারে। অ্যাপের স্ক্রিন ও ছবি শুধুমাত্র দৃষ্টান্তের জন্য, এবং প্রশংসাপত্রগুলো বিটা ব্যবহারকারীদের কাছ থেকে এবং প্রতিনিধিত্বমূলক। 2NIGHT মানুষকে মিলিত হতে সাহায্য করে কিন্তু পটভূমি বা পরিচয় যাচাই <strong>করে না</strong> — অনুগ্রহ করে আমাদের <a href=\"/safety\">নিরাপত্তা</a> নির্দেশিকা পড়ুন এবং দায়িত্বশীলভাবে দেখা করুন। 2NIGHT ব্যবহার করে আপনি আমাদের <a href=\"/terms\">শর্তাবলী</a> এবং <a href=\"/privacy\">গোপনীয়তা নীতি</a>-তে সম্মত হন। Apple, Apple লোগো এবং App Store হলো Apple Inc.-এর ট্রেডমার্ক; 2NIGHT, Apple Inc. দ্বারা অনুমোদিত, পৃষ্ঠপোষকতাপ্রাপ্ত বা সমর্থিত নয় এবং এর সাথে যুক্ত নয়।",
