    "pc_kicker": "আপনার গোপনীয়তা",
    "pc_title": "আপনার গোপনীয়তার পছন্দসমূহ",
    "pc_lead": "2NIGHT-এ আপনার ডেটার নিয়ন্ত্রণ আপনারই হাতে। যেকোনো সময় আপনার গোপনীয়তার পছন্দগুলো কীভাবে কাজে লাগাবেন, তা এখানে দেওয়া হলো।",
    "pc1_t": "আপনার ডেটা দেখুন",
    "pc1_b": "আপনার সম্পর্কে আমাদের কাছে থাকা ব্যক্তিগত ডেটার একটি কপি চান, আর আমরা তা আপনাকে পাঠিয়ে দেব।",
    "pc2_t": "আপনার অ্যাকাউন্ট ও ডেটা মুছুন",
    "pc2_b": "যেকোনো সময় Settings → Account → Delete account-এ গিয়ে আপনার অ্যাকাউন্ট মুছুন, অথবা আমাদের ইমেল করুন। কোনো আইনি সংরক্ষণের শর্ত সাপেক্ষে আমরা আপনার ডেটা মুছে ফেলি।",
    "pc3_t": "মার্কেটিং থেকে বেরিয়ে আসুন",
    "pc3_b": "Settings → Notifications-এ গিয়ে প্রচারমূলক ইমেল ও পুশ নোটিফিকেশন বন্ধ করুন, অথবা যেকোনো ইমেলে থাকা আনসাবস্ক্রাইব লিঙ্ক ব্যবহার করুন।",
    "pc4_t": "বিক্রি বা শেয়ার নয়",
    "pc4_b": "আমরা কখনোই আপনার ব্যক্তিগত ডেটা বিক্রি করি না এবং ক্রস-কনটেক্সট আচরণগত বিজ্ঞাপনের জন্য কখনো শেয়ার করি না — তাই এ থেকে বেরিয়ে আসার মতো কিছু নেই।",
    "pc5_t": "কুকি পরিচালনা করুন",
    "pc5_b": "কুকি ব্যানার বা আপনার ব্রাউজারের সেটিংসের মাধ্যমে যেকোনো সময় আপনার কুকি ও ট্র্যাকিং পছন্দ পরিবর্তন করুন।",
    "pc6_t": "লোকেশন ও অনুমতি",
    "pc6_b": "আপনার ডিভাইসের সেটিংস থেকে লোকেশন, ক্যামেরা ও নোটিফিকেশনের অ্যাক্সেস নিয়ন্ত্রণ করুন, এবং যখন খুশি এর যেকোনোটি প্রত্যাহার করুন।",
    "pc_note": "এই পছন্দগুলো সবার জন্য, সর্বত্র উপলব্ধ — এর মধ্যে GDPR (EU/UK) এবং CCPA/CPRA (California)-এর দেওয়া অধিকারও রয়েছে। এগুলো ব্যবহারের জন্য আমরা কখনো আপনার কাছ থেকে কোনো অর্থ নেব না বা আপনার সঙ্গে ভিন্ন আচরণ করব না।",
    "pc_contact": "কোনো গোপনীয়তার অধিকার প্রয়োগ করতে privacy@2night.co-এ ইমেল করুন — আমরা ৩০ দিনের মধ্যে সাড়া দিই।",
