    "founders_p2": "প্রতিষ্ঠাতা Hugo কোড লেখেন। তাঁর সহযোগী Jeric প্রকল্পটি চালান আর অভিজ্ঞতাটিকে গড়ে তোলেন। সুইজারল্যান্ডের এক রান্নাঘরের টেবিল থেকে আজ রাতে আপনি যেখানে দাঁড়িয়ে, সেখান পর্যন্ত — এটুকুই পুরো গল্প।",
