    "about_world_p1": "2NIGHT ایک ایک شہر کرکے نہیں آ رہا۔ یہ زمین پر کہیں بھی کام کرتا ہے — آپ کے قریب کے لوگوں کے ساتھ، آج رات آپ جہاں بھی ہوں۔ کسی نئے شہر میں اتریں اور رات پہلے ہی چل رہی ہے۔",
    "about_world_p2": "آپ طے کرتے ہیں کہ یہ کہاں تک پہنچے۔ اپنا دائرہ چنیں — اپنی گلی سے لے کر پورے شہر تک — اور 2NIGHT آپ کو دکھاتا ہے کہ اس کے اندر کون باہر ہے۔",
    "about_who1_t": "مسافر",
    "about_who1_b": "نیا شہر، کوئی جان پہچان نہیں، اسے یادگار بنانے کے لیے ایک رات۔ 2NIGHT کھولیں اور مقامی رات پہلے ہی آپ کے سامنے ہے۔",
    "about_who2_t": "تارکینِ وطن",
    "about_who2_b": "کسی نئی جگہ زندگی بسا رہے ہیں۔ اُن لوگوں سے ملیں جو آج رات اُسی جگہ باہر ہیں جسے اب آپ گھر کہتے ہیں۔",
    "about_who3_t": "مقامی لوگ",
    "about_who3_b": "آپ شہر کو جانتے ہیں — آپ کو بس آج رات کے لیے ساتھ چاہیے۔ اپنا اسٹیٹس سیٹ کریں اور اپنے لوگ ڈھونڈیں، کسی کیلنڈر کی ضرورت نہیں۔",
    "about_design_t": "رات کے لیے ڈیزائن کی گئی",
    "about_design_p": "گہرے چارکول پر گرم شیمپین۔ ایڈیٹوریل، پُرسکون اور تھوڑی خصوصی — ایسی بنی کہ شہر کا بہترین کمرہ لگے، نہ کہ ایک اور شور والی فیڈ۔ ہر اسکرین اُن لوگوں کے لیے بنی ہے جو دیر سے طے کرتے ہیں اور تیز چلتے ہیں۔",
    "support_kicker": "سپورٹ",
    "support_title": "ہم کیسے مدد کر سکتے ہیں؟",
    "support_lead": "2NIGHT کے بارے میں آپ کو جو کچھ جاننا چاہیے — اور ضرورت پر دوسری طرف ایک حقیقی انسان۔",
