    "testimonials_note": "بیٹا صارفین کے اقتباسات۔ نام اور شہر علامتی ہیں۔",
    "testimonial1_q": "میں بغیر کسی منصوبے کے Lisbon اترا۔ رات نو بجے تک میں ایک روف ٹاپ بار میں تین ایسے لوگوں کے ساتھ تھا جن سے ابھی ابھی Match ہوا تھا۔ ایک ہی رات میں پوری ایپ بس یہی ہے۔",
