    "testimonial1_c": "Lisbon",
    "testimonial2_q": "اب وہ ”جلد کبھی ملتے ہیں“ والی بات نہیں رہی۔ میں نے اپنا اسٹیٹس سیٹ کیا، دیکھا کون فارغ ہے، اور اسی شام واقعی کسی سے ملی۔ آخرکار۔",
