    "testimonial2_c": "Paris",
    "testimonial3_q": "Black Events تو ناقابلِ یقین ہیں۔ یہ کسی ایپ سے کم اور شہر کے بہترین کمرے میں داخلے کی دعوت سے زیادہ لگتا ہے۔",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "کام کے سلسلے میں نیا شہر، کسی کو نہیں جانتا تھا۔ دو ہفتوں میں ہی میرا ایک حقیقی دوستوں کا حلقہ بن گیا — اور یہ سب شام سات بجے اس فیصلے سے شروع ہوا کہ مجھے گھر پر نہیں رہنا۔",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlin",
    "testimonial5_q": "یہ تیز ہے، خوبصورت ہے، اور واقعی آپ کے وقت کا احترام کرتی ہے۔ Ping، Match، ملاقات — بالکل ویسے ہی جیسا وعدہ کیا گیا تھا۔",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "London",
    "testimonial6_q": "Travel Mode تو ایک چیٹ کوڈ ہے۔ اترتے ہی میں 2NIGHT کھول لیتا ہوں اور مقامی رات پہلے سے میرے انتظار میں ہوتی ہے۔",
