    "safety_kicker": "حفاظت",
    "safety_title": "لوگوں سے سمجھداری کے ساتھ ملیں۔",
    "safety_lead": "2NIGHT اچانک، حقیقی زندگی کی راتوں کے لیے بنائی گئی ہے۔ چند آسان عادتیں انہیں مزے دار رکھتی ہیں — اور نئے لوگوں سے ملتے وقت آپ کو اختیار میں رکھتی ہیں۔",
    "safety_t1_t": "عوامی جگہ پر ملیں",
    "safety_t1_b": "پہلی ملاقات کے لیے کوئی ایسی جگہ چنیں جو پُررونق اور اچھی روشنی والی ہو — کوئی بار، کیفے یا مقبول جگہ۔ جب تک آپ واقعی آرام دہ محسوس نہ کریں، عوامی جگہ پر ہی رہیں، اور ابھی ملے کسی شخص کے ساتھ کسی نجی مقام پر نہ جائیں۔",
    "safety_t2_t": "اپنا منصوبہ کسی دوست کو بتائیں",
    "safety_t2_b": "کسی بھروسے مند شخص کو بتائیں کہ آپ کہاں جا رہے ہیں، کس سے مل رہے ہیں، اور کب تک واپس آنے کی توقع رکھتے ہیں۔ اس رات اپنی لائیو لوکیشن ان کے ساتھ شیئر کریں اور بعد میں انہیں اطلاع دیں۔",
    "safety_t3_t": "اپنی آمد و رفت خود طے کریں",
    "safety_t3_b": "جانا اور واپس آنا اپنی مرضی سے کریں۔ اپنا فون چارج رکھیں، جانیں کہ آپ گھر کیسے جائیں گے، اور آپ جب چاہیں جانے کے لیے آزاد ہیں — کسی وضاحت کی ضرورت نہیں۔",
    "safety_t4_t": "کبھی پیسے نہ بھیجیں",
    "safety_t4_b": "ایپ پر ملے کسی شخص کو کبھی پیسے، گفٹ کارڈ یا کرپٹو نہ بھیجیں، کہانی کچھ بھی ہو۔ نقدی، مالی مدد یا سرمایہ کاری کی ”ٹپس“ کا مطالبہ کلاسیکی دھوکا ہے — رک جائیں اور رپورٹ کریں۔",
    "safety_t5_t": "اپنی اندرونی آواز پر بھروسہ کریں",
    "safety_t5_b": "اگر کچھ ٹھیک نہ لگے، تو غالباً واقعی کچھ ٹھیک نہیں۔ آپ کسی کو اپنا وقت دینے کے پابند نہیں۔ چیٹ ختم کریں، ملاقات چھوڑ دیں، یا کسی دوست کو کال کریں — چلے جانے کی کوئی وجہ غلط نہیں ہوتی۔",
    "safety_t6_t": "رپورٹ کریں اور بلاک کریں",
    "safety_t6_b": "جو بھی آپ کو بے چین کرے اسے ایک ٹیپ میں بلاک اور رپورٹ کیا جا سکتا ہے۔ ہماری ٹیم رپورٹس کا جائزہ لیتی ہے — برے رویے کی نشاندہی پوری رات کو سب کے لیے زیادہ محفوظ بناتی ہے۔",
    "safety_t7_t": "اپنی ذاتی معلومات کی حفاظت کریں",
    "safety_t7_b": "جب تک آپ کسی پر بھروسہ نہ کریں، چیٹ 2NIGHT کے اندر ہی رکھیں۔ اپنا گھر کا پتا، کام کی جگہ، مالی تفصیلات یا دستاویزات شیئر نہ کریں، اور ایسی تصاویر کے بارے میں محتاط رہیں جو ٹھیک ٹھیک ظاہر کر دیں کہ آپ کہاں رہتے ہیں۔",
    "safety_t8_t": "اختیار آپ کے ہاتھ میں ہے",
    "safety_t8_b": "آپ طے کرتے ہیں کہ آپ کب لائیو ہیں، آپ کا دائرہ کتنی دور تک پہنچتا ہے، اور آپ کیا شیئر کرتے ہیں۔ ہم پس منظر کی جانچ نہیں کرتے، اس لیے آپ کی اپنی سمجھ بوجھ ہمیشہ سب سے پہلے آتی ہے۔",
    "safety_help_t": "ہنگامی صورتحال میں، مدد کے لیے کال کریں۔",
    "safety_help_p": "اگر آپ کبھی غیر محفوظ یا خطرے میں محسوس کریں، تو پہلے اپنی مقامی ہنگامی خدمات سے رابطہ کریں۔ کسی شخص یا بات کی ہمیں رپورٹ کرنے کے لیے ہماری ٹیم کو ای میل کریں — ہم ہر پیغام پڑھتے ہیں۔",
    "cookie_text": "ہم 2NIGHT کو چلانے اور یہ سمجھنے کے لیے کوکیز استعمال کرتے ہیں کہ سائٹ کیسے استعمال ہوتی ہے۔",
