    "about_kicker": "Kuhusu 2NIGHT",
    "about_title": "Leo usiku, si kesho.",
    "about_lead": "2NIGHT ni kwa ajili ya kile kipindi unapoamua saa moja jioni kwamba kwa kweli unataka kufanya jambo — na unataka watu halisi walio karibu wanaohisi vivyo hivyo.",
    "about_story_pull": "Usiku mwingi hufia kwenye gumzo la kikundi. “Tukutane hivi karibuni.” Hicho karibuni hakifiki kamwe.",
    "about_story_t": "Usiku ambao kweli unatoka nje",
    "about_story_p1": "2NIGHT ilijengwa kuzunguka wazo moja gumu: usiku bora zaidi haupangwi wiki tatu kabla. Hutokea kwa sababu mtu fulani, mahali karibu, yuko huru sasa hivi na tayari kusonga. Tulitengeneza programu inayobadilisha hamasa hiyo kuwa mpango halisi — haraka, ana kwa ana, leo usiku.",
    "about_story_p2": "Weka hali yako kwa mstari mmoja. Ona nani ametoka karibu nawe. Ping, lingana, kutana. Hakuna kuvinjari bila mwisho kuelekea “labda wiki ijayo.” Ni watu tu walio nje leo usiku, na njia fupi kabisa ya kuwa chumba kimoja.",
    "about_world_t": "Kote duniani, si kwa jiji moja moja",
    "about_world_p1": "2NIGHT haitolewi jiji moja kwa wakati. Inafanya kazi mahali popote duniani — na watu walio karibu nawe, popote ulipo leo usiku. Tua jiji jipya na usiku tayari uko hai.",
    "about_world_p2": "Wewe huamua ufike umbali gani. Chagua eneo lako — kutoka mtaa wako hadi jiji zima — na 2NIGHT itakuonyesha nani ametoka ndani yake.",
    "about_who1_t": "Wasafiri",
    "about_who1_b": "Jiji jipya, hakuna mawasiliano, usiku mmoja wa kuufanya uwe wa maana. Fungua 2NIGHT na usiku wa hapa tayari uko mbele yako.",
    "about_who2_t": "Wahamiaji",
    "about_who2_b": "Unajenga maisha mahali papya. Kutana na watu walio nje leo usiku mahali ambapo sasa unapaita nyumbani.",
    "about_who3_t": "Wenyeji",
    "about_who3_b": "Unalijua jiji — unataka tu mwenza wa leo usiku. Weka hali yako na upate watu wako, hakuna kalenda inayohitajika.",
    "about_design_t": "Imeundwa kwa ajili ya usiku",
    "about_design_p": "Shampeni ya joto juu ya makaa meusi. Ya kisasa, tulivu na ya kipekee kidogo — imejengwa ihisike kama chumba bora zaidi jijini, si mlisho mwingine wenye kelele. Kila skrini imetengenezwa kwa watu wanaoamua kuchelewa na kusonga haraka.",
    "support_kicker": "Usaidizi",
    "support_title": "Tunawezaje kukusaidia?",
    "support_lead": "Kila kitu unachohitaji kujua kuhusu 2NIGHT — na mtu halisi upande wa pili pale unapomhitaji.",
    "faq_q7": "Mnashughulikiaje faragha yangu?",
    "faq_a7": "Tunakusanya tu kinachohitajika kukusaidia kukutana na watu leo usiku, na kamwe hatuuzi data yako binafsi. Wewe huchagua kinachoonekana kwa wengine na wakati wa kushiriki eneo. Soma maelezo kamili katika Sera yetu ya Faragha.",
    "faq_a7_link": "Privacy Policy",
    "support_contact_t": "Bado unahitaji msaada?",
    "support_contact_p": "Tutumie barua pepe na mtu halisi atakujibu. Tunasoma kila ujumbe.",
    "nav_safety": "Usalama",
    "nav_contact": "Wasiliana",
    "footer_safety": "Usalama",
    "footer_contact": "Wasiliana",
    "contact_kicker": "Wasiliana nasi",
    "screens_disclaimer": "Picha zote ni za mfano tu.",
    "android_soon": "Android — inakuja hivi karibuni",
    "testimonials_kicker": "Kutoka usiku",
    "testimonials_title": "Watumiaji wetu walisema nini kuhusu sisi",
    "testimonials_sub": "Usiku wa awali wa beta, kwa maneno yao wenyewe.",
    "testimonials_note": "Nukuu kutoka kwa watumiaji wa beta. Majina na miji ni ya mfano.",
    "testimonial1_q": "Nilitua Lisbon bila mpango wowote. Kufikia saa tatu usiku nilikuwa kwenye baa ya darini na watu watatu ambao nilikuwa nimekutana nao kwa Match. Hiyo ndiyo app nzima katika usiku mmoja.",
    "testimonial1_n": "Marco",
    "testimonial1_c": "Lisbon",
    "testimonial2_q": "Hakuna tena “tukutane hivi karibuni.” Niliweka hali yangu, nikaona nani yuko huru, na kweli nikakutana na mtu jioni hiyo hiyo. Hatimaye.",
    "testimonial2_n": "Léa",
    "testimonial2_c": "Paris",
    "testimonial3_q": "Black Events ni za ajabu kweli. Hazifanani na app, bali zaidi kama mwaliko wa kuingia chumba bora zaidi cha jiji.",
    "testimonial3_n": "Sofia",
    "testimonial3_c": "Dubai",
    "testimonial4_q": "Jiji jipya kwa ajili ya kazi, sikumjua mtu. Baada ya wiki mbili nina kundi halisi la marafiki — yote yalitokana na uamuzi wa saa moja jioni kwamba sitaki kubaki ndani.",
    "testimonial4_n": "Daniel",
    "testimonial4_c": "Berlin",
    "testimonial5_q": "Ni ya haraka, ni nzuri, na kweli inaheshimu wakati wako. Ping, Match, kukutana — kama ilivyoahidiwa hasa.",
    "testimonial5_n": "Aisha",
    "testimonial5_c": "London",
    "testimonial6_q": "Travel Mode ni kama msimbo wa udanganyifu. Nafungua 2NIGHT mara tu ninapotua na usiku wa eneo hilo tayari unaningoja.",
    "testimonial6_n": "Tomás",
    "testimonial6_c": "New York",
    "safety_kicker": "Usalama",
    "safety_title": "Kutana na watu kwa njia ya busara.",
    "safety_lead": "2NIGHT imejengwa kwa usiku wa kawaida na halisi unaotokea papo hapo. Tabia chache rahisi huufanya uwe wa kufurahisha — na kukuweka ukiwa na udhibiti unapokutana na mtu mpya.",
    "safety_t1_t": "Kutana mahali pa umma",
    "safety_t1_b": "Kwa mkutano wa kwanza, chagua mahali penye watu wengi na mwanga wa kutosha — baa, mkahawa, au sehemu maarufu. Baki mahali pa umma hadi ujihisi vizuri kweli, na usiende mahali pa faragha na mtu uliyemfahamu sasa hivi.",
    "safety_t2_t": "Mwambie rafiki mipango yako",
    "safety_t2_b": "Mjulishe mtu unayemwamini unaenda wapi, unakutana na nani, na unatarajia kurudi lini. Shiriki naye eneo lako la moja kwa moja usiku huo na umtaarifu baadaye.",
    "safety_t3_t": "Panga usafiri wako mwenyewe",
    "safety_t3_b": "Fika na rudi kwa masharti yako mwenyewe. Weka simu yako ikiwa na chaji, jua jinsi utakavyorudi nyumbani, na uko huru kuondoka wakati wowote unaotaka — bila maelezo yoyote.",
    "safety_t4_t": "Usitume pesa kamwe",
    "safety_t4_b": "Usitume pesa, kadi za zawadi, au crypto kwa mtu uliyemkutana naye kwenye app, hadithi iwe yoyote ile. Maombi ya pesa taslimu, msaada wa kifedha, au “vidokezo” vya uwekezaji ni ulaghai wa kawaida — simama na ripoti.",
    "safety_t5_t": "Amini hisia zako za ndani",
    "safety_t5_b": "Kama kitu kinaonekana hakiko sawa, mara nyingi kweli hakiko sawa. Hudaiwi muda wako na mtu yeyote. Maliza mazungumzo, ondoka kwenye mkutano, au mpigie rafiki simu — hakuna sababu mbaya ya kuondoka.",
    "safety_t6_t": "Ripoti na zuia",
    "safety_t6_b": "Yeyote anayekufanya ujisikie vibaya anaweza kuzuiwa na kuripotiwa kwa mguso mmoja. Timu yetu hukagua ripoti — kuripoti tabia mbaya hufanya usiku wote kuwa salama zaidi kwa kila mtu.",
    "safety_t7_t": "Linda taarifa zako binafsi",
    "safety_t7_b": "Endelea kuzungumza ndani ya 2NIGHT hadi umwamini mtu. Usishiriki anwani ya nyumbani, mahali pa kazi, taarifa za kifedha, au nyaraka zako, na uwe makini na picha zinazoonyesha hasa mahali unapoishi.",
    "safety_t8_t": "Uko na udhibiti",
    "safety_t8_b": "Wewe ndiye unaamua lini uko mtandaoni, eneo lako linafika umbali gani, na unashiriki nini. Hatufanyi ukaguzi wa historia, kwa hivyo busara yako mwenyewe huja kwanza daima.",
    "safety_help_t": "Wakati wa dharura, omba msaada.",
    "safety_help_p": "Iwapo utahisi hauko salama au unatishwa, wasiliana kwanza na huduma za dharura za eneo lako. Ili kuripoti mtu au jambo kwetu, tumia barua pepe kwa timu yetu — tunasoma kila ujumbe.",
    "cookie_text": "Tunatumia vidakuzi ili 2NIGHT iendelee kufanya kazi na kuelewa jinsi tovuti inavyotumika.",
    "cookie_accept": "Kubali",
    "cookie_decline": "Muhimu tu",
    "cookie_privacy_link": "Faragha na Vidakuzi",
    "cookie_aria": "Idhini ya vidakuzi",
    "founders_title": "Marafiki wawili, wazo moja sugu",
    "founders_role": "Mwanzilishi na Mshirika · Uswisi",
    "founders_p1": "Hugo na Jeric, marafiki wawili kutoka Uswisi, waligonga ukuta uleule kila mara: miji iliyojaa watu, gumzo za vikundi zilizojaa „tukutane karibuni“, lakini usiku huu hakuna mtu aliyetoka nje kweli.",
    "founders_p2": "Hugo, mwanzilishi, anaandika msimbo. Jeric, mshirika wake, anaendesha mradi na kuunda matumizi. Kutoka meza ya jikoni nchini Uswisi hadi pale ulipo usiku huu — hiyo ndiyo hadithi nzima.",
    "founders_sign": "— Hugo na Jeric · Uswisi",
    "about_cta_t": "Toka nje usiku huu.",
    "about_cta_p": "Mji tayari unaenda kasi. Jiunge nao.",
