    "gal_profile_s": "Wewe, giza linapoingia",
    "tiers_note": "Bei ziko katika USD na zinaweza kutofautiana kulingana na eneo. Mipango ya kulipia hutozwa kupitia Apple App Store na hujifanya upya kiotomatiki hadi ighairiwe — dhibiti au ghairi wakati wowote katika mipangilio yako ya App Store. Tazama Masharti yetu.",
    "auth_login": "Ingia",
    "cg1_b": "Tumia picha zako halisi na maelezo ya kweli. Hakuna profaili bandia, kujifanya mtu mwingine, au catfishing.",
    "cg1_t": "Kuwa halisi",
    "cg2_b": "Hakuna unyanyasaji, chuki, vitisho, au maudhui ya ngono usiyoyaomba. Watendee watu jinsi ungependa kutendewa.",
    "cg2_t": "Kuwa na heshima",
    "cg3_b": "2NIGHT ni kwa watu wazima pekee kabisa. Yeyote asiye na umri unaostahili huondolewa mara moja.",
    "cg3_t": "Miaka 18 na zaidi pekee",
    "cg4_b": "Hakuna kuuza, escorting, kuomba-omba, ulaghai, au kuwaomba wanachama pesa, zawadi, au crypto.",
    "cg4_t": "Hakuna pesa, hakuna biashara",
    "cg5_b": "Usimrekodi au kumshiriki mtu yeyote bila ridhaa, hakuna doxxing, hakuna kushiriki taarifa za faragha.",
    "cg5_t": "Dumisha ridhaa",
    "cg6_b": "Zuia na ripoti yeyote anayevuka mpaka. Timu yetu hukagua kila ripoti — kuripoti hufanya usiku uwe salama.",
    "cg6_t": "Ripoti lisilo sahihi",
    "cg_contact": "Umeona jambo zito? Tutumie barua pepe — tunasoma kila ujumbe.",
    "cg_kicker": "Jamii",
    "cg_lead": "2NIGHT hufanya kazi tu ikiwa inahisi salama na halisi. Kanuni hizi hufanya usiku uwe mzuri kwa kila mtu — uzivunje na utatolewa.",
    "cg_title": "Miongozo ya Jamii",
    "community_meta": "Miongozo ya Jamii ya 2NIGHT — kanuni zinazofanya usiku uwe salama na halisi.",
    "cta_join": "Jiunge na orodha ya kusubiri",
    "cta_sub2": "Kuwa wa kwanza kuingia. Wanachama wa kwanza wanamiliki usiku — bila malipo.",
    "disc_f1_b": "Weka hali yako na jiji litaona uko huru usiku huu. Wewe unadhibiti nani, umbali gani, na kwa muda gani.",
    "disc_f1_t": "Kuwa hai kwa mguso mmoja",
    "disc_f2_b": "Watu halisi karibu nawe, huru sasa hivi, wanaotaka kitu kile kile. Hakuna kuteleza bila mwisho kuelekea siku fulani.",
    "disc_f2_t": "Tonight Feed",
    "disc_f3_b": "Hamu ya pande zote mbili hufungua mazungumzo. Panga mpango na ukutane — ana kwa ana, usiku huo huo.",
    "disc_f3_t": "Tuma ping, fanya match, kutana",
    "disc_f4_b": "Kutoka mtaa wako hadi jiji zima. Uanachama wako huamua usiku unaweza kufika umbali gani.",
    "disc_f4_t": "Eneo lako, usiku wako",
    "disc_feat_t": "Imejengwa kukutoa nje ya mlango",
    "disc_kicker": "Gundua",
    "disc_lead": "Programu ya uchumba wa usiku mmoja kwa watu wanaoamua saa 1 jioni kwamba wanataka kukutana na mtu — usiku huu, si kesho.",
    "disc_p1": "Programu nyingi za uchumba hupanga kahawa wiki tatu mbele. 2NIGHT imejengwa kwa ajili ya saa kati ya sasa na saa 8 usiku — kipindi ambacho mipango hutokea kweli. Kuwa hai, ona nani yuko nje karibu nawe, tuma ping, fanya match na kutana.",
    "disc_title": "2NIGHT ni nini?",
    "discover_meta": "Gundua 2NIGHT — programu hii ya uchumba wa usiku mmoja ni nini na inafanyaje kazi.",
    "hero_cta_how": "Ona jinsi inavyofanya kazi",
    "nav_blog": "Blogu",
    "nav_community": "Jamii",
    "nav_discover": "Gundua",
    "nav_join": "Jiunge na orodha ya kusubiri",
    "sec1_b": "Wewe unaamua wakati uko hai, umbali wa eneo lako, na unachoshiriki. Toka mtandaoni na utatoweka.",
    "sec1_t": "Daima uko na udhibiti",
    "sec2_b": "Watu walio ndani ya eneo na hadhira unayochagua pekee ndio wanaoweza kukuona, na hilo tu ukiwa hai.",
    "sec2_t": "Ya faragha kwa chaguo-msingi",
    "sec3_b": "Imefichwa wakati wa usafirishaji, ufikiaji umewekewa mipaka mikali, na haiuzwi kamwe. Soma maelezo katika Sera yetu ya Faragha.",
    "sec3_t": "Data yako, imelindwa",
    "sec4_b": "Yeyote anayekufanya ujisikie vibaya anaweza kuzuiwa na kuripotiwa papo hapo. Timu yetu hukagua kila ripoti.",
    "sec4_t": "Zuia na ripoti kwa mguso",
    "sec_contact": "Maswali kuhusu usalama au faragha? Tuma barua pepe support@2night.co.",
    "sec_kicker": "Uaminifu na Usalama",
    "sec_lead": "Kukutana na watu wapya kunapaswa kuhisi cha kusisimua, si cha hatari. Hivi ndivyo 2NIGHT inavyokulinda wewe na data yako.",
    "sec_note": "Muhimu: 2NIGHT haifanyi ukaguzi wa nyuma au wa utambulisho. Kutana mahali pa umma, mwambie rafiki, na amini hisia zako — ona Vidokezo vyetu vya Usalama.",
    "sec_title": "Usalama wako, kwa muundo.",
    "security_meta": "Uaminifu na Usalama katika 2NIGHT — jinsi tunavyokulinda wewe na data yako.",
