    "waitlist_title2": "Faça a 2NIGHT acontecer.",
    "waitlist_perk": "Os 20 primeiros ganham Platinum grátis por um ano — os próximos 200 ganham Gold. Avisaremos assim que a 2NIGHT estiver pronta.",
    "waitlist_perk_short": "Os 20 primeiros: Platinum grátis por um ano — os próximos 200: Gold.",
