    "gal_profile_s": "Você, depois do anoitecer",
    "tiers_note": "Preços em USD e podem variar por região. Os planos pagos são cobrados pela App Store da Apple e renovam automaticamente até o cancelamento — gerencie ou cancele quando quiser nas configurações da App Store. Veja nossos Termos.",
    "auth_login": "Entrar",
    "cg1_b": "Use suas próprias fotos e dados reais. Nada de perfis falsos, falsidade ideológica ou catfishing.",
    "cg1_t": "Seja real",
    "cg2_b": "Nada de assédio, ódio, ameaças ou conteúdo explícito não solicitado. Trate as pessoas como você gostaria de ser tratado.",
    "cg2_t": "Seja respeitoso",
    "cg3_b": "O 2NIGHT é estritamente para adultos. Qualquer menor de idade é removido imediatamente.",
    "cg3_t": "Somente maiores de 18",
    "cg4_b": "Nada de vendas, acompanhantes, aliciamento, golpes nem pedir dinheiro, presentes ou cripto a outros membros.",
    "cg4_t": "Sem dinheiro, sem negócios",
    "cg5_b": "Não grave nem compartilhe ninguém sem consentimento, nada de doxxing, nada de compartilhar informações privadas.",
    "cg5_t": "Sempre com consentimento",
    "cg6_b": "Bloqueie e denuncie quem ultrapassar os limites. Nossa equipe analisa cada denúncia — denunciar mantém a noite segura.",
    "cg6_t": "Denuncie o que está errado",
    "cg_contact": "Viu algo grave? Escreva pra gente — lemos cada mensagem.",
    "cg_kicker": "Comunidade",
    "cg_lead": "O 2NIGHT só funciona se for seguro e real. Essas regras mantêm a noite boa pra todo mundo — quem quebrar, está fora.",
    "cg_title": "Diretrizes da comunidade",
    "community_meta": "Diretrizes da comunidade do 2NIGHT — as regras que mantêm a noite segura e real.",
    "disc_f1_b": "Defina seu status e a cidade vê que você está livre hoje à noite. Você controla quem, até onde e por quanto tempo.",
    "disc_f1_t": "Fique ao vivo com um toque",
    "disc_f2_b": "Pessoas reais perto de você, livres agora mesmo, querendo a mesma coisa. Sem deslizar sem fim rumo a um algum dia.",
    "disc_f2_t": "O Tonight Feed",
    "disc_f3_b": "O interesse mútuo abre um chat. Combinem um plano e se encontrem — pessoalmente, na mesma noite.",
    "disc_f3_t": "Ping, match, encontro",
    "disc_f4_b": "Da sua rua à cidade inteira. Sua assinatura define até onde a noite pode chegar.",
    "disc_f4_t": "Seu raio, sua noite",
    "disc_feat_t": "Feito pra te colocar pra fora de casa",
    "disc_kicker": "Descubra",
    "disc_lead": "O app de encontros de uma noite para quem decide às 19h que quer conhecer alguém — hoje à noite, não amanhã.",
    "disc_p1": "A maioria dos apps de namoro marca um café pra daqui a três semanas. O 2NIGHT foi feito pras horas entre agora e as 2 da manhã — a janela em que os planos realmente acontecem. Fique ao vivo, veja quem está por perto, dê um ping, dê match e se encontrem.",
    "disc_title": "O que é o 2NIGHT?",
    "discover_meta": "Descubra o 2NIGHT — o que é o app de encontros de uma noite e como ele funciona.",
