    "sec3_b": "Criptografados em trânsito, com acesso estritamente limitado e nunca vendidos. Leia os detalhes na nossa Política de Privacidade.",
    "sec3_t": "Seus dados, protegidos",
    "sec4_b": "Qualquer pessoa que te deixe desconfortável pode ser bloqueada e denunciada na hora. Nossa equipe analisa cada denúncia.",
    "sec4_t": "Bloqueie e denuncie com um toque",
    "sec_contact": "Dúvidas sobre segurança ou privacidade? Escreva para support@2night.co.",
    "sec_kicker": "Confiança e segurança",
    "sec_lead": "Conhecer gente nova deveria ser empolgante, não arriscado. Veja como o 2NIGHT protege você e seus dados.",
    "sec_note": "Importante: o 2NIGHT não faz verificações de antecedentes nem de identidade. Encontrem-se em local público, avise um amigo e confie no seu instinto — veja nossas dicas de segurança.",
    "sec_title": "Sua segurança, desde o projeto.",
