    "pc_kicker": "Ang iyong privacy",
    "pc_title": "Ang iyong mga pagpipilian sa privacy",
    "pc_lead": "Ikaw ang may kontrol sa iyong data sa 2NIGHT. Narito kung paano gamitin ang iyong mga pagpipilian sa privacy, anumang oras.",
    "pc1_t": "I-access ang iyong data",
    "pc1_b": "Humiling ng kopya ng personal na data na hawak namin tungkol sa iyo, at ipapadala namin ito sa iyo.",
    "pc2_t": "Burahin ang iyong account at data",
    "pc2_b": "Burahin ang iyong account anumang oras sa Settings → Account → Delete account, o mag-email sa amin. Buburahin namin ang iyong data, alinsunod sa anumang legal na pagpapanatili.",
    "pc3_t": "Mag-opt out sa marketing",
    "pc3_b": "I-off ang mga promotional na email at push notification sa Settings → Notifications, o gamitin ang unsubscribe link sa anumang email.",
    "pc4_t": "Hindi ibinebenta o ibinabahagi",
    "pc4_b": "Hindi namin kailanman ibinebenta ang iyong personal na data at hindi kailanman ibinabahagi para sa cross-context behavioural advertising — kaya wala kang kailangang i-opt out.",
    "pc5_t": "Pamahalaan ang cookies",
    "pc5_b": "Baguhin ang iyong mga kagustuhan sa cookie at pagsubaybay anumang oras sa pamamagitan ng cookie banner o ng mga setting ng iyong browser.",
    "pc6_t": "Lokasyon at mga pahintulot",
    "pc6_b": "Kontrolin ang access sa lokasyon, camera at notification mula sa mga setting ng iyong device, at bawiin ang alinman sa mga ito kahit kailan mo gusto.",
    "pc_note": "Ang mga pagpipiliang ito ay available sa lahat, saanman — kasama ang mga karapatang ipinagkakaloob ng GDPR (EU/UK) at ng CCPA/CPRA (California). Hindi ka namin kailanman sisingilin o pakikitunguhan nang iba dahil sa paggamit ng mga ito.",
    "pc_contact": "Upang gamitin ang isang karapatan sa privacy, mag-email sa privacy@2night.co — tumutugon kami sa loob ng 30 araw.",
    "footer_privacy_choices": "Ang iyong mga pagpipilian sa privacy",
