    "gal_tonight_t": "Tonight",
    "gal_tonight_s": "Sino ang live, ngayon na",
    "gal_plans_t": "Plans",
    "gal_plans_s": "Sumali sa isang bagay ngayong gabi",
    "gal_chat_t": "Chat",
    "gal_chat_s": "Laktawan ang small talk",
    "gal_matches_t": "Matches",
    "gal_matches_s": "Mutual, hindi random",
    "gal_membership_t": "Membership",
    "gal_membership_s": "Silver · Gold · Platinum",
    "gal_profile_t": "Profile",
    "gal_profile_s": "Ikaw, pagdilim",
    "tiers_note": "Ang mga presyo ay nasa USD at maaaring mag-iba depende sa rehiyon. Ang mga bayad na plano ay sinisingil sa pamamagitan ng Apple App Store at awtomatikong nagre-renew hangga't hindi kinakansela — pamahalaan o kanselahin anumang oras sa iyong App Store settings. Tingnan ang aming Terms.",
    "auth_login": "Mag-log in",
    "cg1_b": "Gamitin ang sarili mong mga litrato at totoong detalye. Walang pekeng profile, panggagaya, o catfishing.",
    "cg1_t": "Maging totoo",
    "cg2_b": "Walang harassment, pang-aapi, pananakot, o hindi hiniling na explicit na content. Tratuhin ang iba gaya ng gusto mong itrato sa iyo.",
    "cg2_t": "Maging magalang",
    "cg3_b": "Ang 2NIGHT ay para lang sa mga adulto. Ang sinumang menor de edad ay agad na aalisin.",
    "cg3_t": "18 pataas lang",
    "cg4_b": "Walang pagbebenta, escorting, pang-aakit, scam, o paghingi ng pera, regalo, o crypto sa mga miyembro.",
    "cg4_t": "Walang pera, walang negosyo",
    "cg5_b": "Walang pag-record o pagbabahagi ng kahit sino nang walang pahintulot, walang doxing, walang pagbabahagi ng pribadong impormasyon.",
    "cg5_t": "Panatilihing may pahintulot",
    "cg6_b": "I-block at i-report ang sinumang lumalagpas sa linya. Sinusuri ng aming team ang bawat report — ang pag-flag ay nagpapanatiling ligtas ng gabi.",
    "cg6_t": "I-report ang mali",
    "cg_contact": "May nakita kang seryoso? I-email kami — binabasa namin ang bawat mensahe.",
    "cg_kicker": "Komunidad",
    "cg_lead": "Gumagana lang ang 2NIGHT kung pakiramdam ay ligtas at totoo. Ang mga panuntunang ito ang nagpapanatiling maganda ng gabi para sa lahat — labagin mo at lalabas ka.",
    "cg_title": "Mga Alituntunin ng Komunidad",
    "community_meta": "Mga Alituntunin ng Komunidad ng 2NIGHT — ang mga panuntunang nagpapanatiling ligtas at totoo ng gabi.",
    "cta_join": "Sumali sa waitlist",
    "cta_sub2": "Mauna kang makapasok. Ang pinakaunang mga miyembro ang nagmamay-ari ng gabi — libre.",
    "disc_f1_b": "Itakda ang iyong status at makikita ng buong lungsod na libre ka ngayong gabi. Ikaw ang kumokontrol kung sino, gaano kalayo, at gaano katagal.",
    "disc_f1_t": "Mag-live sa isang tap",
    "disc_f2_b": "Totoong mga tao malapit sa iyo, libre ngayon, gustong-gusto ang parehong bagay. Walang walang-katapusang pag-swipe para sa balang araw.",
    "disc_f2_t": "Tonight Feed",
    "disc_f3_b": "Ang magkatugmang interes ay nagbubukas ng chat. Gumawa ng plano at magkita — personal, sa parehong gabi.",
    "disc_f3_t": "Ping, match, kita",
    "disc_f4_b": "Mula sa iyong kalye hanggang sa buong lungsod. Ang iyong membership ang nagtatakda kung gaano kalayo aabot ang gabi.",
    "disc_f4_t": "Iyong radius, iyong gabi",
    "disc_feat_t": "Ginawa para mailabas ka sa pinto",
    "disc_kicker": "Tuklasin",
    "disc_lead": "Ang one-night dating app para sa mga taong nagdedesisyon nang alas-7 ng gabi na gusto nilang makakilala ng iba — ngayong gabi, hindi bukas.",
    "disc_p1": "Karamihan ng dating apps ay nag-iiskedyul ng kape tatlong linggo mula ngayon. Ginawa ang 2NIGHT para sa mga oras sa pagitan ng ngayon at alas-2 ng madaling-araw — ang panahong talagang nangyayari ang mga plano. Mag-live, tingnan kung sino ang nasa labas malapit sa iyo, mag-ping, mag-match at magkita.",
    "disc_title": "Ano ang 2NIGHT?",
    "discover_meta": "Tuklasin ang 2NIGHT — ano ang one-night dating app at paano ito gumagana.",
    "hero_cta_how": "Tingnan kung paano ito gumagana",
    "nav_blog": "Blog",
    "nav_community": "Komunidad",
